window.__Q=window.__Q||{};window.__Q["tcm/4/A2"]=[{"q":"患者腰痛脚软，身半以下常有冷感，少腹拘急，小便不利或小便反多，入夜尤甚，阳痿早泄，舌淡而胖，脉虚弱，尺脉沉细，以及痰饮，水肿，消渴，脚气，转胞等，治疗宜用的方剂是","o":["左归丸","右归丸","大补阴丸","肾气丸","六味地黄丸"],"a":3,"e":"肾气丸以干地黄为君，配山药、山茱萸补益肾中精气，佐桂枝、附子温阳化气，泽泻、茯苓、丹皮渗湿泄浊，补中有泻，温补肾阳而化生肾气，主治肾阳不足之腰痛脚软、下半身冷感、小便不利或反多及痰饮水肿消渴等。左归丸纯补肾阴、填精益髓，无温化水液之力；右归丸温阳填精之力峻，主治命门火衰而少治水饮；六味地黄丸滋养肾阴，主治腰膝酸软、盗汗遗精等阴虚之证"},{"q":"患者肢体沉重，怠惰嗜卧，脘腹胀满，舌苔白腻，脉缓。治疗应首选的治法是","o":["燥湿和胃，消痞除满","健脾和胃，行气除满","益气健脾，行气导滞","燥湿运脾，行气和胃","燥湿健脾，和胃止呕"],"a":3,"e":"证属湿滞脾胃，湿困中焦则肢体沉重、怠惰嗜卧、脘腹胀满，苔白腻、脉缓皆为湿象。平胃散以苍术燥湿健脾为君，厚朴行气除满，陈皮理气和胃，甘草调和，燥湿运脾、行气和胃，为治湿滞脾胃之主方，故治法当为燥湿运脾、行气和胃。燥湿和胃、消痞除满偏于和胃降逆，未突出运脾；健脾和胃、行气除满与益气健脾、行气导滞侧重补虚消导，主治脾虚食积；燥湿健脾、和胃止呕则重在止呕，均非本证治法"},{"q":"患者面目俱黄，黄色鲜明，发热口渴，恶心呕吐，脘腹微满，小便短赤，舌苔黄腻，脉滑数有力。治疗应首选的方剂是","o":["甘露消毒丹","栀子柏皮汤","茵陈蒿汤","茵陈四逆汤","三仁汤"],"a":2,"e":"证属阳黄，湿热蕴结肝胆，胆汁外溢则身目鲜黄，热重于湿则发热口渴、小便短赤，苔黄腻、脉滑数有力。茵陈蒿汤以茵陈为君清热利湿退黄，栀子通泄三焦，大黄泻热逐瘀通腑，使湿热从二便而去，为治湿热阳黄之主方。栀子柏皮汤清泄湿热，主治阳黄热重于湿而无腑实者，无大黄攻下之力；甘露消毒丹利湿化浊、清热解毒，主治湿温时疫湿热并重；茵陈四逆汤温阳利湿退黄，主治寒湿阴黄，黄色晦暗；三仁汤宣畅气机、清利湿热，主治湿温初起而无黄疸"},{"q":"患者瘟疫热毒，气血两燔证而见四肢抽搐，发斑疹，舌绛唇焦，脉沉细数。治疗应首选的方剂是","o":["清瘟败毒饮","黄连解毒汤","竹叶石膏汤","犀角地黄汤","普济消毒饮"],"a":0,"e":"证属瘟疫热毒、气血两燔，热毒充斥气分则高热烦渴，入血分则发斑疹、舌绛唇焦，热极生风则四肢抽搐。清瘟败毒饮合白虎汤、犀角地黄汤、黄连解毒汤之意，清热解毒、凉血泻火，气血两清，为治气血两燔之主方。黄连解毒汤仅泻三焦火毒，无凉血散斑之功，主治火毒炽盛而无斑疹；犀角地黄汤专清血分热毒，主治吐衄发斑而气分热不著；普济消毒饮疏风清热、解毒利咽，主治大头瘟头面红肿焮痛；竹叶石膏汤清热生津、益气和胃，主治热病后期气阴两伤"},{"q":"患者心热移于小肠，小便赤涩刺痛，舌红脉数。治疗应首选的方剂是","o":["玉女煎","导赤散","猪苓汤","五苓散","八正散"],"a":1,"e":"心火亢盛，下移小肠，小肠分清泌浊失司则小便赤涩刺痛，舌红、脉数为心火之象。导赤散以生地凉血滋阴、木通清心利水为君，竹叶清心除烦，甘草梢直达茎中而止痛，清心养阴、利水通淋，使心火从小便而出，为治心火移热小肠之主方。八正散清热利水通淋，主治湿热下注之热淋，尿频尿急、溺时涩痛，病在膀胱湿热而非心火；五苓散温阳化气利水，主治膀胱蓄水之小便不利；猪苓汤利水清热养阴，主治水热互结伤阴；玉女煎清胃滋阴，主治胃热阴虚之牙痛"},{"q":"患者，男，65岁。腹痛便秘，手足不温，苔白腻，脉弦紧。下列最为适宜选用的方剂是","o":["大承气汤","大黄附子汤","小承气汤","调胃承气汤","济川煎"],"a":1,"e":"证属寒积里实，寒邪积滞内停，腑气不通则腹痛便秘，阳虚不温四末则手足不温，苔白腻、脉弦紧为寒积之象。大黄附子汤以附子温里散寒，大黄泻下通便，细辛助附子散寒止痛，温里散寒、通便止痛，主治寒积腹痛便秘。大承气汤峻下热结，主治阳明腑实之痞满燥实、潮热谵语；小承气汤轻下热结，主治腑实轻证；调胃承气汤缓下热结，主治燥实而无痞满；济川煎温肾益精、润肠通便，主治肾虚肠燥便秘，均无散寒之力"},{"q":"患者脘腹疼痛，喜温欲按，自利不渴，畏寒肢冷，呕吐，不欲饮食，舌淡苔白，脉沉细。辨证为脾胃虚寒证。方剂宜选用","o":["吴茱萸汤","小建中汤","大建中汤","理中丸","四逆汤"],"a":3,"e":"证属脾胃虚寒，中焦阳气不足，寒自内生，胃失和降则呕吐、不欲饮食，脾失运化则自利不渴，舌淡苔白、脉沉细为虚寒之象。理中丸以干姜温中祛寒为君，人参补气健脾，白术健脾燥湿，甘草益气和中，温中祛寒、补气健脾，为治脾胃虚寒之主方。吴茱萸汤温中补虚、降逆止呕，主治肝胃虚寒、浊阴上逆之头痛、吐涎沫；小建中汤温中补虚、和里缓急，主治中焦虚寒之腹中挛急作痛；大建中汤温中补虚、降逆止痛，主治中阳衰微、阴寒内盛之心胸大痛；四逆汤回阳救逆，主治心肾阳虚之四肢厥逆"},{"q":"患者恶寒发热，无汗，头痛，鼻塞，咳嗽痰白，胸脘满闷，倦怠无力，气短懒言，舌苔白，脉弱。治疗当首选的方剂是","o":["小青龙汤","止嗽散","败毒散","再造散","参苏饮"],"a":4,"e":"证属气虚外感风寒，兼有痰湿，气虚则倦怠无力、气短懒言、脉弱，风寒束表则恶寒发热无汗头痛，肺气不宣则咳嗽痰白、胸脘满闷。参苏饮以人参、甘草益气扶正，紫苏、葛根解表散寒，陈皮、半夏、茯苓理气化痰，益气解表、理气化痰，主治气虚外感风寒兼痰湿者。败毒散虽亦益气解表，但侧重疏散风寒湿邪，主治气虚外感风寒湿之憎寒壮热、无汗，理气化痰之力不足；小青龙汤解表散寒、温肺化饮，主治外寒内饮之喘咳痰稀；止嗽散疏风润肺、止咳化痰，主治风邪犯肺之咳嗽迁延；再造散助阳益气解表，主治阳虚外感"},{"q":"小蓟饮子的组成药物中无","o":["生地黄","大黄","淡竹叶","蒲黄","山栀子"],"a":1,"e":"小蓟饮子由生地黄、小蓟、藕节、蒲黄、滑石、淡竹叶、山栀子、当归、甘草、荷叶组成，功能凉血止血、利水通淋，主治热结下焦之血淋、尿血。方中大黄并非组成部分，大黄攻下泄热、凉血逐瘀，多用于血热妄行之吐衄或热结便秘，如泻心汤、桃核承气汤。生地黄凉血养阴为君，小蓟、藕节、蒲黄凉血止血，淡竹叶、山栀子清热利水，滑石通淋，皆为本方药物，故无大黄"},{"q":"症见两胁作痛，头痛目眩，口燥咽干，神疲食少，月经不调，乳房胀痛，脉虚而弦者，首选治疗方剂是","o":["归脾汤","龙胆泻肝汤","柴胡疏肝散","温经汤","逍遥散"],"a":4,"e":"证属肝郁血虚脾弱，肝失疏泄则两胁作痛、乳房胀痛、脉弦，血虚不能上荣则头痛目眩、口燥咽干，脾弱则神疲食少。逍遥散以柴胡疏肝解郁为君，当归、白芍养血柔肝，白术、茯苓健脾益气，薄荷疏肝，甘草调和，疏肝解郁、养血健脾，为本证主方。柴胡疏肝散疏肝理气、活血止痛，主治肝气郁结之胁肋胀痛，无养血健脾之功；归脾汤益气补血、健脾养心，主治心脾两虚之心悸失眠；龙胆泻肝汤清肝胆实火、利肝经湿热，主治口苦胁痛、阴肿阴痒；温经汤温经散寒、养血祛瘀，主治冲任虚寒之月经不调"},{"q":"患者正值夏月感寒，刻诊见恶寒发热，头疼身痛，腹痛吐泻，胸脘痞闷，舌苔白腻，脉浮，临床辨证为","o":["暑湿证","阳暑","阴暑","暑温证","湿温证"],"a":2,"e":"夏月乘凉饮冷，外感风寒、内伤湿滞，故见恶寒发热、头疼身痛、腹痛吐泻、胸脘痞闷，苔白腻、脉浮，此即阴暑，乃暑月受寒湿所致，治宜祛暑解表、化湿和中，香薷散主之。阳暑为暑热伤津耗气，症见高热烦渴、大汗脉洪，与本案寒湿表现迥异；暑湿证、暑温证以暑热兼湿或热入心营为主，必有明显热象；湿温证起病缓慢、身热不扬、午后热甚，病程较长，均非夏月感寒之阴暑"},{"q":"以恶寒发热，无汗而喘，脉浮紧为辨证要点的方剂是","o":["桂枝汤","小青龙汤","麻黄汤","大青龙汤","败毒散"],"a":2,"e":"麻黄汤由麻黄、桂枝、杏仁、甘草组成，功能发汗解表、宣肺平喘，主治外感风寒表实证，以恶寒发热、无汗而喘、脉浮紧为辨证要点，麻黄发汗解表、宣肺平喘为君，桂枝助其发汗，杏仁降肺气，甘草调和。桂枝汤解肌发表、调和营卫，辨证要点为恶风、发热、汗出、脉浮缓，属表虚；小青龙汤解表散寒、温肺化饮，要点为恶寒发热、喘咳痰多清稀；大青龙汤发汗解表、清热除烦，要点为不汗出而烦躁；败毒散益气解表，主治气虚外感风寒湿"},{"q":"患者膈下瘀阻气滞，形成痞块，痛处不移，卧则腹坠。治疗应首选的方剂是","o":["失笑散","血府逐瘀汤","桃核承气汤","复元活血汤","膈下逐瘀汤"],"a":4,"e":"瘀血积于膈下，气机阻滞，故成痞块、痛处不移，卧则腹坠，膈下逐瘀汤以当归、川芎、桃仁、红花、五灵脂、丹皮、赤芍等活血祛瘀，配乌药、香附、枳壳、甘草行气止痛，活血祛瘀、行气止痛，专为膈下瘀阻气滞而设。血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀之胸痛、头痛、内热瞀闷，病位在胸；桃核承气汤破血下瘀，主治下焦蓄血之少腹急结、其人如狂；复元活血汤活血祛瘀、疏肝通络，主治跌打损伤、瘀血留于胁下；失笑散活血止痛，主治瘀血停滞之心腹剧痛，均无行气消痞之力"},{"q":"患者，女，66岁。有慢性胃炎病史，现主要症状体征有：胃脘疼痛，手足不温，喜食热食，大便溏泄，四肢无力，嗜卧，舌淡苔白，脉沉。宜选择下列哪方治疗","o":["理中丸","小建中汤","桂枝人参汤","阳和汤","四逆汤"],"a":0,"e":"胃脘疼痛、喜食热食、手足不温、大便溏泄、四肢无力嗜卧、舌淡苔白脉沉，皆脾胃虚寒、运化失司之象。理中丸温中祛寒、补气健脾，干姜温中散寒，人参、白术、甘草健脾益气，中焦得温则疼痛止、运化复，故为首选。小建中汤温中补虚、和里缓急，主治中焦虚寒之腹中拘急疼痛、喜温喜按，兼见虚烦；桂枝人参汤温中解表，主治脾胃虚寒兼外感表证之协热利；阳和汤温阳补血、散寒通滞，主治阴疽漫肿无头；四逆汤回阳救逆，主治心肾阳虚、四肢厥逆、脉微欲绝"},{"q":"患者反复自汗出，夜卧尤甚，心悸惊惕，气短烦倦，舌嫩红，脉细弱者。治宜选用","o":["桂枝汤","牡蛎散","玉屏风散","当归六黄汤","酸枣仁汤"],"a":1,"e":"自汗夜卧尤甚、心悸惊惕、气短烦倦、舌嫩红、脉细弱，为体虚卫外不固、阴液外泄之心悸自汗证。牡蛎散以煅牡蛎敛阴止汗为君，黄芪益气固表，麻黄根止汗，浮小麦养心敛汗，益气固表、敛阴止汗，主治自汗、盗汗。玉屏风散益气固表止汗，主治表虚自汗、易感风邪，无敛阴及治心悸之功；当归六黄汤滋阴泻火、固表止汗，主治阴虚火旺之盗汗发热、面赤心烦；桂枝汤解肌发表、调和营卫，主治外感风寒表虚之汗出恶风；酸枣仁汤养血安神、清热除烦，主治肝血不足之虚烦不眠"},{"q":"患者身热口渴，咽痛颐肿，小便短赤，或泄泻淋浊，舌苔黄腻，脉濡数。治疗应首选的治法是","o":["利湿化浊，清热凉血","利湿化浊，清热泻火","利湿化浊，清热解毒","利尿通淋，清热解毒","祛风除湿，清热解毒"],"a":2,"e":"证属湿温时疫、湿热并重，湿热蕴结则身热口渴，上攻则咽痛颐肿，下注则小便短赤、泄泻淋浊，苔黄腻、脉濡数。甘露消毒丹以滑石、茵陈、黄芩清热利湿为君，石菖蒲、藿香、白蔻仁化浊，连翘、薄荷、贝母等清热解毒利咽，利湿化浊、清热解毒，主治湿温时疫。利尿通淋、清热解毒偏治湿热淋证，病在下焦膀胱；祛风除湿、清热解毒主治风湿痹痛或疮疡；利湿化浊、清热凉血主治热入血分之斑疹吐衄；利湿化浊、清热泻火侧重清气分实热，均非湿温时疫之治法"},{"q":"症见肠鸣腹痛，大便泄泻，泻必腹痛，泻后痛缓，舌苔薄白，脉两关不调，左弦而右缓者，首选治疗方剂是","o":["理中丸","参苓白术散","归脾汤","痛泻要方","逍遥散"],"a":3,"e":"泻必腹痛、泻后痛缓、脉左弦右缓，为肝郁脾虚、肝脾不和之痛泻，肝气郁滞则脉弦，脾虚湿盛则右关缓。痛泻要方以白术健脾燥湿为君，白芍柔肝缓急止痛，陈皮理气醒脾，防风散肝舒脾，补脾柔肝、祛湿止泻，为治痛泻之主方。理中丸温中祛寒，主治脾胃虚寒之自利不渴、腹痛喜温；参苓白术散益气健脾、渗湿止泻，主治脾虚湿盛之泄泻、体倦乏力，无柔肝之功；归脾汤益气补血、健脾养心，主治心脾两虚；逍遥散疏肝解郁、养血健脾，主治肝郁血虚脾弱之胁痛、月经不调，不以止泻为主"},{"q":"患者，男，58岁。有慢支炎病史。因气温突降，受凉感冒2天，现恶寒发热，无汗，头身疼痛，喘咳，痰多清稀，晚上不能平卧，舌苔白滑，脉浮。可用下列何方加味治疗","o":["败毒散","九味羌活汤","小青龙汤","香苏散","葱豉桔梗汤"],"a":2,"e":"素有慢支炎，复感风寒，外寒束表则恶寒发热、无汗、头身疼痛、脉浮，内伏水饮被寒邪触动则喘咳痰多清稀、不能平卧、苔白滑。小青龙汤以麻黄、桂枝解表散寒，干姜、细辛温肺化饮，半夏降逆，五味子、白芍敛肺和营，解表散寒、温肺化饮，主治外寒内饮之咳喘。九味羌活汤解表散寒、祛湿清热，主治外感寒湿兼里热之口苦微渴；败毒散益气解表，主治气虚外感风寒湿；香苏散疏风散寒、理气和中，主治外感风寒兼气滞胸闷；葱豉桔梗汤疏风清热，主治风热感冒"},{"q":"患者身热夜甚，神烦少寐，斑疹隐隐，舌绛而干，脉细数。治疗应首选的方剂是","o":["清营汤","竹叶石膏汤","清暑益气汤","青蒿鳖甲汤","白虎加人参汤"],"a":0,"e":"热入营分，营阴受损则身热夜甚、舌绛而干，热扰心神则神烦少寐，热郁营络则斑疹隐隐，脉细数。清营汤以水牛角清解营分之热毒为君，生地、玄参、麦冬清热养阴，银花、连翘、竹叶透热转气，黄连清心解毒，清营解毒、透热养阴，主治热入营分证。白虎加人参汤清热生津，主治气分热盛之大热、大汗、大渴、脉洪大；青蒿鳖甲汤养阴透热，主治温病后期邪伏阴分之夜热早凉、热退无汗；竹叶石膏汤清热生津、益气和胃，主治热病后气阴两伤；清暑益气汤清暑益气、养阴生津，主治暑热耗气伤津"},{"q":"患者口眼斜，舌强不能言语，手足不能运动，风邪散见，不拘一经。治疗首选的方剂是","o":["大秦艽汤","小活络丹","镇肝熄风汤","地黄饮子","牵正散"],"a":0,"e":"风邪中经络，散见不拘一经，故见口眼㟀斜、舌强不能言、手足不能运动而无神志昏迷。大秦艽汤以秦艽为君祛风通络，配羌活、独活、防风等祛风，归、芎、地、芍养血活血，黄芩、石膏清热，疏风清热、养血活血，主治风邪初中经络。牵正散祛风化痰、通络止痉，主治风痰阻络之口眼㟀斜，无手足不用；小活络丹祛风除湿、化痰通络，主治中风后手足不仁、关节疼痛；镇肝熄风汤镇肝熄风、滋阴潜阳，主治肝阳上亢、气血逆乱之类中风；地黄饮子滋肾阴、补肾阳、开窍化痰，主治下元虚衰之瘖痱"},{"q":"患者适逢暑日，乘凉饮冷，症见恶寒发热，头疼身痛，腹痛吐泻，胸脘痞闷，舌苔白腻，脉浮。此病证的治法是","o":["清暑益气，养阴生津","祛暑解表，化湿和中","疏风清热，宣肺止咳","清热生津，益气和胃","清暑利湿"],"a":1,"e":"暑月乘凉饮冷，外感风寒、内伤湿滞，故恶寒发热、头疼身痛、腹痛吐泻、胸脘痞闷，苔白腻、脉浮，属阴暑，治宜祛暑解表、化湿和中，香薷散主之，香薷解表散寒、祛暑化湿为君，厚朴行气除满，扁豆健脾化湿。清暑益气、养阴生津主治暑热耗伤气阴之身热多汗、脉虚数；清暑利湿为六一散之法，主治暑湿之身热烦渴、小便不利；疏风清热、宣肺止咳主治风热犯肺之咳嗽咽痛；清热生津、益气和胃主治热病后气阴两伤，均非阴暑治法"},{"q":"患者胸胁满闷，头晕目眩，背部恶寒，晨起吐清涎，舌苔白滑，脉弦滑。治疗应首选的方剂是","o":["十枣汤","苓桂术甘汤","龙胆泻肝汤","柴胡疏肝散","苏子降气汤"],"a":1,"e":"胸胁满闷、头晕目眩、背部恶寒、晨起吐清涎、苔白滑、脉弦滑，为中阳不足、痰饮内停之痰饮证，饮停心下则胸满，上犯清阳则头眩，背部阳虚则恶寒。苓桂术甘汤以茯苓健脾渗湿、桂枝温阳化气为君，白术健脾燥湿，甘草益气和中，温阳化饮、健脾利湿，主治中阳不足之痰饮。十枣汤攻逐水饮，主治水饮停于胸胁之悬饮，咳唾引痛、心下痞硬；苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳；柴胡疏肝散疏肝理气，主治肝郁胁痛；龙胆泻肝汤清肝胆实火湿热，主治口苦、阴肿阴痒，均无温阳化饮之功"},{"q":"患者面色㿠白，身热自汗，大便稀溏，气短乏力，舌质淡，脉大而虚软，治宜选用","o":["玉屏风散","四君子汤","参苓白术散","补中益气汤","八珍汤"],"a":3,"e":"面色㿠白、气短乏力、大便稀溏、舌淡、脉大而虚软为脾胃气虚，身热、自汗为气虚发热、卫外不固，属脾虚气陷、气虚发热证。补中益气汤以黄芪补中益气、升阳固表为君，人参、白术、甘草健脾益气，当归养血，陈皮理气，升麻、柴胡升阳举陷，补中益气、升阳举陷，主治脾胃气虚、气虚发热及脏器脱垂。四君子汤益气健脾，主治脾胃气虚之面色萎白、食少便溏，无升阳及治虚热之功；玉屏风散益气固表止汗，主治表虚自汗；参苓白术散健脾渗湿止泻，主治脾虚湿盛泄泻；八珍汤益气补血，主治气血两虚"},{"q":"妇人经期经停不至，少腹里急，腹满，傍晚发热，手心烦热，唇口干燥，舌质黯红，脉细而涩。治疗应首选的方剂是","o":["温经汤","桂枝茯苓丸","血府逐瘀汤","生化汤","桃核承气汤"],"a":0,"e":"冲任虚寒、瘀血阻滞，经血不通则经停不至、少腹里急腹满，瘀而化热则傍晚发热、手心烦热，津液不布则唇口干燥，舌黯红、脉细涩为瘀血之象。温经汤以吴茱萸、桂枝温经散寒、通行血脉为君，当归、川芎、芍药养血活血，丹皮清虚热，人参、甘草益气健脾，温经散寒、养血祛瘀，主治冲任虚寒、瘀血阻滞之月经不调。生化汤养血祛瘀、温经止痛，专主产后恶露不行、小腹冷痛；桂枝茯苓丸活血化瘀、缓消癥块，主治妇人瘀阻胞宫之癥块；血府逐瘀汤主治胸中血瘀；桃核承气汤破血下瘀，主治下焦蓄血之少腹急结"},{"q":"患者牙痛，齿松牙衄，烦热干渴，舌红苔黄而干。治疗应首选的方剂是","o":["清胃散","泻黄散","黄芩汤","玉女煎","左金丸"],"a":3,"e":"胃热阴虚，胃火上攻则牙痛、齿松牙衄，肾阴不足则烦热干渴，舌红苔黄而干为胃热伤津之象。玉女煎以石膏、知母清胃泻火为君，熟地滋肾养阴，麦冬养阴生津，牛膝引火下行，清胃热、滋肾阴，主治胃热阴虚之牙痛、烦热干渴。清胃散清胃凉血，主治胃火上攻之牙宣出血、牙龈红肿、口气热臭，无滋阴之功；泻黄散泻脾胃伏火，主治脾胃伏火之口疮口臭、烦渴易饥；左金丸清肝泻火、降逆止呕，主治肝火犯胃之胁痛、呕吐吞酸；黄芩汤清热止利，主治少阳阳明合病之下利"},{"q":"患者脘腹胀满，不思饮食，口淡无味，舌苔白厚腻，脉濡。治疗应首选的方剂是","o":["藿香正气散","平胃散","四君子汤","参苓白术散","八珍汤"],"a":1,"e":"湿滞脾胃，运化失司则脘腹胀满、不思饮食、口淡无味，苔白厚腻、脉濡为湿盛之象。平胃散以苍术燥湿健脾为君，厚朴行气除满，陈皮理气和胃，甘草调中，燥湿运脾、行气和胃，主治湿滞脾胃之脘腹胀满、口淡无味。藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞之吐泻、恶寒发热；四君子汤益气健脾，主治脾胃气虚之食少便溏、面色萎白；参苓白术散益气健脾、渗湿止泻，主治脾虚湿盛之泄泻；八珍汤益气补血，主治气血两虚，均无燥湿除满之功"},{"q":"患者疔疮初起，发热恶寒，疮形如粟，坚硬如钉，舌红苔黄，脉数。首选治疗方剂是","o":["内补黄芪汤","五味消毒饮","大黄牡丹汤","苇茎汤","阳和汤"],"a":1,"e":"疔疮初起，火毒蕴结，故疮形如粟、坚硬如钉，发热恶寒、舌红苔黄、脉数为热毒炽盛之象。五味消毒饮以金银花为君，配野菊花、蒲公英、紫花地丁、天葵子，清热解毒、消散疔疮，主治火毒结聚之疔疮初起。阳和汤温阳补血、散寒通滞，主治阴疽漫肿无头、皮色不变；大黄牡丹汤泻热破瘀、散结消肿，主治肠痈初起之少腹肿痞、按之痛如淋；苇茎汤清肺化痰、逐瘀排脓，主治肺痈之咳吐腥臭脓血；内补黄芪汤补益气血、托毒生肌，主治痈疽溃后气血两虚、久不收口"},{"q":"患者身热肢酸，口渴尿赤，咽痛身黄，舌苔黄腻，脉滑数。治疗应首选的方剂是","o":["甘露消毒丹","五苓散","三仁汤","茵陈蒿汤","八正散"],"a":0,"e":"湿温时疫，湿热并重，郁遏气分则身热肢酸，上攻则咽痛，下注则尿赤，湿热熏蒸则身黄，口渴、苔黄腻、脉滑数皆湿热之象。甘露消毒丹清热利湿、化浊解毒，滑石、茵陈、黄芩清热利湿，石菖蒲、藿香、白蔻仁化湿浊，连翘、贝母、射干等解毒利咽，主治湿温时疫。茵陈蒿汤清热利湿退黄，主治湿热阳黄之黄色鲜明、大便不爽；三仁汤宣畅气机、清利湿热，主治湿温初起之头痛恶寒、身重疼痛、午后身热；八正散清热利水通淋，主治热淋之尿频尿急、溺时涩痛；五苓散温阳化气利水，主治膀胱蓄水"},{"q":"患者恶心呕吐，脘腹胀满，常多自利，舌苔白腻而厚，脉缓。本证的病机是","o":["湿重于热，肝脾不和","内伤湿滞，肝胃不和","痰湿内扰，胆胃不和","脾虚湿盛，胃肠不和","湿阻气滞，脾胃不和"],"a":4,"e":"恶心呕吐、脘腹胀满、自利、苔白腻而厚、脉缓，为湿邪阻滞中焦、气机不畅、脾胃失和之证，湿重于热则苔白腻，故病机为湿阻气滞、脾胃不和，平胃散主之。脾虚湿盛、胃肠不和必有脾虚之面色萎黄、气短乏力、脉虚缓；内伤湿滞、肝胃不和当见胸胁胀痛、吞酸嗳气等肝胃失调；痰湿内扰、胆胃不和常见眩晕、惊悸、失眠；湿重于热、肝脾不和则兼见口苦、胁痛等热象与肝郁，均非本证纯属湿阻气滞之病机"},{"q":"患者头痛，胸痛，呃逆日久，内热瞀闷，舌质黯红，有瘀点，脉紧涩。治疗应首选的方剂是","o":["失笑散","血府逐瘀汤","桃核承气汤","复元活血汤","膈下逐瘀汤"],"a":1,"e":"瘀血阻于胸中，气机不畅，故头痛、胸痛、呃逆日久，瘀而化热则内热瞀闷，舌黯红有瘀点、脉紧涩为血瘀之象。血府逐瘀汤以桃仁、红花、当归、川芎、赤芍活血化瘀为君，柴胡、枳壳、甘草疏肝行气，桔梗开肺气，牛膝引血下行，活血化瘀、行气止痛，主治胸中血瘀之胸痛、头痛、内热瞀闷。膈下逐瘀汤主治膈下瘀阻气滞之痞块、痛处不移；复元活血汤主治跌打损伤、瘀留胁下之痛；桃核承气汤破血下瘀，主治下焦蓄血之少腹急结、其人如狂；失笑散活血止痛，主治瘀血停滞之心腹剧痛"},{"q":"患者平素畏寒肢冷，现便秘腹痛，脐周绞痛，手足不温，苔白不渴，脉沉弦而迟。下列处方最为适合的是","o":["大黄9g，附子12g，细辛3g","大黄10g，芒硝10g，甘遂1g","大黄12g，芒硝12g，炙甘草6g","当归、干姜各5g，附子、人参、甘草各6g，大黄15g，甘草6g","大黄12g，芒硝9g，枳实12g，厚朴24g"],"a":3,"e":"患者平素畏寒肢冷、手足不温、苔白不渴、脉沉弦而迟，为脾阳不足、冷积内停之便秘腹痛，治宜温补脾阳、泻下冷积，温脾汤以附子、干姜温阳散寒，人参、甘草、当归补养气血，大黄泻下冷积，攻下兼温补，故所列之方最宜。大黄附子汤虽亦温里通便，但配细辛而无补虚之力，主治寒积里实之胁下偏痛、脉弦紧，无脾虚见症；含芒硝、甘遂者为峻下逐水之剂，主治水饮内停；含芒硝、炙甘草者为调胃承气汤，主治阳明燥实；含枳实、厚朴者为大承气汤，主治热结痞满燥实，均非冷积脾虚之治"},{"q":"患者胸背掣痛不得息，干呕短气，头痛目眩，舌苔白滑，脉沉弦。治疗应首选方剂是","o":["大青龙汤","小青龙汤","十枣汤","半夏白术天麻汤","苓桂术甘汤"],"a":2,"e":"水饮停于胸胁，饮邪上逆则胸背掣痛、不得息，胃气上逆则干呕，肺气不利则短气，饮邪上犯清阳则头痛目眩，苔白滑、脉沉弦为水饮之象。十枣汤以甘遂、大戟、芫花峻下逐水，大枣缓和药性，攻逐水饮，主治悬饮之咳唾胸胁引痛、心下痞硬。苓桂术甘汤温阳化饮、健脾利湿，主治中阳不足之痰饮，胸胁满闷、头眩心悸，力缓；小青龙汤解表散寒、温肺化饮，主治外寒内饮之咳喘痰稀；半夏白术天麻汤化痰熄风、健脾祛湿，主治风痰上扰之眩晕头痛；大青龙汤发汗清热，主治外寒内热之烦躁"},{"q":"患者呕吐泄泻，胸脘痞闷，舌苔黄腻，脉濡数。治疗应首选的方剂是","o":["八正散","藿香正气散","平胃散","甘露消毒丹","连朴饮"],"a":4,"e":"湿热蕴结中焦，胃失和降则呕吐，脾失运化则泄泻，气机阻滞则胸脘痞闷，苔黄腻、脉濡数为湿热之象。连朴饮以黄连、栀子清热，厚朴、半夏理气和胃降逆，石菖蒲化湿，芦根清热生津，清热化湿、理气和中，主治湿热霍乱之吐泻、胸脘痞闷。藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞之吐泻，苔白腻；平胃散燥湿运脾、行气和胃，主治湿滞脾胃之脘腹胀满，无清热之功；甘露消毒丹利湿化浊、清热解毒，主治湿温时疫之发热咽痛；八正散清热利水通淋，主治热淋"},{"q":"小儿急惊，见身热昏睡，痰盛气粗，发惊发厥，四肢抽搐，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":3,"e":"小儿急惊，痰热内盛，上蒙清窍则昏睡，痰壅则气粗，热极生风则发惊发厥、四肢抽搐，抱龙丸以天竺黄、胆星、全蝎等涤痰镇惊，朱砂、麝香开窍安神，祛风涤痰、镇惊开窍，专为小儿急惊风痰热盛者而设。安宫牛黄丸清热解毒、豁痰开窍，主治热闭心包之高热烦躁、神昏谵语；紫雪清热开窍、熄风止痉，主治热盛动风之高热惊厥、神昏；至宝丹化浊开窍、清热解毒，主治痰热内闭心包之神昏、痰盛气粗；紫金锭辟瘟解毒、消肿止痛，主治秽恶痰浊之脘腹胀痛、吐泻"},{"q":"患者睾丸肿胀偏坠，坚硬如石，痛引脐腹，阴囊肿大，成痈溃烂，宜用","o":["橘核丸","天台乌药散","吴茱萸汤","暖肝煎","阳和汤"],"a":0,"e":"寒湿气滞凝于肝经，循经结于睾丸，故睾丸肿胀偏坠、坚硬如石、痛引脐腹，甚则阴囊肿大成痈溃烂。橘核丸以橘核、楝实、香附、木香等行气散结止痛，海藻、昆布、海带软坚散结，厚朴、枳实等破气消胀，行气止痛、软坚散结，主治寒湿疝气之睾丸肿胀偏坠。天台乌药散行气疏肝、散寒止痛，主治寒凝气滞之小肠疝气、少腹引控睾丸而痛；暖肝煎温补肝肾、行气止痛，主治肝肾不足、寒凝气滞之疝气，兼腰膝酸软；吴茱萸汤温中补虚、降逆止呕，主治肝胃虚寒之头痛、吐涎沫；阳和汤温阳补血、散寒通滞，主治阴疽"},{"q":"患者尿频尿急，淋沥不畅，溺时涩痛，尿色浑赤，口燥咽干，舌苔黄腻，脉滑数。主治病证是","o":["热淋","膏淋","气淋","血淋","石淋"],"a":0,"e":"湿热下注膀胱，气化不利则尿频尿急、淋沥不畅，湿热灼伤尿道则溺时涩痛，尿色浑赤，口燥咽干、苔黄腻、脉滑数为湿热之象，属热淋，八正散主之。膏淋以小便浑浊如米泔或滑腻如膏脂为特征，为湿热下注、分清泌浊失司；血淋以尿色红赤、溺时刺痛、夹有血块为特征，为热伤血络；石淋以尿中夹砂石、排尿突然中断、尿道刺痛为特征，为湿热煎熬成石；气淋以排尿困难、少腹胀满、脉沉弦为主，为气机郁滞，均非本证单纯湿热之热淋"},{"q":"患者咳吐腥臭脓血，胸中隐隐作痛，身有微热，咳嗽痰多，舌红，苔黄腻，脉滑数。首选治疗方剂是","o":["苇茎汤","四妙勇安汤","麻杏石甘汤","定喘汤","泻白散"],"a":0,"e":"热毒壅肺，腐肉成脓，故咳吐腥臭脓血，肺络瘀滞则胸中隐隐作痛，身有微热、咳嗽痰多、舌红苔黄腻、脉滑数为痰热瘀血之象。苇茎汤以苇茎清泻肺热为君，薏苡仁、冬瓜仁清热排脓，桃仁活血逐瘀，清肺化痰、逐瘀排脓，主治肺痈之咳吐腥臭脓血、胸中隐痛。麻杏石甘汤清肺平喘，主治外感风邪、邪热壅肺之发热喘咳，无腥臭脓血；泻白散泻肺清热、止咳平喘，主治肺热喘咳、皮肤蒸热；定喘汤宣肺降气、清热化痰，主治风寒外束、痰热内蕴之哮喘咳嗽；四妙勇安汤清热解毒、活血止痛，主治热毒炽盛之脱疽"},{"q":"患者恶寒发热，头面红肿焮痛，目不能开，咽喉不利，舌燥口渴，舌红苔白兼黄，脉浮数有力。治疗应首选的方剂是","o":["仙方活命饮","黄连解毒汤","普济消毒饮","五味消毒饮","九味羌活汤"],"a":2,"e":"风热疫毒上攻头面，故头面红肿焮痛、目不能开，风热犯表则恶寒发热、脉浮数有力，热毒伤津则咽喉不利、舌燥口渴，此为大头瘟。普济消毒饮以黄芩、黄连清热解毒为君，牛蒡子、连翘、薄荷、僵蚕疏风散邪，玄参、板蓝根、马勃等解毒利咽，清热解毒、疏风散邪，主治大头瘟。仙方活命饮清热解毒、消肿溃坚，主治阳证痈疡肿毒初起之局部红肿热痛；黄连解毒汤泻火解毒，主治三焦火毒炽盛之烦躁、吐衄；五味消毒饮清热解毒、消散疔疮，主治疔疮初起坚硬如钉；九味羌活汤解表散寒祛湿，主治外感寒湿之肢体酸楚"},{"q":"患者胸部闷痛，胸痛彻背，咳唾喘息，短气，舌苔白腻，脉沉弦，宜用","o":["血府逐瘀汤","瓜蒌薤白白酒汤","瓜蒌薤白半夏汤","小陷胸汤","枳实薤白桂枝汤"],"a":1,"e":"胸阳不振，痰气互结于胸，故胸部闷痛、胸痛彻背，肺气不利则咳唾喘息、短气，苔白腻、脉沉弦为痰浊内盛之象，属胸痹轻证。瓜蒌薤白白酒汤以瓜蒌实理气宽胸、涤痰散结为君，薤白通阳散结、行气止痛，白酒助药上行、温通胸阳，通阳散结、行气祛痰，主治胸痹之胸痛彻背、短气。瓜蒌薤白半夏汤于本方加半夏，化痰力更强，主治胸痹痰结较重、不得卧；枳实薤白桂枝汤主治胸痹心中痞气、气结在胸、胁下逆抢心；小陷胸汤清热化痰、宽胸散结，主治痰热互结之胸脘痞闷、按之则痛；血府逐瘀汤主治胸中血瘀之刺痛"},{"q":"患者喘咳痰多，短气，胸膈满闷，呼多吸少，腰疼脚软，肢体浮肿，舌苔白滑或白腻，脉弦滑，宜用","o":["小青龙汤","杏苏散","定喘汤","二陈汤","苏子降气汤"],"a":4,"e":"痰浊上壅于肺则喘咳痰多、胸膈满闷、短气，肾阳不足、摄纳无权则呼多吸少、腰疼脚软，水湿泛溢则肢体浮肿，苔白滑、脉弦滑为痰湿之象，属上实下虚之喘咳。苏子降气汤以苏子降气化痰、止咳平喘为君，半夏、厚朴、前胡降气祛痰，肉桂温肾纳气，当归养血，甘草调和，降气平喘、祛痰止咳，主治上实下虚之喘咳。小青龙汤解表散寒、温肺化饮，主治外寒内饮之喘咳痰稀；定喘汤宣肺降气、清热化痰，主治痰热哮喘、咳痰黄稠；杏苏散轻宣凉燥、理肺化痰，主治外感凉燥之咳嗽痰稀；二陈汤燥湿化痰、理气和中，主治湿痰咳嗽而无肾虚"},{"q":"患者脘腹胀满，口淡无味，嗳气吞酸，舌苔白滑腻，脉濡。主治病证是","o":["湿滞脾胃证","脾胃气虚证","脾虚湿盛证","内伤湿滞证","湿重于热证"],"a":0,"e":"脘腹胀满、口淡无味为湿困脾胃、运化失司，嗳气吞酸为胃气上逆，苔白滑腻、脉濡为湿滞之象，故病机属湿滞脾胃证，平胃散主之。脾胃气虚证以面色萎白、气短乏力、食少便溏、脉虚缓为主，无苔腻湿盛；脾虚湿盛证必有脾虚运化无力之体倦乏力、大便溏薄、面色萎黄；内伤湿滞证多兼外感表证之恶寒发热、头痛；湿重于热证当见苔黄腻、身热、口渴等热象，均非本证单纯湿滞脾胃"},{"q":"患者，男，28岁。游泳后感冒，发烧1天，体温39℃，无汗，咳嗽，口渴，舌苔薄黄，脉浮数。可选用下列何方加减治疗","o":["桑菊饮","柴葛解肌汤","升麻葛根汤","麻黄杏仁甘草石膏汤","银翘散"],"a":3,"e":"泳后感寒，邪从热化，邪热壅肺则发热、无汗、咳嗽、口渴，苔薄黄、脉浮数为风热化热之象。麻黄杏仁甘草石膏汤以麻黄宣肺解表、石膏清泻肺热为君，杏仁降肺气，甘草调和，清肺平喘、宣肺泄热，主治外感风邪、邪热壅肺之发热喘咳。银翘散辛凉透表、清热解毒，主治风热表证之发热咽痛、口渴，咳喘不著；桑菊饮疏风清热、宣肺止咳，主治风热轻证之咳嗽、发热不甚；柴葛解肌汤解肌清热，主治外感风寒、郁而化热之三阳合病，症见恶寒轻、发热重、眼眶痛；升麻葛根汤解肌透疹，主治麻疹初起疹发不出"},{"q":"患者心悸怔忡，虚烦失眠，神疲健忘，或梦遗，手足心热，口舌生疮，大便干结，舌红少苔，脉细数。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","黄连阿胶汤","养心汤"],"a":1,"e":"阴血不足、心神失养则心悸怔忡、虚烦失眠、神疲健忘，阴虚火旺则梦遗、手足心热、口舌生疮，肠燥则大便干结，舌红少苔、脉细数为阴虚内热之象。天王补心丹以生地滋阴养血为君，玄参、麦冬、天冬养阴清热，当归、丹参养血活血，人参、茯苓益气安神，酸枣仁、柏子仁、远志养心安神，滋阴养血、补心安神，主治阴虚血少之心悸失眠。朱砂安神丸镇心安神、清热养血，主治心火亢盛、阴血不足之失眠多梦、胸中烦热；酸枣仁汤养血安神、清热除烦，主治肝血不足之虚烦不眠；黄连阿胶汤滋阴降火，主治阴虚火旺之心烦失眠；养心汤益气养血安神，主治心虚血少之惊悸怔忡"},{"q":"患者胸胁疼痛，时发时止，口苦，舌红，苔黄，脉弦数，宜选用","o":["良附丸","血府逐瘀汤","四逆散","越鞠丸","金铃子散"],"a":4,"e":"肝郁气滞，郁而化热，气滞血瘀，故胸胁疼痛、时发时止，口苦、舌红苔黄、脉弦数为肝经郁热之象。金铃子散以川楝子疏肝泄热、行气止痛为君，延胡索活血行气止痛，疏肝泄热、活血止痛，主治肝郁化热之胸胁脘腹疼痛。四逆散透解郁热、疏肝理气，主治肝郁气滞之胁痛、四肢不温、泄利下重，止痛力弱；血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀之胸痛、痛有定处；良附丸高良姜、香附温胃散寒、行气止痛，主治寒邪客胃之胃脘冷痛、喜温；越鞠丸行气解郁，主治气血痰火湿食六郁之胸膈痞闷"},{"q":"头痛身热、咳嗽、咽痛、口渴、脉浮数为辨证要点的方剂是","o":["柴葛解肌汤","麻黄杏仁甘草石膏汤","葱豉桔梗汤","升麻葛根汤","银翘散"],"a":2,"e":"葱豉桔梗汤以葱白、豆豉疏风解表，桔梗、薄荷、连翘、甘草等清热利咽，辛凉解表、清热利咽，主治风热感冒初起，以头痛身热、咳嗽咽痛、口渴、脉浮数为辨证要点。银翘散辛凉透表、清热解毒，主治风热表证之发热无汗或有汗不畅、咽痛口渴，侧重透表解毒；麻黄杏仁甘草石膏汤清肺平喘，主治邪热壅肺之发热喘咳、口渴，以喘为主；柴葛解肌汤解肌清热，主治外感风寒化热之三阳合病，见恶寒轻、发热重、眼眶痛、鼻干；升麻葛根汤解肌透疹，主治麻疹初起之疹发不出、身热咳嗽"},{"q":"患者，女。带下黄臭，阴痒，舌红苔黄腻，脉弦数有力。治疗应首选的方剂是","o":["易黄散","清瘟败毒饮","龙胆泻肝汤","甘露消毒丹","黄连解毒汤"],"a":2,"e":"湿热下注肝经，循经外溢则带下黄臭、阴痒，舌红苔黄腻、脉弦数有力为肝胆湿热之象。龙胆泻肝汤以龙胆草清肝胆实火、利肝经湿热为君，黄芩、栀子清热，泽泻、木通、车前子清热利湿，当归、生地养血滋阴，清肝胆实火、利肝经湿热，主治肝经湿热之阴肿阴痒、带下黄臭。易黄汤补脾益肾、清热祛湿，主治脾肾两虚、湿热下注之带下色黄、质稠腥臭，无固定痛痒；黄连解毒汤泻三焦火毒，主治火毒炽盛之烦躁吐衄；甘露消毒丹利湿化浊、清热解毒，主治湿温时疫之发热咽痛；清瘟败毒饮气血两清，主治瘟疫热毒气血两燔"},{"q":"患者头痛恶寒，身重疼痛，午后身热，苔白不渴，脉濡。治疗应首选的方剂是","o":["防己黄芪汤","三仁汤","羌活胜湿汤","九味羌活汤","藿香正气散"],"a":1,"e":"湿温初起，湿邪郁表则头痛恶寒、身重疼痛，湿郁化热则午后身热，湿胜则苔白不渴、脉濡。三仁汤以杏仁宣上、白蔻仁畅中、薏苡仁渗下，三焦分消，配厚朴、通草、滑石、半夏等除湿清热，宣畅气机、清利湿热，主治湿温初起之头痛恶寒、身重疼痛、午后身热。羌活胜湿汤祛风胜湿，主治风湿在表之肩背痛、头痛身重；九味羌活汤解表散寒、祛湿清热，主治外感寒湿兼里热之口苦微渴；防己黄芪汤益气祛风、健脾利水，主治风湿表虚之汗出恶风；藿香正气散解表化湿，主治外感风寒、内伤湿滞之吐泻"},{"q":"患者咳嗽痰多气急，痰稠色黄，微恶风寒，舌苔黄腻，脉滑数，宜用","o":["苏子降气汤","定喘汤","清气化痰丸","小陷胸汤","小青龙汤"],"a":1,"e":"风寒外束，痰热内蕴，肺气壅滞则咳嗽痰多气急，痰稠色黄、苔黄腻、脉滑数为痰热之象，微恶风寒为外有表邪。定喘汤以白果收敛肺气、麻黄宣肺散寒为君，黄芩、桑白皮清肺化痰，苏子、杏仁、半夏降气化痰，宣肺降气、清热化痰，主治风寒外束、痰热内蕴之哮喘咳嗽、痰多黄稠。苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳、呼多吸少、腰膝酸软；清气化痰丸清热化痰、理气止咳，主治痰热咳嗽之痰多黄稠，无解表宣肺之力；小陷胸汤清热化痰、宽胸散结，主治痰热互结之心下痞闷；小青龙汤温肺化饮，主治外寒内饮之痰清稀"},{"q":"症见遗精滑泄，神疲乏力，腰痛耳鸣，舌淡苔白，脉细弱者，治宜选用","o":["龙胆泻肝丸","桑螵蛸散","知柏地黄丸","金锁固精丸","缩泉丸"],"a":3,"e":"肾虚精关不固则遗精滑泄，肾气不足则神疲乏力、腰痛耳鸣，舌淡苔白、脉细弱为肾虚之象。金锁固精丸以沙苑子补肾固精为君，芡实、莲子、莲须固肾涩精，龙骨、牡蛎煅用涩精止遗，固肾涩精，主治肾虚不固之遗精滑泄。桑螵蛸散调补心肾、涩精止遗，主治心肾两虚之尿频、遗尿、遗精、心神恍惚；知柏地黄丸滋阴降火，主治阴虚火旺之遗精、潮热盗汗、口干；缩泉丸温肾祛寒、缩尿止遗，主治膀胱虚寒之尿频、遗尿；龙胆泻肝丸清肝胆实火湿热，主治湿热下注之遗精、阴肿阴痒"},{"q":"患者发热盗汗，面赤心烦，口干唇燥，大便干结，小便黄赤，舌红苔黄，脉数。治疗应首选的方剂是","o":["黄龙汤","凉膈散","小承气汤","当归六黄汤","甘露消毒丹"],"a":3,"e":"阴虚火旺，迫津外泄则盗汗，虚火上炎则面赤心烦，津伤则口干唇燥、大便干结，火热内盛则发热、小便黄赤，舌红苔黄、脉数为阴虚火旺之象。当归六黄汤以当归、生地、熟地滋阴养血为君，黄芩、黄连、黄柏泻火除烦，黄芪固表止汗，滋阴泻火、固表止汗，主治阴虚火旺之盗汗发热、面赤心烦。黄龙汤泻热通便、补气养血，主治阳明腑实兼气血不足之便秘、神疲；凉膈散泻火通便、清上泄下，主治上中二焦火热之胸膈烦热、便秘；小承气汤轻下热结，主治阳明腑实轻证；甘露消毒丹利湿化浊、清热解毒，主治湿温时疫"},{"q":"患者肝肾不足，须发早白，齿牙动摇，梦遗滑精，崩漏带下，肾虚不育，腰膝酸软，治宜","o":["七宝美鬓丹","左归丸","右归丸","大补阴丸","肾气丸"],"a":0,"e":"肝肾不足、精血亏虚，不能上荣则须发早白、齿牙动摇，精关不固则梦遗滑精，冲任不固则崩漏带下，肾虚则腰膝酸软、不育。七宝美鬓丹以何首乌补肝肾、益精血、乌须发为君，当归、枸杞、菟丝子、补骨脂、茯苓、牛膝等助之，补肝肾、益精血、乌须发，主治肝肾不足之须发早白、齿牙动摇、腰膝酸软。左归丸滋补肾阴、填精益髓，主治真阴不足之腰膝酸软、盗汗遗精，无乌须发之功；右归丸温补肾阳、填精益髓，主治命门火衰之神疲畏寒；大补阴丸滋阴降火，主治阴虚火旺之骨蒸潮热；肾气丸温补肾阳、化气行水，主治肾阳不足之水肿、小便不利"},{"q":"胆怯易惊，虚烦不宁，失眠多梦，呕吐呃逆，癫痫等，宜选用","o":["清金化痰丸","二陈汤","贝母瓜蒌散","温胆汤","滚痰丸"],"a":3,"e":"胆郁痰扰，痰热内扰心神则胆怯易惊、虚烦不宁、失眠多梦，胃失和降则呕吐呃逆，痰蒙清窍可致癫痫。温胆汤以半夏、陈皮、茯苓、甘草燥湿化痰、理气和中为君，枳实破气消痰，竹茹清热化痰、和胃止呕，理气化痰、清胆和胃，主治胆郁痰扰之惊悸失眠、呕吐呃逆。二陈汤燥湿化痰、理气和中，主治湿痰咳嗽、痰多色白，无清胆和胃之功；清金化痰丸清肺化痰，主治痰热壅肺之咳嗽痰黄；贝母瓜蒌散润肺化痰、理气止咳，主治燥痰咳嗽之痰少而黏；滚痰丸泻火逐痰，主治实热老痰之癫狂惊悸、大便秘结"},{"q":"患者身重微肿，汗出恶风，小便不利，舌淡苔白，脉浮。本证的病机是","o":["肺脾气虚，风寒外袭","肺脾气虚，风湿外袭","肺脾气虚，风热外袭","肺脾气虚，寒湿外袭","肺脾气虚，湿毒外袭"],"a":1,"e":"身重微肿、小便不利为水湿泛溢，汗出恶风、脉浮为风邪外袭、营卫不和，舌淡苔白为脾气不足，故病机为肺脾气虚、风湿外袭，防己黄芪汤主之。风寒外袭当见恶寒重、无汗、脉浮紧；风热外袭当见发热重、咽痛、脉浮数；寒湿外袭多见畏寒肢冷、苔白腻、脉沉迟；湿毒外袭则见皮肤瘙痒、疮疡、苔腻，均非本证汗出恶风、脉浮之风水表虚表现"},{"q":"患者，男，51岁。证见脘腹痞满胀痛，大便秘结，舌苔黄腻，脉沉实。治宜","o":["越鞠丸","葛花解酲汤","木香槟榔丸","枳实导滞丸","健脾丸"],"a":2,"e":"湿热积滞内停，气机壅滞则脘腹痞满胀痛，腑气不通则大便秘结，苔黄腻、脉沉实为实热积滞之象。木香槟榔丸以木香、槟榔行气导滞为君，配青皮、陈皮、香附等行气，大黄、芒硝攻积泄热，牵牛子、皂角逐水消积，行气导滞、攻积泄热，主治积滞内停、湿蕴生热之脘腹痞满胀痛、大便秘结。枳实导滞丸消积导滞、清利湿热，主治湿热食积之脘腹胀痛、下痢泄泻、小便短赤，以下利为主；越鞠丸行气解郁，主治六郁之胸膈痞闷；葛花解酲汤分消酒湿、理气健脾，主治饮酒过度之眩晕呕吐；健脾丸健脾和胃、消食止泻，主治脾虚食积"},{"q":"患者，暑病余热未清，气阴两伤而见身热多汗，虚烦少寐，舌红少苔，脉虚数。治疗应首选的方剂是","o":["清暑益气汤","白虎加人参汤","竹叶石膏汤","青蒿鳖甲汤","当归六黄汤"],"a":2,"e":"暑病后期，余热未清、气阴两伤，故身热多汗、虚烦少寐，舌红少苔、脉虚数为余热未净、气阴不足之象。竹叶石膏汤以竹叶、石膏清热生津为君，人参、麦冬益气养阴，半夏和胃降逆，粳米、甘草养胃和中，清热生津、益气和胃，主治伤寒温病后期余热未清、气阴两伤。白虎加人参汤清热生津，主治气分热盛之大热、大汗、大渴、脉洪大而虚；清暑益气汤清暑益气、养阴生津，主治暑热耗伤气阴之身热口渴、体倦少气；青蒿鳖甲汤养阴透热，主治温病后期邪伏阴分之夜热早凉、热退无汗；当归六黄汤滋阴泻火固表，主治阴虚火旺之盗汗"},{"q":"患者月经前少腹胀痛，胀甚于痛，舌淡，苔薄白，脉弦紧，宜用","o":["良附丸","天台乌药散","橘核丸","暖肝煎","加味乌药汤"],"a":4,"e":"经前肝气郁滞，气血运行不畅，故少腹胀痛、胀甚于痛，舌淡苔薄白、脉弦紧为气滞兼寒之象。加味乌药汤以乌药、香附、砂仁、木香等疏肝理气、行气止痛，配延胡索、槟榔活血行气，疏肝理气、调经止痛，主治肝郁气滞之经前少腹胀痛、胀甚于痛。良附丸温胃散寒、行气止痛，主治寒邪客胃之胃脘冷痛；天台乌药散行气疏肝、散寒止痛，主治寒凝气滞之小肠疝气、少腹引控睾丸；暖肝煎温补肝肾、行气止痛，主治肝肾不足、寒凝气滞之疝气；橘核丸行气散结、软坚止痛，主治寒湿疝气之睾丸肿胀偏坠，均非经痛之专方"},{"q":"患者头痛身热，微恶风寒，无汗或有汗不多，咳嗽，心烦，口渴，咽干，舌红，脉数。治疗应首选的方剂是","o":["银翘散","桑菊饮","加减葳蕤汤","葱豉汤","葱白七味饮"],"a":2,"e":"阴虚之体外感风热，阴虚则心烦、口渴咽干、舌红脉数，风热犯表则头痛身热、微恶风寒、无汗或汗少、咳嗽。加减葳蕤汤以葳蕤滋阴养液为君，配葱白、豆豉、薄荷、桔梗等疏风清热解表，白薇清热，甘草、大枣养胃，滋阴解表，主治阴虚外感风热之头痛身热、咽干口渴。银翘散辛凉透表、清热解毒，主治风热表证之发热咽痛，无滋阴之力；桑菊饮疏风清热、宣肺止咳，主治风热轻证之咳嗽；葱豉汤解表散寒，主治外感初起之头痛发热、无汗；葱白七味饮养血解表，主治血虚外感风寒之头痛身热、无汗"},{"q":"患者口干而渴，饮水不解，小便频数，困倦气短，脉虚细无力。治疗宜首选的方剂是","o":["桑杏汤","清燥救肺汤","玉液汤","沙参麦冬汤","增液汤"],"a":2,"e":"脾虚气弱、津液不升则口干而渴、饮水不解，肾虚不固则小便频数，气虚则困倦气短，脉虚细无力为气阴两虚之象，属消渴之气阴不足证。玉液汤以黄芪、山药益气健脾为君，知母、天花粉、葛根滋阴生津止渴，五味子、鸡内金固肾缩尿、助运化，益气滋阴、固肾止渴，主治消渴之气阴两虚、口渴尿多。桑杏汤清宣温燥、润肺止咳，主治外感温燥之头痛身热、干咳；清燥救肺汤清燥润肺，主治燥热伤肺之干咳气喘、咽干；沙参麦冬汤清养肺胃、生津润燥，主治肺胃阴伤之咽干口渴、干咳；增液汤增液润燥，主治阳明温病之便秘"},{"q":"患者胁肋疼痛，嗳气太息，脘腹胀满，脉弦，最宜选用","o":["越鞠丸","一贯煎","小柴胡汤","半夏厚朴汤","柴胡疏肝散"],"a":4,"e":"肝气郁结，疏泄失司，故胁肋疼痛、嗳气太息，气滞中焦则脘腹胀满，脉弦为肝郁之象。柴胡疏肝散以柴胡疏肝解郁为君，香附、川芎、陈皮、枳壳理气活血行滞，白芍柔肝，甘草调和，疏肝理气、活血止痛，主治肝气郁结之胁肋胀痛、嗳气太息。一贯煎滋阴疏肝，主治肝肾阴虚、肝气不舒之胁肋胀痛、口干咽燥、舌红少苔；小柴胡汤和解少阳，主治少阳证之往来寒热、胸胁苦满、口苦咽干；半夏厚朴汤行气散结、降逆化痰，主治痰气郁结之梅核气，咽中如有物阻；越鞠丸行气解郁，主治气血痰火湿食六郁之胸膈痞闷"},{"q":"患者全身浮肿，身半以下为甚，手足不温，大便溏薄，舌淡胖苔白腻，脉沉迟。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":4,"e":"脾肾阳虚，水湿不化，泛溢肌肤则全身浮肿、身半以下为甚，阳虚不温则手足不温，脾虚湿盛则大便溏薄，舌淡胖苔白腻、脉沉迟为阳虚水停之象。实脾散以附子、干姜温阳散寒为君，白术、茯苓健脾渗湿，厚朴、木香、槟榔、草果行气导水，温阳健脾、行气利水，主治脾肾阳虚、水气内停之阴水。真武汤温阳利水，主治脾肾阳虚、水气泛溢之小便不利、四肢沉重疼痛、身瞤动；五苓散温阳化气利水，主治膀胱蓄水之小便不利、头痛微热；猪苓汤利水清热养阴，主治水热互结伤阴；苓桂术甘汤温阳化饮，主治中阳不足之痰饮"},{"q":"以“恶寒发热，无汗头痛，咳痰色白，胸脘满闷，倦怠乏力，苔白，脉弱”为辨证要点的方剂是","o":["小青龙汤","止嗽散","参苏饮","麻黄附子细辛汤","败毒散"],"a":2,"e":"参苏饮以人参、甘草益气扶正，苏叶、葛根解表散寒，陈皮、半夏、茯苓理气化痰，桔梗、枳壳宣降气机，益气解表、理气化痰，以恶寒发热、无汗头痛、咳痰色白、胸脘满闷、倦怠乏力、苔白脉弱为辨证要点，主治气虚外感风寒兼痰湿。败毒散益气解表、散风祛湿，主治气虚外感风寒湿之憎寒壮热、无汗、肢体酸痛，咳痰不著；小青龙汤解表散寒、温肺化饮，要点为喘咳痰多清稀、舌苔白滑；麻黄附子细辛汤助阳解表，主治阳虚外感之恶寒重、发热轻、脉沉细；止嗽散疏风止咳，主治风邪犯肺之咳嗽迁延"},{"q":"患者恶寒头痛，脘腹闷痛，恶心呕吐，肠鸣泄泻，舌苔白腻，脉浮。主治病证是","o":["外感风热，内伤湿滞证","外感风湿，内有蕴热证","外感风寒，内伤湿滞证","外感风寒，内停水饮证","外感风寒，内有痰饮证"],"a":2,"e":"恶寒头痛、脉浮为外感风寒，脘腹闷痛、恶心呕吐、肠鸣泄泻、苔白腻为内伤湿滞、脾胃失和，故病机为外感风寒、内伤湿滞，藿香正气散主之。外感风热、内伤湿滞当见发热重、咽痛、脉浮数；外感风湿、内有蕴热当见肢体酸痛、苔黄腻、口渴；外感风寒、内停水饮以咳喘痰稀、心悸头眩为主；外感风寒、内有痰饮以咳嗽痰多清稀、胸闷为主，均无吐泻并作、苔白腻之湿滞中焦表现"},{"q":"主治心肾不交之健忘失眠，心神不安，或头目眩晕，舌红苔薄白，脉弦细。其方剂为","o":["交泰丸","黄连阿胶汤","甘麦大枣汤","孔圣枕中丹","天王补心丹"],"a":3,"e":"心肾不交，肾阴不足不能上济于心，心火独亢则健忘失眠、心神不安，虚阳上扰则头目眩晕，舌红苔薄白、脉弦细为阴虚之象。孔圣枕中丹以龟板、龙骨滋阴潜阳、重镇安神为君，石菖蒲、远志开窍化痰、交通心肾，滋阴补肾、养心安神，主治心肾不交之健忘失眠、心神不安。交泰丸仅黄连、肉桂两味，清心火、温肾阳，交通心肾，主治心火偏亢、肾阳不足之失眠；黄连阿胶汤滋阴降火，主治阴虚火旺之心烦失眠、舌红绛；甘麦大枣汤养心安神、和中缓急，主治脏躁之精神恍惚、悲伤欲哭；天王补心丹滋阴养血，主治阴虚血少之心悸健忘、口舌生疮"},{"q":"患者，男，42岁。阵发性头晕2年，加重10天。现症见头晕目眩，头重如裹，肢体困重，胸闷呕恶，舌质淡，苔白腻，脉弦滑。治疗宜选用的方剂是","o":["天麻钩藤饮","平胃散","二陈汤","苓桂术甘汤","半夏白术天麻汤"],"a":4,"e":"脾虚湿盛，聚湿成痰，痰浊上蒙清窍则头晕、头重如裹，湿困肢体则困重，痰阻中焦则胸闷呕恶，舌淡苔白腻、脉弦滑为痰湿之象。半夏白术天麻汤以半夏燥湿化痰、天麻平肝熄风为君，白术健脾燥湿，茯苓健脾渗湿，橘红理气化痰，化痰熄风、健脾祛湿，主治风痰上扰之眩晕、头重如裹、胸闷呕恶。天麻钩藤饮平肝熄风、清热活血，主治肝阳上亢之眩晕耳鸣、头目胀痛、烦躁；苓桂术甘汤温阳化饮，主治中阳不足痰饮之头眩心悸、背部恶寒；二陈汤燥湿化痰、理气和中，主治湿痰咳嗽；平胃散燥湿运脾，主治湿滞脾胃之脘腹胀满，均无熄风之功"},{"q":"患儿，男，5岁。小儿急惊，热盛抽搐。治疗应首选的方剂是","o":["泻青丸","至宝丹","大定风珠","龙胆泻肝汤","泻黄散"],"a":0,"e":"小儿急惊，热盛生风，肝风内动则抽搐，泻青丸以龙胆草、大黄等泻肝清热，羌活、防风、川芎等疏散肝风，当归、栀子养血清热，清肝泻火、熄风止痉，主治肝经热盛之小儿急惊、抽搐。大定风珠滋阴熄风，主治温病后期阴虚风动之手足瘈疭、脉气虚弱；至宝丹化浊开窍、清热解毒，主治痰热内闭心包之神昏谵语；龙胆泻肝汤清肝胆实火、利肝经湿热，主治口苦胁痛、阴肿阴痒，无熄风止痉之功；泻黄散泻脾胃伏火，主治脾胃伏火之口疮口臭、烦渴"},{"q":"患者全身水肿，尤以身半以下为重，腹胀喘满，二便不利，舌苔白滑，脉沉实。治疗应首选方剂是","o":["实脾散","五皮饮","禹功散","真武汤","十枣汤"],"a":4,"e":"水饮内停，泛溢肌肤则全身水肿、身半以下为甚，水气上逆则腹胀喘满，二便不利、苔白滑、脉沉实为水饮壅盛之实证。十枣汤以甘遂、大戟、芫花峻下逐水，大枣缓和大毒、护中，攻逐水饮，主治水饮壅盛之全身水肿、腹胀喘满、二便不利。实脾散温阳健脾、行气利水，主治脾肾阳虚之阴水，身半以下肿甚、手足不温、脉沉迟；真武汤温阳利水，主治脾肾阳虚水泛之小便不利、四肢沉重；五皮饮利湿消肿、理气健脾，主治皮水之全身水肿、按之没指；禹功散逐水通便，主治寒湿水疝、阴囊肿胀，均非水饮壅盛之峻下逐水"},{"q":"腹中时痛、喜温欲按、舌淡苔白、脉细弦；或虚劳而心中悸动，虚烦不宁，面色无华，或手足烦热，咽干口燥。方剂宜选用","o":["吴茱萸汤","小建中汤","大建中汤","理中丸","四逆汤"],"a":1,"e":"中焦虚寒，肝脾不和，腹中拘急则时痛、喜温欲按，舌淡苔白、脉细弦为虚寒之象，虚劳气血不足则心中悸动、虚烦不宁、面色无华，阴阳不和则手足烦热、咽干口燥。小建中汤以桂枝、白芍倍用温中补虚、和里缓急为君，饴糖温中补虚，生姜、大枣调和，甘草缓急，温中补虚、和里缓急，主治中焦虚寒、肝脾不和之腹中痛、虚劳心悸。大建中汤温中补虚、降逆止痛，主治中阳衰微、阴寒内盛之心胸大痛、呕吐；理中丸温中祛寒、补气健脾，主治脾胃虚寒之自利不渴；吴茱萸汤温中补虚、降逆止呕，主治肝胃虚寒之头痛、吐涎沫；四逆汤回阳救逆，主治四肢厥逆"},{"q":"以咳嗽，发热不甚，微渴，脉浮数为辨证要点的方剂是","o":["麻黄杏仁甘草石膏汤","桑菊饮","柴葛解肌汤","升麻葛根汤","银翘散"],"a":1,"e":"桑菊饮以桑叶、菊花疏风清热为君，杏仁、桔梗宣肺止咳，连翘、薄荷清热，芦根生津，甘草调和，疏风清热、宣肺止咳，主治风热犯肺之咳嗽，以咳嗽、发热不甚、微渴、脉浮数为辨证要点。银翘散辛凉透表、清热解毒，主治风热表证之发热较重、咽痛口渴；麻黄杏仁甘草石膏汤清肺平喘，主治邪热壅肺之发热喘咳、口渴；柴葛解肌汤解肌清热，主治外感风寒化热之三阳合病，见眼眶痛、鼻干；升麻葛根汤解肌透疹，主治麻疹初起之疹发不出，均非以咳嗽为主之风热轻证"},{"q":"患者胸脘烦闷，呕吐泄泻，口渴不欲饮，舌苔黄腻，脉濡数。本证的病机是","o":["热毒内蕴，升降失常","湿热内蕴，升降失常","瘀热内蕴，升降失常","寒湿内蕴，升降失常","湿毒内蕴，升降失常"],"a":1,"e":"胸脘烦闷、呕吐泄泻为湿热蕴结中焦、胃失和降、脾失运化，升降失常，口渴不欲饮、苔黄腻、脉濡数为湿热内蕴之象，故病机为湿热内蕴、升降失常，连朴饮主之。寒湿内蕴当见畏寒肢冷、口不渴、苔白腻、脉沉迟；热毒内蕴多为炽盛之高热、神昏、吐衄、舌绛；瘀热内蕴当见疼痛固定、舌黯有瘀点、脉涩；湿毒内蕴多见疮疡、皮肤瘙痒、苔腻，均非本证吐泻并作、苔黄腻之湿热中阻"},{"q":"患者三焦火毒热盛证而见有痈疡疔毒，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["普济消毒饮","黄连解毒汤","仙方活命饮","四妙勇安汤","五味消毒饮"],"a":1,"e":"三焦火毒炽盛，热壅血分则生痈疡疔毒，舌红苔黄、脉数有力为实火之象。黄连解毒汤以黄芩清上焦、黄连清中焦、黄柏清下焦、栀子通泄三焦，泻火解毒，主治三焦火毒热盛之烦躁、吐衄、痈疡疔毒。仙方活命饮清热解毒、消肿溃坚，主治阳证痈疡肿毒初起之局部红肿热痛；五味消毒饮清热解毒、消散疔疮，主治疔疮初起坚硬如钉、发热恶寒；普济消毒饮疏风清热、解毒利咽，主治大头瘟头面红肿焮痛；四妙勇安汤清热解毒、活血止痛，主治热毒炽盛之脱疽，均非通泻三焦火毒"},{"q":"患者夜热早凉，热退无汗，舌红少苔，脉细数。治疗应首选的方剂是","o":["清营汤","清骨散","青蒿鳖甲汤","秦艽鳖甲散","当归六黄汤"],"a":2,"e":"温病后期，邪伏阴分，入夜阳气内入与邪相争则夜热，清晨阳气出表则热退，阴液已伤则热退无汗，舌红少苔、脉细数为阴虚内热之象。青蒿鳖甲汤以鳖甲滋阴入络搜邪为君，青蒿透热外出，知母、丹皮清热凉血，生地养阴，养阴透热，主治温病后期邪伏阴分之夜热早凉、热退无汗。清营汤清营解毒、透热养阴，主治热入营分之身热夜甚、神烦少寐、斑疹隐隐；清骨散清虚热，主治骨蒸潮热、低热日久不退；秦艽鳖甲散滋阴养血、清热除蒸，主治风劳骨蒸、盗汗；当归六黄汤滋阴泻火固表，主治盗汗发热、面赤心烦"},{"q":"患者，男，50岁。自述经常便秘。现患者腹痛，脐下绞痛，绕脐不止，手足不温，苔白不渴，脉沉弦而迟。宜选用的方剂是","o":["温脾汤","大陷胸汤","济川煎","调胃承气汤","麻子仁丸"],"a":0,"e":"脾阳不足，冷积内停，腑气不通则腹痛、脐下绞痛绕脐不止、便秘，阳虚不温则手足不温，苔白不渴、脉沉弦而迟为寒积之象。温脾汤以附子、干姜温阳散寒为君，大黄泻下冷积，人参、甘草、当归补养气血，温补脾阳、攻下冷积，主治脾阳不足之冷积便秘、腹痛、手足不温。济川煎温肾益精、润肠通便，主治肾虚肠燥之便秘、腰膝酸软；麻子仁丸润肠泄热、行气通便，主治脾约之大便干结、小便频数；调胃承气汤缓下热结，主治阳明燥实之便秘、口渴；大陷胸汤泻热逐水，主治水热互结之心下硬满疼痛，均非温下冷积"},{"q":"患者消渴，消谷善饥。治疗应首选的方剂是","o":["玉女煎","黄芩汤","清胃散","左金丸","泻黄散"],"a":0,"e":"胃热炽盛、肾阴不足，胃火消食则消谷善饥，肾阴亏虚则口渴多饮，属消渴之中消，玉女煎以石膏、知母清胃泻火为君，熟地、麦冬滋阴生津，牛膝引火下行，清胃热、滋肾阴，主治胃热阴虚之消渴、消谷善饥、牙痛。清胃散清胃凉血，主治胃火上攻之牙宣出血、口气热臭，无滋肾之功；左金丸清肝泻火、降逆止呕，主治肝火犯胃之呕吐吞酸、胁痛；泻黄散泻脾胃伏火，主治脾胃伏火之口疮口臭、烦渴；黄芩汤清热止利，主治少阳阳明合病之腹痛下利，均非胃热阴虚之消渴"},{"q":"患者呃逆或干呕，虚烦少气，口干，舌红嫩，脉虚数，宜用","o":["旋覆代赭汤","橘皮竹茹汤","丁香柿蒂汤","二陈汤","温胆汤"],"a":1,"e":"胃虚有热，气逆不降则呃逆、干呕，胃气虚弱则虚烦少气，津伤则口干，舌红嫩、脉虚数为胃虚有热之象。橘皮竹茹汤以橘皮理气和胃、竹茹清热降逆为君，人参、甘草、大枣益气和中，生姜和胃降逆，降逆止呃、益气清热，主治胃虚有热之呃逆、干呕。旋覆代赭汤降逆化痰、益气和胃，主治胃虚痰阻气逆之噫气不除、心下痞硬；丁香柿蒂汤温中益气、降逆止呃，主治胃气虚寒之呃逆、胸痞、脉沉迟；二陈汤燥湿化痰、理气和中，主治湿痰咳嗽呕吐；温胆汤理气化痰、清胆和胃，主治胆郁痰扰之惊悸失眠、呕吐"},{"q":"患者喉间起白如腐不易拭去，咽喉肿痛，鼻干唇燥，呼吸有声，脉细数。治疗宜","o":["清燥救肺汤","养阴清肺汤","百合固金汤","银翘散","琼玉膏"],"a":1,"e":"肺肾阴虚，虚火上炎，疫毒壅喉，故喉间起白如腐、不易拭去，咽喉肿痛、呼吸有声，鼻干唇燥、脉细数为阴虚肺燥之象，此即白喉。养阴清肺汤以生地、玄参、麦冬养阴清热为君，贝母、丹皮清热化痰凉血，薄荷、甘草利咽解毒，养阴清肺、解毒利咽，主治阴虚肺燥之白喉。百合固金汤养阴润肺、化痰止咳，主治肺肾阴虚之咳嗽痰血、咽干；清燥救肺汤清燥润肺，主治燥热伤肺之干咳气喘、咽干鼻燥；银翘散辛凉解表，主治风热咽痛、发热，无养阴之力；琼玉膏滋阴润肺、益气健脾，主治肺痨虚劳之干咳、咯血"},{"q":"患者下利清水，色纯清，脘腹胀满，腹痛拒按，身热口渴，神倦少气，神昏肢厥，舌苔焦黑，脉虚。治疗应首选方剂是","o":["黄龙汤","大承气汤","调胃承气汤","葛根黄芩黄连汤","安宫牛黄丸"],"a":0,"e":"热结旁流，腑实燥屎内结，故下利清水、脘腹胀满、腹痛拒按、身热口渴、苔焦黑，热耗气阴则神倦少气、脉虚，热深厥深则神昏肢厥，属阳明腑实兼气血不足。黄龙汤以大承气汤泄热通便为君，配人参、当归、甘草、桔梗补气养血、宣肺通腑，泄热通便、补气养血，主治热结旁流而气血虚者。大承气汤峻下热结，主治阳明腑实之痞满燥实，无补虚之力；调胃承气汤缓下热结，主治燥实而无痞满；葛根黄芩黄连汤解表清里，主治协热下利、身热；安宫牛黄丸清热开窍，主治热闭心包之神昏谵语，均无通腑攻下之功"},{"q":"患者胸膈满闷，脘腹疼痛，恶心呕吐，肠鸣泄泻，恶寒发热，舌苔白腻，脉濡缓。治疗应首选的治法是","o":["解表散寒，理气和胃","解表散寒，和胃止呕","解表散寒，芳化湿浊","解表化湿，通络止痛","解表化湿，理气和中"],"a":4,"e":"恶寒发热为外感风寒，胸膈满闷、恶心呕吐、肠鸣泄泻、苔白腻、脉濡缓为内伤湿滞、气机不畅，故治宜解表化湿、理气和中，藿香正气散主之。解表散寒、理气和胃偏于温散，未突出化湿；解表散寒、和胃止呕重在止呕，主治胃寒呕吐；解表散寒、芳化湿浊侧重芳香化浊，主治湿浊中阻；解表化湿、通络止痛兼治痹痛，主治湿痹，均非本证外感风寒、内伤湿滞而吐泻并作之治法"},{"q":"患者阴肿，阴痒，舌红苔黄腻，脉细数有力。治疗应首选的方剂是","o":["消风散","普济消毒饮","龙胆泻肝汤","甘露消毒丹","当归饮子"],"a":2,"e":"肝经湿热下注，循经外溢则阴肿阴痒，舌红苔黄腻、脉细数有力为肝胆湿热之象。龙胆泻肝汤以龙胆草清肝胆实火、利肝经湿热为君，黄芩、栀子清热，泽泻、木通、车前子利湿，当归、生地养血滋阴，清肝胆实火、利肝经湿热，主治肝经湿热之阴肿阴痒、带下黄臭。消风散疏风养血、清热除湿，主治风湿浸淫血脉之皮肤瘙痒、疹块；当归饮子养血活血、祛风止痒，主治血虚生风之皮肤瘙痒；甘露消毒丹利湿化浊、清热解毒，主治湿温时疫之发热咽痛；普济消毒饮疏风清热解毒，主治大头瘟头面红肿，均非肝经湿热下注之阴痒"},{"q":"患者汗、吐、下后，里热炽盛而见大热，大汗，大渴，脉洪大者。治疗应首选的方剂是","o":["白虎汤","竹叶石膏汤","白虎加人参汤","白虎加苍术汤","白虎加桂枝汤"],"a":2,"e":"汗、吐、下后，津液大伤，里热炽盛，故大热、大汗、大渴、脉洪大，兼气阴不足，白虎加人参汤以石膏、知母清热生津为君，粳米、甘草养胃，加人参益气生津，清热、益气、生津，主治气分热盛而津气两伤之大热大渴、脉洪大而虚。白虎汤清热生津，主治气分热盛之四大证而无气虚，脉洪大有力；竹叶石膏汤清热生津、益气和胃，主治热病后期余热未清、气阴两伤之虚烦少寐；白虎加苍术汤清热祛湿，主治湿温之身重、胸闷；白虎加桂枝汤清热通络，主治温疟之寒热往来、关节痛"},{"q":"患儿腰膝酸软，头晕目眩，耳聋耳鸣，盗汗，消渴，骨蒸潮热，手足心热，口燥咽干，囟门不合，舌红少苔，脉沉细数，治疗宜用的方剂是","o":["天王补心丹","炙甘草汤","酸枣仁汤","补中益气汤","六味地黄丸"],"a":4,"e":"肝肾阴虚，腰膝失养则腰膝酸软，髓海不足则头晕目眩、耳聋耳鸣，囟门不合为肾虚骨弱，阴虚内热则盗汗、骨蒸潮热、手足心热、消渴、口燥咽干，舌红少苔、脉沉细数为肝肾阴虚之象。六味地黄丸以熟地滋肾填精为君，山茱萸养肝涩精，山药补脾固精，泽泻、丹皮、茯苓三泻渗湿泄浊，滋补肝肾，主治肝肾阴虚之腰膝酸软、盗汗遗精、消渴。天王补心丹滋阴养血安神，主治心悸失眠、口舌生疮；炙甘草汤益气滋阴、通阳复脉，主治气血阴阳俱虚之心悸、脉结代；酸枣仁汤养血安神，主治虚烦不眠；补中益气汤补中升阳，主治脾虚气陷"},{"q":"患者高热烦躁，神昏谵语，舌謇肢厥，舌红绛，脉数有利，治疗应首选的方剂是","o":["安宫牛黄丸","犀角地黄汤","至宝丹","清营汤","紫金锭"],"a":0,"e":"热闭心包，热毒内陷则高热烦躁、神昏谵语，热盛伤津则舌謇，热深厥深则肢厥，舌红绛、脉数有力为热入心包之象。安宫牛黄丸以牛黄、麝香、冰片开窍醒神为君，水牛角、黄芩、黄连、栀子清热解毒，朱砂、珍珠镇心安神，清热解毒、豁痰开窍，主治热闭心包之高热烦躁、神昏谵语，为凉开三宝之首。至宝丹化浊开窍、清热解毒，主治痰热内闭心包之神昏、痰盛气粗，偏于化浊开窍；清营汤清营解毒、透热养阴，主治热入营分之身热夜甚、斑疹隐隐，无开窍之功；犀角地黄汤清热解毒、凉血散瘀，主治热入血分之吐血、衄血、发斑；紫金锭辟秽解毒，主治秽恶痰浊之吐泻"},{"q":"患者头痛微热，小便不利，水肿，舌苔白，脉浮。治疗应首选的治法是","o":["利水渗湿，温阳化饮","利水渗湿，理气健脾","利水渗湿，温中祛寒","利水渗湿，温阳化气","利水渗湿，养阴清热"],"a":3,"e":"风寒外袭，膀胱气化不利，水湿泛溢则小便不利、水肿，风邪外束则头痛微热，舌苔白、脉浮为外有表邪、水湿内停之蓄水证，五苓散主之，故治法为利水渗湿、温阳化气。利水渗湿、温阳化饮重在化饮，主治中阳不足之痰饮，头眩心悸；利水渗湿、理气健脾侧重健脾行气，主治脾虚湿盛；利水渗湿、温中祛寒主治寒湿内停；利水渗湿、养阴清热为猪苓汤之法，主治水热互结伤阴之小便不利、口渴，均非膀胱蓄水之治法"},{"q":"证见面色萎黄，饮食不化，四肢乏力，肠鸣泄泻，舌淡苔白腻，脉虚缓，治宜选用何方","o":["补中益气汤","参苓白术散","四君子汤","生脉散","异功散"],"a":1,"e":"脾胃气虚，运化失司则饮食不化、肠鸣泄泻，气血生化不足则面色萎黄、四肢乏力，湿浊内生则苔白腻，脉虚缓为气虚湿盛之象。参苓白术散以四君子汤健脾益气为君，配山药、莲子、白扁豆、薏苡仁健脾渗湿，砂仁醒脾，桔梗宣肺利气，益气健脾、渗湿止泻，主治脾虚湿盛之泄泻、体倦乏力。四君子汤益气健脾，主治脾胃气虚之食少便溏，渗湿止泻之力不足；补中益气汤补中益气、升阳举陷，主治气虚发热、脏器脱垂；异功散即四君子加陈皮，主治脾胃气虚兼气滞；生脉散益气养阴、敛汗生脉，主治气阴两伤之体倦汗多"},{"q":"证见胸脘痞闷，按之则痛，或咳痰黄稠，舌苔黄腻，脉滑数者，治宜选用","o":["小陷胸汤","滚痰丸","二陈汤","贝母瓜蒌散","清金化痰丸"],"a":0,"e":"痰热互结于心下，气机痞塞则胸脘痞闷、按之则痛，痰热上壅则咳痰黄稠，苔黄腻、脉滑数为痰热之象，属小结胸病。小陷胸汤以黄连清热泻火为君，半夏化痰散结，瓜蒌实清热化痰、宽胸散结，清热化痰、宽胸散结，主治痰热互结之心下痞闷、按之则痛、咳痰黄稠。二陈汤燥湿化痰、理气和中，主治湿痰之痰多色白、胸膈满闷；贝母瓜蒌散润肺化痰、理气止咳，主治燥痰之痰少而黏、咽干；滚痰丸泻火逐痰，主治实热老痰之癫狂、便秘；清金化痰丸清肺化痰，主治痰热壅肺之咳嗽痰黄，无宽胸散结之功"},{"q":"患儿，女，7岁。咳嗽9天，晨起、晚上阵咳，痰白量多，鼻塞涕稀，纳可，二便正常，舌质淡红，苔白腻，脉滑。治疗宜选的方剂是","o":["苏子降气汤化裁","止嗽散化裁","小青龙汤化裁","苓甘五味姜辛汤化裁","杏苏散化裁"],"a":3,"e":"咳嗽日久，痰白量多、鼻塞涕稀、苔白腻、脉滑为寒饮内停于肺，肺气上逆则阵咳，无发热恶寒等表证，属寒饮咳嗽，苓甘五味姜辛汤温肺化饮，主治寒饮内停之咳嗽痰多清稀。小青龙汤解表散寒、温肺化饮，主治外寒内饮之咳喘，必有恶寒发热、无汗等表证；止嗽散疏风润肺、止咳化痰，主治风邪犯肺之咳嗽迁延、咽痒，无温化寒饮之力；苏子降气汤降气平喘，主治上实下虚之喘咳、呼多吸少；杏苏散轻宣凉燥、理肺化痰，主治外感凉燥之咳嗽痰稀、恶寒头痛，均非单纯寒饮内停"},{"q":"患者小便不利，头痛微热，烦渴欲饮，甚则水入即吐，舌苔白，脉浮。主治病证是","o":["蓄血证","风水证","阴水证","蓄水证","皮水证"],"a":3,"e":"风寒外袭，膀胱气化不利，水湿内停则小便不利，外有表邪则头痛微热、脉浮，水停气不化津则烦渴欲饮，水入不化则水入即吐，此为太阳蓄水证，五苓散主之。蓄血证为瘀热互结下焦，见少腹急结、其人如狂、小便自利；风水证为风邪袭表、肺失通调，见水肿、恶风、脉浮；阴水证为脾肾阳虚，水肿身半以下为甚、手足不温、脉沉迟；皮水证为水停皮肤，全身水肿、按之没指、无口渴，均非膀胱气化不利之蓄水"},{"q":"以恶风，发热，汗出，脉浮缓为辨证要点的方剂是","o":["大青龙汤","败毒散","麻黄汤","小青龙汤","桂枝汤"],"a":4,"e":"桂枝汤解肌发表、调和营卫，以桂枝解肌散风为君，白芍敛阴和营，生姜、大枣调和营卫，甘草调和，主治外感风寒表虚证，以恶风、发热、汗出、脉浮缓为辨证要点。麻黄汤发汗解表、宣肺平喘，要点为恶寒发热、无汗而喘、脉浮紧，属表实；大青龙汤发汗解表、清热除烦，要点为不汗出而烦躁、脉浮紧；小青龙汤解表散寒、温肺化饮，要点为喘咳痰多清稀、舌苔白滑；败毒散益气解表，主治气虚外感风寒湿之憎寒壮热、无汗，均有别于表虚汗出之桂枝汤证"},{"q":"患者骨蒸潮热，或低热日久不退，形体消瘦，唇红颧赤，舌红少苔，脉细数。治疗应首选的方剂是","o":["凉膈散","清骨散","青蒿鳖甲汤","秦艽鳖甲散","知柏地黄丸"],"a":1,"e":"肝肾阴虚，虚火内扰，故骨蒸潮热、低热日久不退，阴血亏虚则形体消瘦，虚火上浮则唇红颧赤，舌红少苔、脉细数为阴虚内热之象。清骨散以银柴胡、胡黄连清虚热为君，知母、丹皮、地骨皮清热凉血，青蒿透热，鳖甲滋阴，甘草调和，清虚热，主治阴虚内热之骨蒸潮热、低热不退。青蒿鳖甲汤养阴透热，主治温病后期邪伏阴分之夜热早凉、热退无汗；秦艽鳖甲散滋阴养血、清热除蒸，主治风劳骨蒸、盗汗、咳嗽；知柏地黄丸滋阴降火，主治阴虚火旺之潮热盗汗、口干；凉膈散泻火通便，主治上中二焦火热之胸膈烦热、便秘，均非单纯骨蒸虚热"},{"q":"患者恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧。治疗应首选的方剂是","o":["桂枝汤","小青龙汤","麻黄汤","大青龙汤","败毒散"],"a":3,"e":"外感风寒，卫阳被遏则恶寒发热、头身疼痛、无汗，寒邪郁而化热，不得发越则烦躁，脉浮紧为风寒表实之象。大青龙汤以麻黄、桂枝发汗解表为君，石膏清热除烦，杏仁宣肺，生姜、大枣、甘草调和，发汗解表、清热除烦，主治外感风寒、内有郁热之不汗出而烦躁、脉浮紧。麻黄汤发汗解表、宣肺平喘，主治风寒表实之恶寒发热、无汗而喘，无里热烦躁；桂枝汤解肌发表、调和营卫，主治表虚之汗出恶风、脉浮缓；小青龙汤解表散寒、温肺化饮，主治外寒内饮之咳喘痰稀；败毒散益气解表，主治气虚外感风寒湿"},{"q":"患者，上中二焦火热证而见睡卧不宁，谵语狂妄，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["白虎汤","凉膈散","黄连解毒汤","清瘟败毒饮","羚角钩藤汤"],"a":1,"e":"上中二焦火热炽盛，热扰心神则睡卧不宁、谵语狂妄，舌红苔黄、脉滑数为里热之象。凉膈散以大黄、芒硝、栀子、黄芩等泻火通便为君，连翘、薄荷、竹叶清上焦热，甘草、蜂蜜缓和中焦，泻火通便、清上泄下，主治上中二焦火热之胸膈烦热、睡卧不宁、谵语狂妄。白虎汤清热生津，主治气分热盛之大热大汗、脉洪大；黄连解毒汤泻火解毒，主治三焦火毒炽盛之吐衄、痈疡；清瘟败毒饮清热解毒、凉血泻火，主治瘟疫热毒气血两燔之发斑、神昏；羚角钩藤汤凉肝熄风，主治热盛动风之高热惊厥、抽搐"},{"q":"患者外感，发汗后病证未解除，仍发热，头眩，身瞤动，振振欲擗地，舌淡胖，苔白滑，脉沉细。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":3,"e":"发汗太过，损伤脾肾阳气，阳虚水泛，水气上冲则头眩，水浸筋脉则身瞤动、振振欲擗地，舌淡胖苔白滑、脉沉细为阳虚水停之象。真武汤以附子温肾助阳化水为君，茯苓、白术健脾利水，生姜温散水气，白芍利小便、缓急和营，温阳利水，主治脾肾阳虚、水气内停之小便不利、四肢沉重、身瞤动。苓桂术甘汤温阳化饮，主治中阳不足之痰饮、头眩心悸；五苓散温阳化气利水，主治膀胱蓄水之小便不利、头痛微热；猪苓汤利水清热养阴，主治水热互结伤阴；实脾散温阳健脾、行气利水，主治阴水肿甚、脘腹胀满"},{"q":"冲任虚寒，瘀血阻滞之漏下证，治宜选方","o":["温经汤","生化汤","桂枝茯苓丸","血府逐瘀汤","补中益气汤"],"a":0,"e":"冲任虚寒，血寒则凝滞，瘀血阻滞胞宫，血不归经则漏下不止，温经汤以吴茱萸、桂枝温经散寒、通利血脉为君，当归、川芎、芍药、丹皮养血活血祛瘀，人参、甘草益气健脾，温经散寒、养血祛瘀，主治冲任虚寒、瘀血阻滞之漏下、月经不调。生化汤养血祛瘀、温经止痛，主治产后恶露不行、小腹冷痛；桂枝茯苓丸活血化瘀、缓消癥块，主治妇人瘀阻胞宫之妊娠漏下、腹中癥块；血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀之胸痛；补中益气汤补中益气、升阳举陷，主治气虚下陷之崩漏、脱肛，均无温经散寒之功"},{"q":"患者腰下冷痛，腰重，小便自利，舌淡苔白，脉沉迟。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","肾气丸"],"a":2,"e":"寒湿之邪着于腰部，阻遏阳气则腰下冷痛、腰重，寒湿不碍膀胱气化则小便自利，舌淡苔白、脉沉迟为寒湿之象，此即肾著病。肾著汤以干姜温中散寒为君，茯苓、白术健脾渗湿，甘草缓急和中，温肾除湿，主治寒湿著腰之腰痛、腰重。独活寄生汤养血舒筋、祛风除湿，主治痹证日久、肝肾两虚之腰膝疼痛；羌活胜湿汤祛风胜湿，主治风湿在表之肩背痛、头痛身重；大秦艽汤疏风清热、养血活血，主治风邪中经络之口眼㟀斜、手足不用；肾气丸温补肾阳，主治肾阳不足之腰痛脚软、小便不利，均非寒湿著腰"},{"q":"患者咳唾胸胁引痛，心下痞硬，干呕短气，头痛目眩，舌苔白滑，脉沉弦。治疗应首选方剂是","o":["小柴胡汤","大柴胡汤","小青龙汤","十枣汤","苓桂术甘汤"],"a":3,"e":"水饮停于胸胁，为悬饮，饮邪上逆则咳唾胸胁引痛，水停心下则心下痞硬，胃气上逆则干呕，肺气不利则短气，饮邪上犯则头痛目眩，苔白滑、脉沉弦为水饮之象。十枣汤以甘遂、大戟、芫花峻下逐水，大枣缓和药毒、顾护脾胃，攻逐水饮，主治悬饮之咳唾胸胁引痛、心下痞硬。苓桂术甘汤温阳化饮、健脾利湿，主治中阳不足之痰饮，胸胁满闷、头眩心悸，力缓；小青龙汤解表散寒、温肺化饮，主治外寒内饮之咳喘痰稀；小柴胡汤和解少阳，主治往来寒热、胸胁苦满；大柴胡汤和解少阳、通下里实，主治往来寒热、心下痞硬、大便秘结"},{"q":"患者身热无汗，头痛身疼，项背拘急，胸满恶食，呕吐腹痛，血气不和，心腹疼痛，月经不调。治疗应首选的方剂是","o":["五积散","麻黄汤","九味羌活汤","藿香正气散","败毒散"],"a":0,"e":"外感风寒湿邪，内有痰饮食积，气血凝滞，故身热无汗、头痛身疼、项背拘急，气滞则胸满恶食、呕吐腹痛，血滞则心腹疼痛、月经不调，五积散以麻黄、桂枝、白芷等发散风寒，苍术、厚朴、陈皮等燥湿理气，当归、川芎、芍药活血和血，半夏、茯苓化痰，散寒祛湿、理气活血、化痰消积，主治外感风寒湿、内伤生冷之五积证。麻黄汤发汗平喘，主治风寒表实之无汗而喘；九味羌活汤解表祛湿清热，主治外感寒湿兼里热之口苦微渴；藿香正气散解表化湿，主治吐泻；败毒散益气解表，主治气虚外感"},{"q":"妇人漏下不止，血色黯而有块，淋漓不畅，舌质黯红，脉细而涩。治疗应首选的方剂是","o":["复元活血汤","桂枝茯苓丸","失笑散","生化汤","温经汤"],"a":4,"e":"冲任虚寒，瘀血内阻，血不归经则漏下不止，血色黯而有块、淋漓不畅，舌黯红、脉细涩为瘀血之象。温经汤温经散寒、养血祛瘀，以吴茱萸、桂枝温经通脉，当归、川芎、芍药、丹皮养血活血，阿胶养血止血，人参、甘草益气，主治冲任虚寒、瘀血阻滞之漏下不止、月经不调。桂枝茯苓丸活血化瘀、缓消癥块，主治瘀阻胞宫之腹中癥块、漏下，无温经散寒之力；生化汤养血祛瘀，主治产后恶露不行、小腹冷痛；失笑散活血止痛，主治瘀血停滞之心腹剧痛；复元活血汤活血祛瘀、疏肝通络，主治跌打损伤、瘀留胁下"},{"q":"患者五更泄泻，不思饮食，食不消化，舌淡，苔薄白，脉沉迟无力。治疗首先的方剂是","o":["四神丸","理中丸","真人养脏汤","桃花汤","补中益气汤"],"a":0,"e":"肾阳不足，命门火衰，不能温煦脾土，黎明前阳气未复、阴寒极盛则五更泄泻，脾失运化则不思饮食、食不消化，舌淡苔薄白、脉沉迟无力为脾肾阳虚之象。四神丸以补骨脂温补肾阳为君，肉豆蔻温中涩肠，五味子敛肺涩肠，吴茱萸温中散寒，温肾暖脾、固肠止泻，主治脾肾阳虚之五更泄泻。理中丸温中祛寒、补气健脾，主治脾胃虚寒之自利不渴，无温肾之功；真人养脏汤涩肠止泻、温中补虚，主治久泻久痢、脾肾虚寒之脱肛；桃花汤温中涩肠止痢，主治虚寒痢之下利便脓血；补中益气汤补气升阳，主治气虚下陷之泄泻、脱肛"},{"q":"患者身热谵语，斑色紫黑，舌深绛起刺，脉数。治疗应首选的方剂是","o":["清营汤","犀角地黄汤","清暑益气汤","青蒿鳖甲汤","黄连解毒汤"],"a":1,"e":"热入血分，热毒炽盛，迫血妄行则发斑，斑色紫黑为热毒极盛、血络瘀滞，热扰心神则身热谵语，舌深绛起刺、脉数为血分实热之象。犀角地黄汤以水牛角清热解毒为君，生地凉血养阴，赤芍、丹皮凉血散瘀，清热解毒、凉血散瘀，主治热入血分之吐血、衄血、发斑、神昏谵语。清营汤清营解毒、透热养阴，主治热入营分之身热夜甚、斑疹隐隐，热毒未盛；黄连解毒汤泻三焦火毒，主治火毒炽盛之烦躁吐衄，无凉血散斑之功；青蒿鳖甲汤养阴透热，主治邪伏阴分之夜热早凉；清暑益气汤清暑益气养阴，主治暑热耗气伤津"},{"q":"患者出现产后恶露不行，小腹冷痛，拒按，脉细涩，舌质黯淡。治疗应首选的方剂是","o":["生化汤","温经汤","十灰散","少腹逐瘀汤","温脾汤"],"a":0,"e":"产后血虚受寒，寒凝血瘀，恶露不行，瘀阻小腹则冷痛拒按，脉细涩、舌质黯淡为血虚寒凝之象。生化汤以当归养血活血为君，川芎、桃仁活血祛瘀，炮姜温经散寒止痛，甘草缓急，童便化瘀，养血祛瘀、温经止痛，主治产后恶露不行、小腹冷痛，为产后常用方。温经汤温经散寒、养血祛瘀，主治冲任虚寒之漏下、月经不调，非产后专方；少腹逐瘀汤活血祛瘀、温经止痛，主治寒凝血瘀之少腹积块、痛经；十灰散凉血止血，主治血热妄行之吐血、衄血；温脾汤温阳攻下，主治寒积便秘"},{"q":"患者腹痛时作时止，往来上下，或呕吐清水涎沫，或吐蛔虫，多食而瘦，面色青黄。治疗应首选的方剂是","o":["乌梅丸","化虫丸","吴茱萸汤","健脾丸","枳实导滞丸"],"a":1,"e":"虫积肠道，扰乱气机则腹痛时作时止、往来上下，虫扰胃腑则呕吐清水涎沫或吐蛔虫，虫耗气血则多食而瘦、面色青黄，化虫丸以鹤虱、槟榔、苦楝根皮、铅粉等杀虫，使君子、芜荑助之，杀肠中诸虫，主治肠道诸虫证。乌梅丸寒热并调、安蛔止痛，主治蛔厥之腹痛烦闷、呕吐蛔虫、手足厥冷，侧重安蛔；吴茱萸汤温中补虚、降逆止呕，主治肝胃虚寒之头痛、吐涎沫；健脾丸健脾和胃、消食止泻，主治脾虚食积；枳实导滞丸消积导滞、清利湿热，主治湿热食积之脘腹胀痛、下痢，均无杀虫之功"},{"q":"患者往来寒热，胸胁苦满，呕不止，郁郁微烦，心下痞硬，协热下利，舌苔黄，脉弦数有力。治疗应首选的方剂是","o":["大承气汤","小柴胡汤","败毒散","大柴胡汤","防风通圣散"],"a":3,"e":"邪郁少阳则往来寒热、胸胁苦满，邪热内传阳明、腑气不通则呕不止、郁郁微烦、心下痞硬、协热下利，苔黄、脉弦数有力为少阳阳明合病之象。大柴胡汤以柴胡、黄芩和解少阳为君，大黄、枳实泻下热结，半夏、生姜和胃降逆，白芍缓急，和解少阳、内泻热结，主治少阳阳明合病。小柴胡汤和解少阳，主治少阳证之往来寒热、胸胁苦满、口苦咽干，无泻下之功；大承气汤峻下热结，主治阳明腑实之痞满燥实，无和解少阳之力；防风通圣散疏风解表、泻热通便，主治外感风邪、内有蕴热之表里俱实；败毒散益气解表，主治气虚外感"},{"q":"患者便秘5天。现仍大便不通，频转矢气，脘腹痞满，腹痛拒按。医生开出大承气汤，嘱咐患者使用注意不正确的是","o":["临卧服","中病即止","勿食油腻及不易消化的食物","大黄后下","芒硝溶服"],"a":0,"e":"大承气汤峻下热结，服法当空腹或顿服以使药力集中攻下，并中病即止，不可久服；大黄后下以保其泻下之力，芒硝溶服以取其软坚润燥，服药期间忌油腻及不易消化食物。临卧服并非本方要求，睡前服药不利于观察下利反应与及时调整，且峻下之剂夜间服用易致虚脱，故临卧服为不正确的使用注意。中病即止、忌油腻、大黄后下、芒硝溶服均为大承气汤正确的煎服与调护方法"},{"q":"咳血方中用以清肝泻火的药物是","o":["青黛","龙胆草","黄芩","大黄","柴胡"],"a":0,"e":"咳血方以青黛、栀子清肝泻火为君，瓜蒌仁、海粉清肺化痰，诃子敛肺止咳，共奏清肝宁肺、凉血止血之功，主治肝火犯肺之咳血，方中清肝泻火者首推青黛。龙胆草虽善清肝胆实火，但非咳血方组成，多用于龙胆泻肝汤；黄芩清上焦肺火，侧重清肺而非清肝；大黄泻下攻积、凉血逐瘀，主治热结便秘或血热吐衄；柴胡疏肝解郁、升举阳气，无清肝泻火之力，均非咳血方中清肝泻火之药"},{"q":"暴哑为大寒直犯肺肾，上窒窍隧，下闭肾气所致者，治疗首选的方剂是","o":["回阳救急汤","肾气丸","右归丸","参附汤","麻黄附子细辛汤"],"a":4,"e":"大寒直犯肺肾，寒邪上窒咽喉窍隧则暴哑，下闭肾气则气化不行，麻黄附子细辛汤以附子温肾助阳为君，麻黄发散风寒、宣肺开音，细辛助阳散寒、通窍，助阳解表、温经散寒，主治阳虚外感风寒之暴哑、恶寒、脉沉。回阳救急汤回阳固脱、益气生脉，主治寒邪直中三阴之四肢厥冷、脉微欲绝；肾气丸温补肾阳、化气行水，主治肾阳不足之腰痛脚软、小便不利；右归丸温补肾阳、填精益髓，主治命门火衰之神疲畏寒；参附汤回阳救逆，主治阳气暴脱之四肢厥逆、大汗，均非温经解表开音"},{"q":"患者面目俱黄，黄色鲜明，发热无汗，口渴欲饮，小便短赤，大便不爽，舌红苔黄腻，脉滑数有力。本证的病机是","o":["湿热阻滞，熏蒸肝胆","湿热瘀滞，熏蒸肝胆","湿热瘀滞，熏蒸胆胃","湿热痰滞，熏蒸肝胆","湿热阻滞，熏蒸脾胃"],"a":1,"e":"湿热蕴结肝胆，胆汁外溢则身目俱黄、黄色鲜明，热重于湿则发热、口渴、小便短赤，湿热兼瘀则舌红苔黄腻、脉滑数有力，故病机为湿热瘀滞、熏蒸肝胆，茵陈蒿汤主之，方中大黄兼能泄热逐瘀。湿热阻滞、熏蒸肝胆虽指阳黄常理，但本证大便不爽、脉滑数有力兼有瘀滞，非单纯阻滞可概；湿热瘀滞、熏蒸胆胃病位偏胃，当见呕酸、嘈杂；湿热痰滞、熏蒸肝胆当见痰多、苔腻偏滑；湿热阻滞、熏蒸脾胃病在中焦，当见脘腹胀满、便溏，均非湿热瘀滞熏蒸肝胆之阳黄"},{"q":"患者大便干结，小便频数，脘腹胀痛，舌红苔黄，脉数。治疗应首选的方剂是","o":["大承气汤","小承气汤","麻子仁丸","济川煎","黄龙汤"],"a":2,"e":"脾约证，胃热肠燥、津液不足，肠道失润则大便干结，脾虚不能为胃行其津液、水液直趋膀胱则小便频数，脘腹胀痛、舌红苔黄、脉数为胃热肠燥之象。麻子仁丸以麻子仁润肠通便为君，杏仁、白芍润肠缓急，大黄、枳实、厚朴泄热行气通便，润肠泄热、行气通便，主治脾约之大便干结、小便频数。大承气汤峻下热结，主治痞满燥实俱全之阳明腑实；小承气汤轻下热结，主治腑实轻证；济川煎温肾益精、润肠通便，主治肾虚肠燥之便秘、腰膝酸软；黄龙汤泻热通便兼补气血，主治热结旁流而气血虚"},{"q":"患者心下至少腹硬满疼痛而痛不可近，大便秘结，短期烦躁，舌燥而渴，脉沉紧，按之有力。本病的病机是","o":["水热互结于心下","痰热互结与心下","瘀热互结与心下","水湿结聚与心下","寒积心下"],"a":0,"e":"水热互结于胸腹，热实内盛则心下至少腹硬满疼痛、痛不可近，腑气不通则大便秘结，热扰心神则烦躁，津伤则舌燥而渴，脉沉紧、按之有力为水热结实之象，属大陷胸汤证，故病机为水热互结于心下。痰热互结于心下为小陷胸汤证，仅心下痞闷、按之则痛，病位局限、病情较轻；瘀热互结当见舌黯有瘀点、痛如针刺；水湿结聚无热象，当见苔白滑、口不渴；寒积心下当见手足不温、苔白腻、脉沉迟，均非水热互结之结胸重证"},{"q":"患者大便秘结，小便清长，腰膝酸冷，舌淡苔白，脉沉迟。治疗应首选方剂是","o":["济川煎","肾气丸","五仁丸","温脾汤","脾约丸"],"a":0,"e":"肾阳不足、精血亏虚，肠失温煦濡润则大便秘结，肾虚不固则小便清长，腰膝失养则酸冷，舌淡苔白、脉沉迟为阳虚里寒之象。济川煎以肉苁蓉温肾益精、润肠通便为君，当归养血润肠，牛膝引药下行、强壮腰膝，泽泻渗湿，升麻升清阳，枳壳宽肠下气，温肾益精、润肠通便，主治肾虚便秘。温脾汤温阳攻下，主治寒积便秘之腹痛、手足不温；麻子仁丸润肠泄热，主治脾约之大便干结、小便频数，非清长；五仁丸润肠通便，主治津枯肠燥便秘，无温肾之功；肾气丸温补肾阳、化气行水，主治水肿、小便不利，均非肾虚肠燥便秘"},{"q":"时值深秋，患者头微痛，恶寒无汗，咳嗽痰稀，鼻塞咽干已两日，苔白，脉弦。宜首选的方剂是","o":["桑杏汤","麻黄汤","杏苏散","清燥救肺汤","桑菊饮"],"a":2,"e":"深秋凉燥外袭，燥邪收引则恶寒无汗、头微痛，凉燥束肺则咳嗽痰稀、鼻塞，燥胜则咽干，苔白、脉弦为凉燥之象。杏苏散以苏叶轻宣凉燥为君，杏仁宣肺止咳，前胡、桔梗、枳壳宣降气机，半夏、陈皮、茯苓理气化痰，轻宣凉燥、理肺化痰，主治外感凉燥之头微痛、恶寒无汗、咳嗽痰稀。桑杏汤清宣温燥，主治外感温燥之身热、干咳无痰、咽干口渴；清燥救肺汤清燥润肺，主治燥热伤肺之干咳气喘、咽干鼻燥；麻黄汤发汗平喘，主治风寒表实之无汗而喘；桑菊饮疏风清热，主治风热轻证之咳嗽、微渴，均非凉燥"},{"q":"升麻葛根汤的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热，喘咳，苔黄，脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":4,"e":"升麻葛根汤以升麻、葛根解肌透疹为君，芍药、甘草养血和营，解肌透疹，主治麻疹初起，以疹发不出或出而不畅、舌红、脉数为辨证要点。咳嗽、发热不甚、微渴、脉浮数为桑菊饮之风热犯肺轻证；发热、喘咳、苔黄、脉数为麻黄杏仁甘草石膏汤之邪热壅肺；发热重、恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪为柴葛解肌汤之三阳合病；发热、微恶寒、咽痛、口渴、脉浮数为银翘散之风热表证，均非麻疹透发不畅之辨证要点"},{"q":"患者，男，22岁。心下至少腹硬满疼痛而痛不可近，大便秘结，日晡潮热，舌燥而渴，脉沉紧，按之有力。医生开出的方剂是大陷胸汤，方中君药是","o":["大黄","芒硝","甘遂","大戟","芫花"],"a":2,"e":"大陷胸汤以甘遂为君，甘遂善攻逐水饮、泻热破结，直达胸腹水热互结之处，力猛效专；大黄泻热通腑，芒硝软坚润燥，共为臣药，三药合用泻热逐水破结，主治水热互结之结胸证，心下至少腹硬满疼痛、大便秘结。大黄虽常被误认作君药，实则助甘遂泻热通便，居臣位；芒硝咸寒软坚，辅助散结；大戟、芫花虽与甘遂同为峻下逐水之品，但非大陷胸汤组成，十枣汤方用之，均非本方君药"},{"q":"症见大便下血，先便后血，血色黯淡，伴有四肢不温，面色萎黄，舌淡苔白，脉沉细无力，治宜选用","o":["槐花散","黄土汤","芍药汤","归脾汤","理中丸"],"a":1,"e":"脾阳不足、中焦虚寒，不能统血，血渗肠道则大便下血、先便后血，血色黯淡，阳虚不温则四肢不温，血虚则面色萎黄，舌淡苔白、脉沉细无力为脾虚寒之象。黄土汤以灶心土温中止血为君，白术、附子温阳健脾，生地、阿胶养血止血，黄芩苦寒坚阴、反佐温药，温阳健脾、养血止血，主治脾阳不足之便血。槐花散清肠疏风、凉血止血，主治肠风脏毒之便血、血色鲜红；芍药汤清热燥湿、调气和血，主治湿热痢之腹痛便脓血；归脾汤益气补血、健脾养心，主治心脾两虚之便血、崩漏；理中丸温中祛寒，无养血止血之功"},{"q":"患者痈疽溃后，脓水稀少，腐肉不去，新肉不生，神倦，面色少华，脉虚无力。首选治疗方剂是","o":["补中益气汤","托里消毒散","四妙勇安汤","仙方活命饮","阳和汤"],"a":1,"e":"痈疽溃后，气血两虚，正气不足不能托毒外出，故脓水稀少、腐肉不去、新肉不生，神倦、面色少华、脉虚无力为气血亏虚之象。托里消毒散以人参、黄芪、白术、茯苓等补益气血为君，当归、川芎养血活血，皂角刺、桔梗、白芷等托毒排脓，补益气血、托毒生肌，主治气血不足之痈疽溃后、久不收口。仙方活命饮清热解毒、消肿溃坚，主治阳证痈疡肿毒初起之红肿热痛；阳和汤温阳补血、散寒通滞，主治阴疽漫肿无头、皮色不变；四妙勇安汤清热解毒、活血止痛，主治热毒炽盛之脱疽；补中益气汤补中益气、升阳举陷，无托毒生肌之功"},{"q":"患者，男，68岁。平素易感冒，此次因气温突降而感冒2天，腹泻1天，症见“恶寒发热，头痛，肢体酸痛，无汗，鼻塞，泄泻伴腹痛，舌淡苔白，脉浮而按之无力”。治疗首选的方剂是","o":["九味羌活汤","参苏饮","麻黄汤","败毒散","葱白七味饮"],"a":3,"e":"平素易感冒、脉浮而按之无力为气虚之体，复感风寒湿邪则恶寒发热、头痛、肢体酸痛、无汗、鼻塞，湿邪犯脾则泄泻腹痛，舌淡苔白为虚寒之象。败毒散以人参益气扶正为君，羌活、独活、川芎、柴胡等散风祛湿解表，桔梗、枳壳、前胡、茯苓理气化痰，益气解表、散风祛湿，主治气虚外感风寒湿之憎寒壮热、无汗、肢体酸痛。参苏饮益气解表、理气化痰，主治气虚外感风寒兼痰湿之咳嗽痰多、胸脘满闷；九味羌活汤解表祛湿清热，主治外感寒湿兼里热之口苦微渴；麻黄汤发汗平喘，主治风寒表实而无气虚；葱白七味饮养血解表，主治血虚外感"},{"q":"患者遗精淋浊，血崩带下，遇劳则发。治疗应首选的方剂是","o":["导赤散","八正散","完带汤","归脾汤","清心莲子饮"],"a":4,"e":"心火亢盛、气阴两虚，心火下移小肠则淋浊，扰动精室则遗精，热伤冲任则血崩带下，遇劳则发为气虚之象，清心莲子饮以黄芩、麦冬、地骨皮清热养阴为君，石莲子、茯苓、车前子清心利湿，人参、黄芪、甘草益气，清心火、益气阴、止淋浊，主治心火亢盛、气阴两虚之遗精淋浊、血崩带下。导赤散清心利水养阴，主治心火移热小肠之小便赤涩；八正散清热利水通淋，主治湿热热淋之尿频尿急；完带汤补脾疏肝、化湿止带，主治脾虚肝郁之带下清稀；归脾汤益气补血、健脾养心，主治心脾两虚之崩漏、便血，均无清心止淋之功"},{"q":"患者发热咳嗽，口渴欲饮，心烦不寐，小便不利，舌红苔微黄，脉细数。主治病证是","o":["水热互结伤阴证","瘀热互结伤阴证","湿热互结伤阴证","痰瘀互结伤阴证","痰热互结伤阴证"],"a":0,"e":"水热互结于下焦，热邪伤阴，水液不行则小便不利，热灼肺胃则发热、咳嗽、口渴欲饮，热扰心神则心烦不寐，舌红苔微黄、脉细数为水热互结伤阴之象，猪苓汤主之，故病机为水热互结伤阴证。瘀热互结伤阴当见舌黯有瘀点、少腹硬满、小便自利；湿热互结伤阴当见身黄、苔黄腻、口渴不欲饮；痰热互结伤阴当见咳痰黄稠、胸闷；痰瘀互结伤阴当见痰多、舌黯、苔腻，均非本证发热、口渴、小便不利之水热互结伤阴"},{"q":"麻黄汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":2,"e":"麻黄汤发汗解表、宣肺平喘，主治外感风寒表实证，以恶寒发热、无汗而喘、脉浮紧为辨证要点。恶寒发热、头身疼痛、不汗出而烦躁、脉浮紧为大青龙汤之表寒里热证；恶风、发热、汗出、脉浮缓为桂枝汤之表虚证；恶寒发热、头痛无汗、肢体酸楚疼痛、口苦微渴为九味羌活汤之外感寒湿兼里热；恶寒发热、无汗、喘咳、痰多而稀、舌苔白滑、脉浮为小青龙汤之外寒内饮，均非麻黄汤单纯风寒表实之辨证要点"},{"q":"患者带下量多，清稀色白，无异味，大便溏薄，舌淡苔白，脉缓。治疗应首选的方剂是","o":["完带汤","清带汤","二妙散","易黄汤","固冲汤"],"a":0,"e":"脾虚肝郁，脾失运化则湿浊内停，带脉失约则带下量多、清稀色白、无异味，脾虚湿盛则大便溏薄，舌淡苔白、脉缓为脾虚湿盛之象。完带汤以白术、山药健脾益气为君，苍术、陈皮燥湿理气，白芍、柴胡疏肝，车前子利湿，荆芥穗祛风胜湿，补脾疏肝、化湿止带，主治脾虚肝郁之带下清稀。易黄汤补脾益肾、清热祛湿，主治脾肾两虚、湿热下注之带下色黄腥臭；二妙散清热燥湿，主治湿热下注之带下黄稠、阴肿阴痒；清带汤健脾化湿、收涩止带，主治脾虚带下；固冲汤益气健脾、固冲摄血，主治脾肾亏虚之崩漏，均非脾虚肝郁之清稀带下"},{"q":"主治为阴血亏虚、心肾失调之精神恍惚，惊悸怔忡，夜寐多梦，健忘盗汗，舌红少苔，脉细而数的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","柏子养心丸","养心汤"],"a":3,"e":"阴血亏虚、心肾失调，心神失养则精神恍惚、惊悸怔忡、夜寐多梦、健忘，阴虚火旺则盗汗，舌红少苔、脉细数为阴虚之象。柏子养心丸以柏子仁养心安神为君，配熟地、枸杞、当归等滋阴养血，麦冬、玄参养阴清热，石菖蒲、远志开窍安神，滋阴养血、补心安神，主治阴血亏虚、心肾失调之精神恍惚、惊悸失眠。天王补心丹滋阴养血、补心安神，主治阴虚血少之心悸怔忡、虚烦失眠、口舌生疮；朱砂安神丸镇心安神、清热养血，主治心火亢盛之失眠多梦、胸中烦热；酸枣仁汤养血安神、清热除烦，主治肝血不足之虚烦不眠；养心汤益气养血安神，主治心虚血少之惊悸"},{"q":"患者微恶风寒，头痛无汗，鼻塞流涕，喷嚏频作，舌苔薄白，脉浮。治宜选用","o":["桑菊饮","桑杏汤","杏苏散","清燥救肺汤","葱豉汤"],"a":4,"e":"外感风寒初起，邪轻在表，卫阳被遏则微恶风寒、头痛无汗，肺气不宣则鼻塞流涕、喷嚏频作，苔薄白、脉浮为风寒表证之轻者。葱豉汤以葱白通阳发汗、豆豉解表宣郁，通阳解表，主治外感风寒初起之头痛、恶寒、无汗、鼻塞，药简力专。桑菊饮疏风清热、宣肺止咳，主治风热犯肺之咳嗽、发热不甚；桑杏汤清宣温燥，主治外感温燥之干咳、咽干；杏苏散轻宣凉燥，主治凉燥之恶寒无汗、咳嗽痰稀；清燥救肺汤清燥润肺，主治燥热伤肺之干咳气喘、咽干，均非风寒初起之轻证"},{"q":"患者身重疼痛，胸闷不饥，午后身热，面色淡黄，舌淡苔白，脉弦细而濡。治疗应首选的治法是","o":["宣畅气机，清热解毒","宣畅气机，淡渗利湿","宣畅气机，芳化湿浊","宣畅气机，清利湿热","宣畅气机，清化瘀热"],"a":3,"e":"湿温初起，湿邪郁遏气机则身重疼痛、胸闷不饥，湿郁化热则午后身热，湿热熏蒸则面色淡黄，舌淡苔白、脉弦细而濡为湿重于热之象，三仁汤主之，治宜宣畅气机、清利湿热。宣畅气机、淡渗利湿偏于利水，主治水湿内停之水肿、小便不利；宣畅气机、芳化湿浊主治湿浊中阻之脘痞、口黏；宣畅气机、清热解毒主治湿热毒邪之疮疡、咽痛；宣畅气机、清化瘀热主治湿热兼瘀之疼痛固定、舌黯，均非湿温初起宣上畅中渗下之治法"},{"q":"患者头痛身热，干咳无痰，气逆而喘，咽喉干燥，鼻燥，胸满胁痛，心烦口渴，舌干少苔，脉虚大而数。治疗宜首选的方剂是","o":["桑菊饮","玉液汤","银翘散","清燥救肺汤","养阴清肺汤"],"a":3,"e":"燥热伤肺，耗伤气阴，肺失宣降则干咳无痰、气逆而喘，燥热上攻则头痛身热、咽喉干燥、鼻燥，气机不利则胸满胁痛，津伤则心烦口渴、舌干少苔，脉虚大而数为气阴两伤之象。清燥救肺汤以桑叶清宣燥热为君，石膏、麦冬清热养阴，人参、甘草益气生津，杏仁、枇杷叶降肺气，阿胶、胡麻仁养阴润燥，清燥润肺、益气养阴，主治燥热伤肺之干咳气喘。银翘散辛凉解表，主治风热表证之发热咽痛；桑菊饮疏风止咳，主治风热轻证咳嗽；养阴清肺汤养阴清肺解毒，主治白喉之喉间白膜；玉液汤益气滋阴止渴，主治消渴"},{"q":"患者，热入血分而见吐血、衄血，舌深绛起刺，脉数。治疗应首选的方剂是","o":["十灰散","犀角地黄汤","黄连解毒汤","清瘟败毒饮","小蓟饮子"],"a":1,"e":"热入血分，热毒炽盛，迫血妄行则吐血、衄血，舌深绛起刺、脉数为血分实热之象。犀角地黄汤以水牛角清热解毒为君，生地凉血养阴，赤芍、丹皮凉血散瘀，清热解毒、凉血散瘀，主治热入血分之吐血、衄血、发斑，使热清血宁而不留瘀。十灰散凉血止血，主治血热妄行之吐血、衄血，侧重止血而无散瘀；黄连解毒汤泻三焦火毒，主治火毒炽盛之烦躁、吐衄，无凉血散瘀之功；清瘟败毒饮气血两清，主治瘟疫热毒气血两燔之发斑、神昏；小蓟饮子凉血止血、利水通淋，主治热结下焦之血淋、尿血"},{"q":"患者，女，53岁，暑月前来就诊，症见身热烦渴，小便不利，或泄泻。此病证的治法是","o":["解表清里","化湿和中","清暑利湿","清肺平喘","疏风清热"],"a":2,"e":"暑月感受暑湿，暑热伤津则身热烦渴，湿邪内阻、气化不利则小便不利，湿邪下注则泄泻，此属暑湿证，六一散主之，治宜清暑利湿。解表清里主治外有表邪、内有里热之发热恶寒、烦躁；化湿和中主治湿滞中焦之脘痞、吐泻而无明显暑热；清肺平喘主治邪热壅肺之发热喘咳；疏风清热主治风热表证之发热咽痛，均非暑月身热烦渴、小便不利之暑湿治法"},{"q":"患者疮痈内已成脓，无力外溃，漫肿无头，痠胀热痛。首选治疗方剂是","o":["苇茎汤","消瘰丸","黄连解毒汤","透脓散","大黄牡丹汤"],"a":3,"e":"疮痈成脓，正气不足，无力托毒外溃，故漫肿无头、痠胀热痛、脓成不溃，透脓散以黄芪补气托毒为君，当归、川芎养血活血，皂角刺、穿山甲、桔梗等活血消肿、通络溃坚，补气养血、托毒溃脓，主治气血不足、疮痈脓成不溃。仙方活命饮清热解毒、消肿溃坚，主治阳证痈疡初起之红肿热痛，脓未成者；大黄牡丹汤泻热破瘀，主治肠痈初起之少腹肿痞；苇茎汤清肺排脓，主治肺痈之咳吐腥臭脓血；消瘰丸清热化痰、软坚散结，主治痰火郁结之瘰疬，均非托毒溃脓"},{"q":"患者大热渴饮，头痛如劈，干呕狂躁，谵语神昏，舌绛唇焦，脉沉细数。治疗应首选的方剂是","o":["白虎汤","竹叶石膏汤","普济消毒饮","黄连解毒汤","清瘟败毒饮"],"a":4,"e":"瘟疫热毒，气血两燔，气分热盛则大热渴饮、头痛如劈，热毒上逆则干呕，热扰心神则狂躁谵语、神昏，热入血分则舌绛唇焦，脉沉细数为热毒深伏之象。清瘟败毒饮合白虎、犀角地黄、黄连解毒三方之意，清热解毒、凉血泻火，气血两清，主治瘟疫热毒气血两燔。白虎汤清气分热，主治大热大汗大渴、脉洪大，无凉血解毒之力；黄连解毒汤泻三焦火毒，无清营凉血、开窍之功；普济消毒饮疏风清热解毒，主治大头瘟头面红肿；竹叶石膏汤清热生津、益气和胃，主治热病后气阴两伤"},{"q":"患者，女，6岁。病后持续性咳嗽，咯痰，清晨或夜间咳嗽严重，伴有气喘，脘痞，食少难消，舌苔白腻，脉滑。治疗宜选的方剂是","o":["泻白散","苏子降气汤","小青龙汤","三子养亲汤","定喘汤"],"a":3,"e":"病后脾虚，痰浊内生，壅肺则咳嗽咯痰、气喘，食积内停则脘痞、食少难消，痰随气逆则晨起、夜间咳甚，苔白腻、脉滑为痰湿食积之象。三子养亲汤以白芥子温肺化痰、苏子降气化痰、莱菔子消食导滞，温肺化痰、降气消食，主治痰壅气逆食滞之咳嗽喘逆、痰多食少。苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳、呼多吸少；定喘汤宣肺降气、清热化痰，主治痰热内蕴之哮喘、痰黄稠；小青龙汤解表散寒、温肺化饮，主治外寒内饮之咳喘痰稀；泻白散泻肺清热，主治肺热喘咳、皮肤蒸热，均非痰食互结之咳嗽"},{"q":"患者，女，20岁。感冒1天。症见恶寒发热，头痛无汗，胸脘痞闷，不欲饮食，并伴恶心，舌苔薄白，脉浮。可用下列何方加味治疗","o":["香苏散","葱豉桔梗汤","败毒散","九味羌活汤","小青龙汤"],"a":0,"e":"外感风寒，邪郁肌表则恶寒发热、头痛无汗、脉浮，气机不畅则胸脘痞闷、不欲饮食，胃气上逆则恶心，苔薄白为风寒在表。香苏散以香附疏肝理气为君，紫苏发散风寒，陈皮理气和中，甘草调和，疏散风寒、理气和中，主治外感风寒兼气滞之恶寒发热、头痛无汗、胸脘痞闷。九味羌活汤解表散寒、祛湿清热，主治外感寒湿兼里热之肢体酸楚、口苦微渴；败毒散益气解表，主治气虚外感之憎寒壮热、脉浮无力；小青龙汤温肺化饮，主治外寒内饮之咳喘痰稀；葱豉桔梗汤疏风清热，主治风热感冒之咽痛口渴"},{"q":"患者小便频数、浑浊不清，白如米泔，舌淡苔白，脉沉。治疗应首选的方剂是","o":["导赤散","小蓟饮子","萆薢分清饮","八正散","猪苓汤"],"a":2,"e":"肾阳不足，分清泌浊失司，湿浊下注膀胱则小便频数、浑浊不清、白如米泔，舌淡苔白、脉沉为肾虚寒湿之象，属膏淋。萆薢分清饮以萆薢利湿去浊为君，石菖蒲化浊，益智仁温肾缩尿，乌药温膀胱气化，温肾利湿、分清化浊，主治肾虚湿浊之膏淋、白浊。八正散清热利水通淋，主治湿热热淋之尿频尿急、溺时涩痛、尿色黄赤；小蓟饮子凉血止血、利水通淋，主治血淋尿血；导赤散清心利水，主治心火移热小肠之小便赤涩；猪苓汤利水清热养阴，主治水热互结伤阴之小便不利、口渴，均非温肾化浊"},{"q":"患者肩背痛不可回顾，头痛身重，舌淡苔白，脉浮。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":1,"e":"风湿之邪郁于肌表，阻遏阳气、经气不利则肩背痛不可回顾、头痛身重，舌淡苔白、脉浮为风湿在表之象。羌活胜湿汤以羌活、独活祛风胜湿为君，藁本、防风、川芎等祛风止痛，蔓荆子清头目，甘草调和，祛风胜湿，主治风湿在表之肩背痛、头痛身重。独活寄生汤养血舒筋、祛风除湿、补益肝肾，主治痹证日久、肝肾两虚之腰膝疼痛；九味羌活汤解表散寒、祛湿清热，主治外感寒湿兼里热之口苦微渴；肾著汤温肾除湿，主治寒湿著腰之腰重冷痛；大秦艽汤疏风清热、养血活血，主治风邪中经络之口眼㟀斜，均非风湿在表之肩背痛"},{"q":"患者，男，61岁。10天前因劳累后出现头痛，头部昏蒙，隐隐作痛，偶有胸闷，乏力，纳差，二便调，舌淡苔白腻，脉弦滑。治疗应首选的方剂是","o":["半夏白术天麻汤加竹茹、黄连","半夏白术天麻汤加黄芪、川芎","川芎茶调散加苍术、厚朴","九味羌活汤加陈皮、茯苓","二陈汤加川芎"],"a":1,"e":"头昏蒙隐痛、胸闷、苔白腻、脉弦滑为风痰上扰，乏力、纳差、舌淡为脾虚气弱，故用半夏白术天麻汤化痰熄风、健脾祛湿，加黄芪补气、川芎活血行气止痛，标本兼顾。加竹茹、黄连者清化痰热，主治痰郁化热之头胀痛、口苦苔黄；川芎茶调散疏风止痛，加苍术、厚朴燥湿，主治外感风邪兼湿之头痛；九味羌活汤解表祛湿清热，加陈皮、茯苓理气健脾，主治外感寒湿兼里热；二陈汤燥湿化痰，加川芎行气活血，无熄风之力，均非本证风痰上扰兼气虚之治"},{"q":"患者瘀阻头面，头痛昏晕，耳聋，脱发，面色青紫，治宜选用","o":["血府逐瘀汤","通窍活血汤","少腹逐瘀汤","身痛逐瘀汤","复元活血汤"],"a":1,"e":"瘀血阻于头面，清窍失养、经络不通则头痛昏晕、耳聋、脱发，面色青紫为瘀血之象。通窍活血汤以麝香开窍通络为君，桃仁、红花、赤芍、川芎等活血化瘀，老葱、生姜、大枣通阳和营，活血化瘀、通窍活络，主治瘀阻头面之头痛昏晕、耳聋、脱发、面色青紫。血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀之胸痛、内热瞀闷；少腹逐瘀汤温经活血，主治下焦寒凝血瘀之少腹疼痛、月经不调；身痛逐瘀汤活血通络、祛风除湿，主治瘀血痹阻经络之周身疼痛；复元活血汤活血祛瘀、疏肝通络，主治跌打损伤、瘀留胁下"},{"q":"患者有风湿性关节炎病史，近期腰膝疼痛，双下肢晨起麻木不仁，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"痹证日久，肝肾两虚、气血不足，风寒湿邪未尽，阻于腰膝经络则腰膝疼痛、双下肢麻木不仁，阳虚不温则畏寒喜暖，舌淡苔白、脉细弱为正虚邪恋之象。独活寄生汤以独活祛下焦风湿为君，桑寄生、杜仲、牛膝补肝肾、强筋骨，人参、茯苓、甘草益气健脾，当归、川芎、芍药、地黄养血活血，祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚、气血不足。羌活胜湿汤祛风胜湿，主治风湿在表之肩背痛；肾著汤温肾除湿，主治寒湿著腰；大秦艽汤疏风养血清热，主治风邪中经络；九味羌活汤解表祛湿清热，主治外感寒湿，均无补益肝肾气血之功"},{"q":"患者，女，32岁，胆怯易惊，虚烦不宁，失眠多梦，呕吐呃逆，舌苔白腻微黄，脉弦滑略数。选用何方为佳","o":["清气化痰丸","温胆汤","贝母瓜蒌散","二陈汤","茯苓丸"],"a":1,"e":"胆郁痰扰，痰热内扰心神则胆怯易惊、虚烦不宁、失眠多梦，胃失和降则呕吐呃逆，苔白腻微黄、脉弦滑略数为痰郁化热之象。温胆汤以半夏、陈皮、茯苓、甘草燥湿化痰、理气和中为君，枳实破气消痰，竹茹清热化痰、和胃止呕，理气化痰、清胆和胃，主治胆郁痰扰之惊悸失眠、呕吐呃逆。二陈汤燥湿化痰、理气和中，主治湿痰之咳嗽痰白，无清胆和胃、除烦之功；清气化痰丸清热化痰，主治痰热壅肺之咳嗽痰黄；贝母瓜蒌散润肺化痰，主治燥痰之干咳痰黏；茯苓丸燥湿行气、软坚化痰，主治痰停中脘之两臂疼痛，均非胆郁痰扰之证"},{"q":"患者，女，64岁。证见脘腹胀痛，下痢泄泻，小便短赤，舌苔黄腻，脉沉有力。治宜","o":["芍药汤","枳实导滞丸","保和丸","木香槟榔丸","健脾丸"],"a":1,"e":"湿热食积内阻，气机壅滞则脘腹胀痛，湿热下注则下痢泄泻、小便短赤，苔黄腻、脉沉有力为实热积滞之象。枳实导滞丸以大黄攻积泄热为君，枳实、神曲消食导滞，黄芩、黄连清热燥湿，茯苓、泽泻利湿，白术健脾，消积导滞、清利湿热，主治湿热食积之脘腹胀痛、下痢泄泻。芍药汤清热燥湿、调气和血，主治湿热痢之腹痛、便脓血、里急后重；木香槟榔丸行气导滞、攻积泄热，主治积滞内停之痞满胀痛、大便秘结；保和丸消食和胃，主治食积之脘腹胀满、嗳腐吞酸；健脾丸健脾和胃、消食止泻，主治脾虚食积，均非湿热食积之泄泻"},{"q":"患者昨日外出后汗出当风，出现肩臂疼痛，难以转侧，舌淡苔白，脉浮。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":1,"e":"汗出当风，风湿之邪乘虚客于肌表经络，肩臂疼痛、难以转侧，舌淡苔白、脉浮为风湿在表之象。羌活胜湿汤以羌活、独活祛风胜湿为君，防风、藁本、川芎、蔓荆子等祛风止痛，祛风胜湿，主治风湿在表之肩背痛、不可回顾、头痛身重。九味羌活汤解表散寒、祛湿清热，主治外感寒湿兼里热之口苦微渴、肢体酸楚；独活寄生汤祛风湿、补肝肾、益气血，主治痹证日久、肝肾两虚之腰膝疼痛；大秦艽汤疏风清热、养血活血，主治风邪中经络之口眼㟀斜；肾著汤温肾除湿，主治寒湿著腰之腰重冷痛，均非风湿客表之肩臂痛"},{"q":"患者，男，55岁。腹痛便秘，脐下绞痛，绕脐不止，手足不温，苔白不渴，脉沉弦而迟。医生选用温脾汤治疗，该方组成药物是","o":["附子、细辛、干姜、大黄、人参","附子、大黄、芒硝、人参、当归","干姜、大黄、枳实、厚朴、人参","干姜、大黄、芒硝、附子、芍药","附子、干姜、细辛、人参、芒硝"],"a":1,"e":"温脾汤以附子、干姜温阳散寒，大黄、芒硝泻下软坚，人参、当归、甘草益气养血，温补脾阳、攻下冷积，主治脾阳不足、冷积内停之腹痛便秘、手足不温，所列附子、大黄、芒硝、人参、当归即其核心药物。含细辛之方为大黄附子汤之意，温经散寒力强而无补益；含枳实、厚朴者偏于行气导滞，主治胸痹或腑实气滞；含芍药者侧重缓急止痛；含细辛、芒硝而无当归、甘草者组合杂乱，均非温脾汤温阳攻下兼补益之配伍"},{"q":"患者见手足不温，胁肋胀痛，脘腹疼痛，泄利下重，脉弦。首选方剂是","o":["四逆散","小柴胡汤","茵陈蒿汤","龙胆泻肝汤","蒿芩清胆汤"],"a":0,"e":"肝郁气滞，阳气内郁不能达于四末则手足不温，气滞胁肋则胀痛，木郁乘土则脘腹疼痛、泄利下重，脉弦为肝郁之象。四逆散以柴胡疏肝解郁、透解郁热为君，枳实理气解郁，白芍养血柔肝，甘草缓急和中，透解郁热、疏肝理气，主治肝郁气滞之四肢不温、胁肋胀痛、泄利下重。小柴胡汤和解少阳，主治往来寒热、胸胁苦满；龙胆泻肝汤清肝胆实火、利肝经湿热，主治口苦、阴肿阴痒；蒿芩清胆汤清胆利湿、和胃化痰，主治少阳湿热之寒热如疟、吐酸苦水；茵陈蒿汤清热利湿退黄，主治阳黄，均非肝郁气滞之四逆"},{"q":"患者，女，44岁。头痛以巅顶为主，痛甚时烦躁欲死，伴有恶心呕吐，畏寒喜热，手足不温，口不渴，舌淡苔白，脉沉弦迟。宜选择下列哪方治疗","o":["吴茱萸汤","小建中汤","当归四逆汤","四逆汤","大建中汤"],"a":0,"e":"厥阴肝经循巅顶，肝胃虚寒、浊阴上逆，故头痛以巅顶为主、痛甚欲死，胃气上逆则恶心呕吐，阳虚不温则畏寒喜热、手足不温，口不渴、舌淡苔白、脉沉弦迟为虚寒之象。吴茱萸汤以吴茱萸温肝暖胃、降逆止呕为君，人参补虚，生姜温胃止呕，大枣补脾和中，温中补虚、降逆止呕，主治肝胃虚寒、浊阴上逆之巅顶头痛、呕吐涎沫。小建中汤温中补虚、和里缓急，主治腹中拘急疼痛；当归四逆汤温经散寒、养血通脉，主治血虚寒厥之手足厥寒、脉细欲绝；四逆汤回阳救逆，主治心肾阳虚之四肢厥逆、脉微；大建中汤温中补虚、降逆止痛，主治心胸大痛、呕吐，均非巅顶头痛"},{"q":"患者症见身热汗多，口渴心烦，小便短赤，体倦少气，精神不振，脉虚数。治疗应首选","o":["清暑益气汤","竹叶石膏汤","香薷散","桂苓甘露散","六一散"],"a":0,"e":"暑热伤气耗阴，邪在气分则身热汗多、口渴心烦，暑湿下注则小便短赤，气虚则体倦少气、精神不振，脉虚数为暑热伤气阴之象。清暑益气汤以西洋参、石斛、麦冬益气养阴为君，西瓜翠衣、荷梗清热解暑，黄连、知母清热，竹叶、甘草、粳米清热和胃，清暑益气、养阴生津，主治暑热气阴两伤。竹叶石膏汤清热生津、益气和胃，主治热病后期余热未清；香薷散祛暑解表、化湿和中，主治阴暑之恶寒发热、吐泻；桂苓甘露散清暑解热、化气利湿，主治暑湿之发热口渴、小便不利；六一散清暑利湿，主治暑湿轻证之身热烦渴，均非暑热伤气阴"},{"q":"患者胸膈痞闷，脘腹胀痛，嗳腐吞酸，恶心呕吐，饮食不消，治宜选用","o":["半夏泻心汤","柴胡疏肝散","越鞠丸","枳实消痞丸","半夏厚朴汤"],"a":2,"e":"六郁内阻，气郁则胸膈痞闷、脘腹胀痛，食郁则嗳腐吞酸、饮食不消，胃气上逆则恶心呕吐，越鞠丸以香附行气解郁为君，川芎活血、栀子清热、苍术燥湿、神曲消食，行气解郁，主治气血痰火湿食六郁之胸膈痞闷、脘腹胀痛。半夏泻心汤寒热平调、消痞散结，主治寒热错杂之心下痞、呕吐、肠鸣；柴胡疏肝散疏肝理气、活血止痛，主治肝郁之胁肋胀痛；枳实消痞丸消痞除满、健脾和胃，主治脾虚气滞、寒热互结之心下痞满；半夏厚朴汤行气散结、降逆化痰，主治梅核气，均非六郁通用之剂"},{"q":"患者牙宣出血，牙龈红肿溃烂，口气热臭，口干舌燥，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["清胃散","左金丸","凉膈散","清瘟败毒饮","普济消毒饮"],"a":0,"e":"胃有积热，循经上攻，胃火灼伤龈络则牙宣出血、牙龈红肿溃烂，口气热臭，热盛伤津则口干舌燥，舌红苔黄、脉滑数为胃经实热之象。清胃散以黄连清胃泻火为君，生地凉血养阴，丹皮凉血清热，当归养血活血，升麻散火解毒、引经上行，清胃凉血，主治胃火牙痛、牙宣出血、口气热臭。左金丸清肝泻火、降逆止呕，主治肝火犯胃之呕吐吞酸；凉膈散泻火通便、清上泄下，主治上中二焦火热之胸膈烦热；清瘟败毒饮气血两清，主治瘟疫热毒气血两燔；普济消毒饮疏风清热解毒，主治大头瘟头面红肿，均非胃火牙宣"},{"q":"患者骨蒸潮热，盗汗遗精，咳嗽咳血，心烦易怒，足膝疼热，舌红少苔，尺脉数而有力，治疗宜用的方剂是","o":["左归丸","肾气丸","大补阴丸","小柴胡汤","一贯煎"],"a":2,"e":"肝肾阴虚，虚火上炎，阴虚火旺则骨蒸潮热、盗汗，虚火扰动精室则遗精，灼肺则咳嗽咳血，虚火上扰则心烦易怒，肝肾阴虚、虚火下注则足膝疼热，舌红少苔、尺脉数而有力为阴虚火旺之象。大补阴丸以熟地、龟板滋阴潜阳为君，知母、黄柏泻火坚阴，猪脊髓、蜂蜜填补精髓，滋阴降火，主治阴虚火旺之骨蒸潮热、盗汗遗精、咳嗽咳血。左归丸滋阴补肾，主治真阴不足之腰膝酸软、遗精，无泻火之力；肾气丸温补肾阳，主治肾阳不足；一贯煎滋阴疏肝，主治肝肾阴虚、肝气不舒之胁痛；小柴胡汤和解少阳，主治往来寒热，均非滋阴降火"},{"q":"九味羌活汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":3,"e":"九味羌活汤解表散寒、祛湿清热，以羌活祛风除湿为君，防风、苍术助之，细辛、白芷、川芎等祛风止痛，黄芩、生地清泄里热，甘草调和，主治外感风寒湿邪、内有蕴热之证，以恶寒发热、头痛无汗、肢体酸楚疼痛、口苦微渴为辨证要点。恶寒发热、头身疼痛、不汗出而烦躁、脉浮紧为大青龙汤之表寒里热；恶风、发热、汗出、脉浮缓为桂枝汤之表虚；恶寒发热、无汗而喘、脉浮紧为麻黄汤之风寒表实；恶寒发热、无汗、喘咳、痰多清稀、苔白滑为小青龙汤之外寒内饮，均非九味羌活汤兼祛湿清热之要点"},{"q":"患者腹痛便秘，胁下偏痛，发热，畏寒肢冷，舌苔白腻，脉弦紧。宜选用的方剂是","o":["温脾汤","大陷胸汤","归脾汤","大黄牡丹汤","大黄附子汤"],"a":4,"e":"寒积内停，腑气不通则腹痛便秘，寒邪偏着胁下则胁下偏痛，阳气被遏则发热、畏寒肢冷，苔白腻、脉弦紧为寒积里实之象。大黄附子汤以附子温里散寒为君，大黄泻下通便，细辛散寒止痛，温里散寒、通便止痛，主治寒积里实之腹痛便秘、胁下偏痛、发热、脉弦紧。温脾汤温补脾阳、攻下冷积，主治脾阳不足之便秘腹痛、手足不温，兼有气血虚；大陷胸汤泻热逐水，主治水热互结之心下硬满疼痛；大黄牡丹汤泻热破瘀，主治肠痈初起之少腹肿痞；归脾汤益气补血、健脾养心，主治心脾两虚，均无散寒通便之功"},{"q":"患者下利清水，色纯青，其气臭秽，脐腹疼痛，按之坚硬有块，口舌干燥，脉滑实。最宜选用的方剂是","o":["温脾汤","十枣汤","济川煎","麻子仁丸","大承气汤"],"a":4,"e":"热结旁流，燥屎内结于肠，逼迫津液从旁而下，故下利清水、色纯青、气臭秽，燥屎不去则脐腹疼痛、按之坚硬有块，热盛伤津则口舌干燥，脉滑实为里实热结之象。大承气汤以大黄泻下攻积为君，芒硝软坚润燥，枳实、厚朴行气导滞，峻下热结，主治阳明腑实之痞满燥实及热结旁流。温脾汤温阳攻下，主治寒积便秘之手足不温、脉沉迟；济川煎温肾润肠，主治肾虚便秘；麻子仁丸润肠泄热，主治脾约之大便干结、小便频数；十枣汤峻下逐水，主治悬饮、水肿，均非热结旁流之峻下"},{"q":"患者大便不通，频转矢气，脘腹痞满，腹痛拒按，按之硬，潮热谵语，手足濈然汗出，舌苔黄燥起刺，脉沉实。最宜选用的方剂是","o":["济川煎","大承气汤","大柴胡汤","桃核承气汤","增液承气汤"],"a":1,"e":"燥屎内结，腑气不通则大便不通、频转矢气，实热壅滞则脘腹痞满、腹痛拒按、按之硬，热盛则潮热，热扰心神则谵语，四肢阳明主之，热逼津泄则手足濈然汗出，舌苔黄燥起刺、脉沉实为阳明腑实之痞满燥实。大承气汤峻下热结，大黄、芒硝、枳实、厚朴合用，痞满燥实悉除，主治阳明腑实重证。大柴胡汤和解少阳、通下里实，主治往来寒热、胸胁苦满；桃核承气汤破血下瘀，主治下焦蓄血之少腹急结、其人如狂；增液承气汤滋阴增液、泄热通便，主治热结阴亏之便秘；济川煎温肾润肠，主治肾虚便秘"},{"q":"以恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴为辨证要点的方剂是","o":["大青龙汤","麻黄杏仁甘草石膏汤","九味羌活汤","白虎汤","败毒散"],"a":2,"e":"九味羌活汤解表散寒、祛湿清热，以羌活、防风、苍术等祛风散寒除湿，细辛、白芷、川芎祛风止痛，黄芩、生地清泄里热，甘草调和，主治外感风寒湿邪、内有蕴热，以恶寒发热、头痛无汗、肢体酸楚疼痛、口苦微渴为辨证要点。大青龙汤发汗清热，要点为恶寒发热、不汗出而烦躁；麻黄杏仁甘草石膏汤清肺平喘，要点为发热喘咳、苔黄脉数；白虎汤清热生津，要点为大热大汗大渴、脉洪大；败毒散益气解表，要点为憎寒壮热、无汗、脉浮无力，均非九味羌活汤外感寒湿兼里热之要点"},{"q":"患者受刀伤后，筋断骨折，瘀血肿痛。治疗应首选的方剂是","o":["七厘散","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":0,"e":"金刃刀伤，筋断骨折，血溢脉外则瘀血肿痛，七厘散以血竭、乳香、没药、红花、朱砂等活血散瘀、消肿定痛，冰片、麝香开窍散瘀，儿茶、海螵蛸止血生肌，散瘀消肿、定痛止血，主治跌打损伤、筋断骨折、瘀血肿痛。补阳还五汤补气活血通络，主治中风后遗症之气虚血瘀、半身不遂；桃核承气汤破血下瘀，主治下焦蓄血之少腹急结；血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀之胸痛；清骨散清虚热，主治骨蒸潮热，均非外伤瘀肿之散瘀定痛"},{"q":"患者因秽恶痰浊郁阻，感脘腹胀闷疼痛，恶心呕吐，泄泻，舌苔厚腻，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":4,"e":"秽恶痰浊郁阻中焦，气机不畅则脘腹胀闷疼痛，胃气上逆则恶心呕吐，脾失运化则泄泻，苔厚腻为痰浊内盛之象。紫金锭以山慈菇、五倍子、大戟、麝香、雄黄、朱砂等辟秽解毒、化痰散结、消肿止痛，辟瘟解毒、消肿止痛，主治秽恶痰浊之脘腹胀痛、呕吐泄泻，外用可治疮疡肿毒。安宫牛黄丸清热解毒、豁痰开窍，主治热闭心包之高热神昏；紫雪清热开窍、熄风止痉，主治热盛动风之惊厥；至宝丹化浊开窍、清热解毒，主治痰热内闭心包之神昏；抱龙丸祛风涤痰、镇惊开窍，主治小儿急惊，均非辟秽化浊和中止呕"},{"q":"患者心下坚，大如盘，边如旋盘，宜用","o":["枳术汤","枳术丸","枳实消痞丸","半夏泻心汤","香砂六君子汤"],"a":0,"e":"枳术汤行气消饮，主治水饮停滞胃脘，心下坚满、大如盘、边如旋盘，重在消痞逐饮，故为首选。B项枳术丸虽亦用枳实、白术，却为健脾消食之剂，主脾虚气滞、食后脘胀，力缓而无逐饮之能；D项半夏泻心汤所主为寒热互结之心下痞满不痛，兼呕吐泻利，与坚满如盘之水饮结聚迥异；E项香砂六君子汤健脾益气、理气化痰，主气虚痰湿之痞满纳差"},{"q":"患者温病后期，神倦瘈疭，舌绛苔少，脉气虚弱，有时时欲脱之势。治疗首选的方剂是","o":["清营汤","羚角钩藤汤","大定风珠","天麻钩藤饮","青蒿鳖甲汤"],"a":2,"e":"大定风珠滋阴熄风，专为温病后期真阴大亏、虚风内动而设，神倦瘈疭、舌绛苔少、脉气虚弱、时时欲脱即其凭据。B项羚角钩藤汤清肝熄风，主热盛动风之高热烦躁、抽搐有力，属实风；A项清营汤清营解毒，主热入营分之身热夜甚、舌绛；E项青蒿鳖甲汤养阴透热，主夜热早凉、热退无汗，均无欲脱之势"},{"q":"患者小便频数，遗尿，小腹怕冷，舌淡，脉沉弱，治适宜选","o":["天台乌药散","缩泉丸","暖肝煎","金锁固精丸","桑螵蛸散"],"a":1,"e":"缩泉丸温肾祛寒、缩尿止遗，主治膀胱虚寒，小便频数、遗尿、小腹怕冷、舌淡脉沉弱，重在温下元而固涩。E项桑螵蛸散调补心肾，所治尿频遗尿必兼心神恍惚、健忘，属心肾两虚；D项金锁固精丸专主肾虚精关不固之遗精滑泄；A项天台乌药散行气散寒，治寒疝少腹痛引睾丸，均非膀胱虚寒遗尿"},{"q":"患者胸脘痞满，不思饮食，舌淡苔白，脉弱，宜用","o":["枳术汤","枳术丸","枳实消痞丸","半夏泻心汤","香砂六君子汤"],"a":1,"e":"枳术丸健脾消食、行气化湿，为脾虚气滞、饮食停滞而设，胸脘痞满、不思饮食、舌淡苔白脉弱即其证，消补兼施而力缓。A项枳术汤虽同一源，却以枳实倍白术、重在消饮，主心下坚大如盘之水饮；E项香砂六君子汤健脾益气、理气化痰，主气虚痰湿之痞满兼倦乏痰多；C项枳实消痞丸寒热并用，见苔腻微黄、痞满不欲食"},{"q":"以疹发不出或出而不畅，舌红，脉数为辨证要点的方剂是","o":["桑菊饮","麻黄杏仁甘草石膏汤","柴葛解肌汤","银翘散","升麻葛根汤"],"a":4,"e":"升麻葛根汤解肌透疹，主治麻疹初起、疹发不出或出而不畅，舌红脉数为郁热之象，升提透达使疹外达。D项银翘散辛凉透表，主风热初起发热咽痛；A项桑菊饮疏风清热，主风热轻证但咳、身热不甚；B项麻杏石甘汤清肺平喘，主邪热壅肺之发热喘咳，均非透疹之剂"},{"q":"患者头微痛，恶寒无汗，咳嗽痰稀，鼻塞嗌干，苔白脉浮。治当首选的方剂是","o":["桂枝汤","三拗汤","加味香苏散","葱白七味饮","杏苏散"],"a":4,"e":"杏苏散轻宣凉燥、理肺化痰，主治外感凉燥，头微痛、恶寒无汗、咳嗽痰稀、鼻塞嗌干、苔白脉浮，为燥邪袭肺之轻证。A项桂枝汤解肌发表、调和营卫，主风寒表虚之汗出脉浮缓；B项三拗汤宣肺散寒，主风寒袭肺之咳喘而无鼻塞嗌干等燥象；D项葱白七味饮养血解表，专为血虚外感而设"},{"q":"患者，外科疮疡，心胸烦闷，大便干结等。治疗应首选的方剂是","o":["泻心汤","黄芩汤","五味消毒饮","仙方活命饮","普济消毒饮"],"a":0,"e":"泻心汤即大黄黄连黄芩，泻火解毒、燥湿泄痞，主治三焦火盛，心胸烦闷、大便干结，火热内结故以苦寒直折。D项仙方活命饮清热解毒、消肿溃坚，主阳证疮疡肿毒初起之局部红肿热痛；C项五味消毒饮专解疔毒，主疔疮痈肿；E项普济消毒饮疏风清热解毒，主大头瘟头面红肿，均不以此便秘烦闷为的"},{"q":"症见久咳不已，咳甚则气喘自汗，痰少而黏，脉虚数。治宜首选","o":["麻黄汤","生脉散","小青龙汤","九仙散","泻白散"],"a":3,"e":"九仙散敛肺止咳、益气养阴，主治久咳肺虚，咳甚气喘自汗、痰少而黏、脉虚数，久咳耗气伤阴故需敛补兼施。B项生脉散益气生津、敛阴止汗，主气阴两虚之汗多体倦，无久咳气喘；C项小青龙汤解表化饮，主外寒内饮之咳痰清稀；E项泻白散泻肺清热，主肺热咳喘、皮肤蒸热，均非久咳虚喘"},{"q":"患者高热烦躁，神昏谵语，痉厥，口渴唇焦，舌红绛，脉数实，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":1,"e":"紫雪清热开窍、息风止痉，主治热闭心包兼热盛动风，高热烦躁、神昏谵语、痉厥、口渴唇焦、舌红绛脉数实最宜。A项安宫牛黄丸偏清热解毒，主高热神昏而痉厥不显；C项至宝丹偏芳香开窍，主神昏谵语而热象较缓；D项抱龙丸主小儿风痰惊厥，均为凉开之剂而各有侧重"},{"q":"以“恶寒发热，头身重痛，无汗，脉浮、重按无力”为辨证要点的方是","o":["九味羌活汤","败毒散","再造散","参苏饮","葱白七味饮"],"a":1,"e":"败毒散益气解表、散风祛湿，主治气虚外感风寒湿，恶寒发热、头身重痛、无汗、脉浮重按无力，人参扶正祛邪。A项九味羌活汤祛湿解表兼清里热，主湿邪困表之肢体酸楚、口苦微渴；C项再造散助阳益气解表，主阳虚外感之肢冷脉沉；D项参苏饮理气化痰，主气虚兼痰湿咳嗽"},{"q":"患者微恶风发热，咳嗽咽痒，咯痰不爽，舌苔薄白，脉浮缓。治疗应首选的方剂是","o":["败毒散","止嗽散","葱豉桔梗汤","香苏散","九味羌活汤"],"a":1,"e":"止嗽散疏风润肺、止咳化痰，主治风邪犯肺、咳嗽迁延，微恶风发热、咽痒、咯痰不爽、苔薄白脉浮缓，温润不燥。A项败毒散解表散风祛湿，主气虚外感头身重痛；C项葱豉桔梗汤疏风清热，主风温初起咽痛口渴；E项九味羌活汤燥湿力强、兼口苦微渴，均非专为咳嗽而设"},{"q":"患者胸闷腹胀，身热口渴，肢酸倦怠，咽痛颐肿，身目发黄，小便短赤，舌苔干黄，脉滑数。主治病证是","o":["暑温时疫之湿重于热证","暑温时疫之湿热并重证","湿温时疫之湿热并重证","湿温时疫之湿重于热证","湿温时疫之热重于湿证"],"a":2,"e":"甘露消毒丹利湿化浊、清热解毒，主治湿温时疫、湿热并重，胸闷腹胀、身热口渴、肢酸倦怠、咽痛颐肿、身目发黄、小便短赤、苔干黄脉滑数。A、B两项属暑温，发病多在盛夏且热象更著；D项湿重于热者身热不扬、苔白腻；E项热重于湿者口渴便秘、苔黄燥，与本例湿热交织不符"},{"q":"小柴胡汤证误用攻下，损伤中阳，少阳邪热乘虚内陷致寒热互结，症见心下痞满不痛，呕吐泻利，苔腻微黄，治疗应选的方剂是","o":["半夏泻心汤","小柴胡汤","大柴胡汤","生姜泻心汤","黄连汤"],"a":0,"e":"半夏泻心汤寒热平调、消痞散结，主治小柴胡汤证误下后寒热互结之心下痞满不痛、呕吐泻利、苔腻微黄，干姜黄连并投。D项生姜泻心汤主水热互结，见干噫食臭、腹中雷鸣下利；E项黄连汤主胸中有热、胃中有邪气之腹痛欲呕；B项小柴胡汤和解少阳，主寒热往来、胸胁苦满，均无痞利并见"},{"q":"患者腰膝疼痛，肢节屈伸不利，畏寒喜暖，心悸气短，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"独活寄生汤祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚气血不足，腰膝疼痛、屈伸不利、畏寒喜暖、心悸气短、脉细弱。B项羌活胜湿汤祛风胜湿，主风湿在表之肩背腰脊痛、脉浮；C项肾著汤温中散寒除湿，主寒湿腰痛如坐水中、腰中冷，均无虚象"},{"q":"患者大热烦躁，口燥咽干，错语不眠，小便黄赤，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["泻心汤","大承气汤","清瘟败毒饮","普济消毒饮","黄连解毒汤"],"a":4,"e":"黄连解毒汤泻火解毒，主治三焦火毒炽盛，大热烦躁、口燥咽干、错语不眠、小便黄赤、舌红苔黄、脉数有力，三黄直折火势。A项泻心汤主心胃火盛之吐血衄血、心下痞满；D项普济消毒饮疏风清热解毒，主大头瘟头面红肿；B项大承气汤峻下热结，主阳明腑实便秘潮热，非单纯火毒"},{"q":"患者脾热弄舌，舌红，脉数。治疗应首选的方剂是","o":["泻黄散","玉女煎","清胃散","左金丸","黄土汤"],"a":0,"e":"泻黄散泻脾胃伏火，主治脾热弄舌、舌红脉数，以石膏栀子清泻伏火、防风升散郁热，专为小儿脾热弄舌而设。C项清胃散清胃凉血，主胃火牙痛、牙龈肿痛；B项玉女煎清胃滋阴，主胃热阴虚之牙痛烦热、舌红苔干；D项左金丸清肝泻火、降逆止呕，主肝火犯胃之胁痛吞酸"},{"q":"患者，女，46岁。证见脘腹胀痛，大便秘结，小便短赤，舌苔黄腻，脉沉有力。治宜","o":["木香槟榔丸","葛花解醒汤","保和丸","枳实导滞丸","健脾丸"],"a":3,"e":"枳实导滞丸消积导滞、清利湿热，主治湿热食积，脘腹胀痛、大便秘结、小便短赤、苔黄腻、脉沉有力，湿热下注故见溲赤苔腻。A项木香槟榔丸行气攻积力峻，主积滞内停之痞满胀痛、便秘或痢疾里急后重；C项保和丸消食和胃，主单纯食积嗳腐吞酸；E项健脾丸健脾消食，主脾虚食积便溏乏力"},{"q":"患者恶寒渐轻，身热增盛，无汗头痛，目疼鼻干，心烦不眠，咽干耳聋，眼眶痛，舌苔薄黄，脉浮微洪。治疗宜首选的方剂是","o":["升麻葛根汤","桑菊饮","柴葛解肌汤","麻黄杏仁甘草石膏汤","银翘散"],"a":2,"e":"柴葛解肌汤解肌清热，主治外感风寒、郁而化热、三阳合病，恶寒渐轻身热增盛、无汗头痛、目疼鼻干、心烦不眠、眼眶痛、脉浮微洪。A项升麻葛根汤解肌透疹，主麻疹初起；D项麻杏石甘汤清肺平喘，主邪热壅肺喘咳；E项银翘散辛凉透表，主风热初起咽痛口渴，均无阳明经热之眼眶痛鼻干"},{"q":"某女性患者，妊娠过程中出现下血，其血色紫黯，腹痛拒按，胎动不安。治疗应首选的方剂是","o":["桂枝茯苓丸","四逆散","生化汤","温经汤","逍遥丸"],"a":0,"e":"桂枝茯苓丸活血化瘀、缓消癥块，主治瘀阻胞宫，妊娠下血色紫黯、腹痛拒按、胎动不安，祛瘀而不伤胎。D项温经汤温经散寒、养血祛瘀，主冲任虚寒瘀血之漏下不止、小腹冷痛、暮热；C项生化汤养血祛瘀，专主产后恶露不行、小腹冷痛；E项逍遥丸疏肝健脾，主肝郁月经不调，无癥块瘀血之据"},{"q":"患者四肢浮肿，恶寒身热，无汗，烦躁，脉浮紧。治疗应首选的方剂是","o":["大青龙汤","桂枝汤","麻黄汤","小青龙汤","败毒散"],"a":0,"e":"大青龙汤发汗解表、清热除烦，主治外寒里热之溢饮，四肢浮肿、恶寒身热、无汗烦躁、脉浮紧，麻黄倍量配石膏发越阳气。D项小青龙汤解表化饮，主外寒内饮之咳喘痰多清稀；C项麻黄汤发汗平喘，主风寒束表之无汗而喘，无水肿烦躁；E项败毒散益气祛湿，主气虚外感，均无里热烦躁"},{"q":"患者筋脉拘急，手足瘈疭，或头晕目眩，舌绛苔少，脉细数。治疗首选的方剂是","o":["天麻钩藤饮","羚角钩藤汤","阿胶鸡子黄汤","大定风珠","青蒿鳖甲汤"],"a":2,"e":"阿胶鸡子黄汤滋阴养血、柔肝熄风，主治热邪伤阴、虚风内动，筋脉拘急、手足瘈疭、头晕目眩、舌绛苔少、脉细数。D项大定风珠滋阴熄风力峻，主温病后期神倦瘈疭、脉气虚弱、时时欲脱；B项羚角钩藤汤凉肝熄风，主热盛动风之高热抽搐；E项青蒿鳖甲汤退虚热，主夜热早凉、热退无汗"},{"q":"患者，女，58岁。左侧肢体一过性麻木无力伴头晕1周。发作时左侧肢体麻木无力，持物不能，站立不稳，言语略含糊，伴头晕，持续约30分钟症状好转，纳差，二便正常，舌黯苔白腻，脉弦滑。治疗应首选的方剂是","o":["小活络丹","定痫丸","半夏白术天麻汤加减","天麻钩藤饮加减","镇肝熄风汤加减"],"a":2,"e":"半夏白术天麻汤化痰熄风、健脾祛湿，主治风痰上扰，一过性肢体麻木无力、头晕、舌黯苔白腻、脉弦滑，痰湿中阻故苔腻脉滑。D项天麻钩藤饮平肝熄风、清热活血，主肝阳上亢之眩晕头痛、脉弦数；E项镇肝熄风汤镇肝熄风、滋阴潜阳，主气血逆乱之中风，苔腻不显；B项定痫丸涤痰开窍，主痫证发作"},{"q":"患者，女，25岁，正值盛暑前来就诊，见身热烦渴，泄泻。治宜首选","o":["清暑益气汤","白虎汤","生脉散","泻白散","六一散"],"a":4,"e":"六一散清暑利湿，主治暑湿证，盛暑身热烦渴、泄泻、小便不利，滑石清暑利水、甘草清热和中，使湿从小便去。A项清暑益气汤清暑益气、养阴生津，主暑热气津两伤之汗多体倦、脉虚数；B项白虎汤清热生津，主气分热盛之大热大汗大渴；C项生脉散益气敛阴，无清暑利湿之功"},{"q":"患者呕吐，呃逆，口渴咽干，舌红少苔，脉虚数。治疗应首选的方剂是","o":["麦门冬汤","沙参麦冬汤","益胃汤","百合固金汤","补肺阿胶汤"],"a":0,"e":"麦门冬汤清养肺胃、降逆下气，主治胃阴不足、气机上逆，呕吐呃逆、口渴咽干、舌红少苔、脉虚数，重用麦冬配半夏降逆。B项沙参麦冬汤养阴清肺、益胃生津，主肺胃阴伤之干咳少痰；C项益胃汤养阴益胃，主胃阴损伤之口干咽燥、大便干结；D项百合固金汤滋养肺肾，主咳嗽痰中带血"},{"q":"下列哪项不属于方剂组成变化中的药味增减","o":["由麻黄汤到三拗汤","麻黄汤加白术，即麻黄加术汤","由大承气汤到小承气汤","桂枝汤加芍药，即桂枝加芍汤","抵当汤与抵当丸"],"a":4,"e":"药味增减指在原方基础上增入或减去药物而剂型不变，A项麻黄汤去桂枝为三拗汤、B项加白术为麻黄加术汤、C项大承气汤去芒硝减枳朴为小承气汤、D项桂枝汤加芍药为桂枝加芍汤，均属此列。E项抵当汤与抵当丸药物组成完全相同，仅剂型有汤丸之别、服法有缓急之异，属剂型更换变化，不属药味增减"},{"q":"患者腰脊疼痛，不能转侧，舌淡苔白，脉浮。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":1,"e":"羌活胜湿汤祛风胜湿，主治风湿在表，腰脊疼痛、不能转侧、舌淡苔白、脉浮，以羌活独活祛上半身风湿。A项独活寄生汤益肝肾补气血，主痹证日久腰膝冷痛、屈伸不利、脉细弱；C项肾著汤温中散寒除湿，主寒湿腰痛如坐水中、小便自利；E项九味羌活汤兼清里热，见口苦微渴"},{"q":"患者下利日数十行，谷不化，腹中雷鸣，心下痞硬而满，干呕，心烦不得安，治疗应选用","o":["小柴胡汤","甘草泻心汤","大陷胸汤","大柴胡汤","半夏泻心汤"],"a":1,"e":"甘草泻心汤和胃消痞、清热解毒，主治胃气虚弱、寒热互结，下利日数十行、谷不化、腹中雷鸣、心下痞硬而满、干呕心烦不得安，重用甘草缓中。E项半夏泻心汤主寒热互结痞满呕利，无下利完谷与雷鸣之甚；生姜泻心汤主水热互结、干噫食臭；C项大陷胸汤主水热结胸，硬满痛不可近"},{"q":"患者偏正头痛或巅顶头痛，恶寒发热，目眩鼻塞，舌苔薄白，脉浮。治疗首选的方剂是","o":["麻黄汤","川芎茶调散","天麻钩藤饮","半夏白术天麻汤","杏苏散"],"a":1,"e":"川芎茶调散疏风止痛，主治外感风邪头痛，偏正头痛或巅顶头痛、恶寒发热、目眩鼻塞、舌苔薄白、脉浮，茶调轻清上行头目。C项天麻钩藤饮平肝熄风，主肝阳上亢头痛眩晕、脉弦数；D项半夏白术天麻汤化痰熄风，主风痰头痛眩晕、苔白腻；E项杏苏散轻宣凉燥，主凉燥咳嗽"},{"q":"柴葛解肌汤的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热，喘咳，苔黄，脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":2,"e":"柴葛解肌汤解肌清热，主治风寒郁而化热、三阳合病，发热重恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪为辨证要点，阳明经热故见眼眶鼻干。B项所述为麻黄杏仁甘草石膏汤之发热喘咳、苔黄脉数，重在邪热壅肺；D项为银翘散之发热微恶寒、咽痛口渴、脉浮数；E项为升麻葛根汤之疹发不出，各有所指"},{"q":"麻黄杏仁甘草石膏汤的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热，喘咳，苔黄，脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":1,"e":"麻黄杏仁甘草石膏汤清肺平喘，主治邪热壅肺，发热、喘咳、苔黄、脉数为辨证要点，麻黄宣肺、石膏清热，喘咳与里热并见。C项所述为柴葛解肌汤之发热重恶寒轻、头痛眼眶痛鼻干、脉浮微洪；D项为银翘散之发热微恶寒、咽痛口渴、脉浮数；E项为升麻葛根汤之疹发不出或出而不畅，均无喘咳"},{"q":"患者，男，65岁。腹痛便秘，胁下偏痛，畏寒肢冷，手足不温，苔白腻，脉弦紧。医生选用具有温里散寒、通便止痛功用的方剂治疗，该方是","o":["温脾汤","大黄附子汤","三物备急丸","济川煎","麻子仁丸"],"a":1,"e":"大黄附子汤温里散寒、通便止痛，主治寒积里实，腹痛便秘、胁下偏痛、畏寒肢冷、苔白腻、脉弦紧，附子温阳、大黄泻积，温下并用。A项温脾汤温阳健脾、泻下通便，主阳虚寒积之腹痛便秘、手足不温、脉沉迟；C项三物备急丸主寒积急暴之心腹胀痛；D项济川煎温肾润肠，主肾虚便秘、小便清长"},{"q":"患者鸡鸣泄泻，伴有不思饮食，食不消化，腹痛喜温，腰酸肢冷，神疲乏力，舌淡，苔薄白，脉沉迟无力。治疗首选的方剂是","o":["理中丸","四神丸","参苓白术散","真人养脏汤","桃花汤"],"a":1,"e":"四神丸温肾暖脾、涩肠止泻，主治脾肾阳虚五更泄泻，鸡鸣即泻、食不消化、腹痛喜温、腰酸肢冷、脉沉迟无力，补骨脂温肾、肉豆蔻涩肠。D项真人养脏汤涩肠固脱、温补脾肾，主久泻久痢滑脱不禁；A项理中丸温中祛寒，主脾胃虚寒之腹痛泄泻但无五更定时；E项桃花汤温中涩肠，主虚寒痢便脓血"},{"q":"患者汗出恶风，身重微肿，肢节疼痛，小便不利，舌淡苔白，脉浮。治疗应首选的治法是","o":["益气健脾，祛湿利水","利水消肿，益气通阳","利水消肿，理气健脾","益气祛风，健脾利水","益气健脾，祛寒除湿"],"a":3,"e":"该证为风水表虚，防己黄芪汤益气祛风、健脾利水，汗出恶风、身重微肿、肢节疼痛、小便不利、脉浮即其主证，黄芪益气固表、防己祛风利水。A项益气健脾祛湿利水重在健脾运湿；C项利水消肿、理气健脾偏于行气导水；B项利水消肿、益气通阳近于五苓散之法，均未体现祛风固表，与表虚风水不合"},{"q":"银翘散的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热、喘咳、苔黄、脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":3,"e":"银翘散辛凉透表、清热解毒，主治温病初起，发热、微恶寒、咽痛、口渴、脉浮数为辨证要点，咽痛口渴提示风热犯肺。A项所述为桑菊饮之咳嗽、发热不甚、微渴、脉浮数，热象较轻；B项为麻黄杏仁甘草石膏汤之发热喘咳、苔黄脉数；C项为柴葛解肌汤之发热重恶寒轻、眼眶痛鼻干，均无咽痛之突出"},{"q":"患者，大热渴饮，四肢抽搐，或厥逆，舌绛唇焦，脉沉细而数。治疗应首选的方剂是","o":["紫雪","至宝丹","白虎加人参汤","白虎加桂枝汤","清瘟败毒饮"],"a":4,"e":"清瘟败毒饮清热解毒、凉血泻火，主治瘟疫热毒、气血两燔，大热渴饮、四肢抽搐或厥逆、舌绛唇焦、脉沉细而数，气分血分热毒并盛。A项紫雪清热开窍息风，主热盛神昏痉厥；C项白虎加人参汤清热益气生津，主气分大热汗出脉芤；D项白虎加桂枝汤主温疟，均不解血分热毒"},{"q":"患者居住海边，双膝关节疼痛反复发作，屈伸不利，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"独活寄生汤祛风湿、止痹痛、补肝肾、益气血，主治痹证日久、肝肾亏虚，双膝关节疼痛反复、屈伸不利、畏寒喜暖、舌淡苔白、脉细弱。B项羌活胜湿汤祛风胜湿，主风湿在表之腰背痛、脉浮；C项肾著汤主寒湿腰痛如坐水中；D项大秦艽汤养血祛风，主风邪初中经络之口眼歪斜，均非久痹虚证"},{"q":"患者恶寒发热，头身疼痛，无汗而喘，舌苔薄白，脉浮紧。治疗应首选的方剂是","o":["麻黄汤","败毒散","桂枝汤","小青龙汤","大青龙汤"],"a":0,"e":"麻黄汤发汗解表、宣肺平喘，主治风寒束表、肺气郁闭，恶寒发热、头身疼痛、无汗而喘、苔薄白、脉浮紧，麻桂相须开腠发汗。C项桂枝汤解肌发表，主表虚有汗脉浮缓；D项小青龙汤解表化饮，主外寒内饮之痰多清稀；E项大青龙汤发汗清热，主不汗出而烦躁，均非单纯风寒无汗而喘"},{"q":"患者神思恍惚，心悸易惊，失眠健忘，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","甘麦大枣汤","养心汤"],"a":4,"e":"养心汤养心安神、益气补血，主治心气心血不足，神思恍惚、心悸易惊、失眠健忘、舌淡苔白、脉细弱，补养心脾以安神志。C项酸枣仁汤养血安神、清热除烦，主肝血不足之虚烦失眠、头目眩晕、咽干口燥脉弦细；B项天王补心丹滋阴养血，主阴虚血少舌红少苔；D项甘麦大枣汤甘润缓急，主脏躁悲伤欲哭"},{"q":"患者头痛身热，微恶风寒，咳嗽，咽痛，口渴，舌尖红，苔薄白，脉浮数。治疗宜首选的方剂是","o":["麻黄杏仁甘草石膏汤","柴葛解肌汤","银翘散","升麻葛根汤","葱豉桔梗汤"],"a":2,"e":"银翘散辛凉透表、清热解毒，主治风热犯表，头痛身热、微恶风寒、咳嗽咽痛、口渴、舌尖红、脉浮数，发热咽痛较著为其特点。A项麻杏石甘汤清肺平喘，主邪热壅肺之发热喘咳；B项柴葛解肌汤解肌清热，主三阳合病之眼眶痛鼻干；E项葱豉桔梗汤偏疏风宣肺解表，清热力较逊，适风温初起表证较轻"},{"q":"患者因稳定型心绞痛就诊，自诉常觉胸骨后痛，偶有心慌心悸，舌质黯红，脉涩。治疗应首选的方剂是","o":["生化汤","温经汤","桃核承气汤","血府逐瘀汤","小承气汤"],"a":3,"e":"血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀，胸痛日久不愈、痛如针刺有定处、舌质黯红、脉涩，胸阳痹阻、瘀血内停故胸骨后痛兼心悸。C项桃核承气汤破血下瘀，主下焦蓄血之少腹急结、其人如狂；A项生化汤养血祛瘀，主产后瘀阻腹痛；B项温经汤温经散寒，主冲任虚寒漏下，病位均不在胸"},{"q":"症见咯痰不爽，涩而难出，咽喉干燥，苔白而干等，治宜选用","o":["二陈汤","贝母瓜萎散","平胃散","大定风珠","镇肝熄风汤"],"a":1,"e":"贝母瓜蒌散润肺清热、理气化痰，主治燥痰咳嗽，咯痰不爽、涩而难出、咽喉干燥、苔白而干，燥胜则痰黏难咯，故以润燥化痰。A项二陈汤燥湿化痰、理气和中，主湿痰咳嗽痰多易咯、苔白腻；C项平胃散燥湿运脾，主湿滞脾胃之脘腹胀满；D项大定风珠滋阴熄风，主虚风内动，均非燥痰之治"},{"q":"患者上中二焦火热证而见有咽痛吐衄，便秘溲赤，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["凉膈散","玉女煎","泻心汤","白虎汤","清胃散"],"a":0,"e":"凉膈散泻火通便、清上泄下，主治上中二焦火热，咽痛吐衄、便秘溲赤、舌红苔黄、脉滑数，上清胸膈之热、下泄肠腑之结。C项泻心汤泻火解毒燥湿，主心胃火盛之吐衄、心下痞满；D项白虎汤清气分热，主大热大汗大渴；E项清胃散清胃凉血，主胃火牙痛，均无清上泄下之能"},{"q":"患者，男，62岁。咳嗽气急，昼轻夜重，咯痰量大，痰色黄质黏，易咯出，咽干，食少难消，舌红苔厚，脉弦滑。治疗宜选的方剂是","o":["苓甘五味姜辛汤加黄芩、桑白皮","苏子降气汤加黄芩","小青龙汤加桑白皮","三子养亲汤黄芩、桑白皮","定喘汤"],"a":3,"e":"三子养亲汤降气消食、温化痰饮，加黄芩、桑白皮清泻痰热，主治痰浊壅肺兼食积，咳嗽气急、昼轻夜重、痰多黄黏易咯、食少难消、苔厚脉弦滑。E项定喘汤宣肺降气、清热化痰，主风寒外束、痰热内蕴之哮喘；B项苏子降气汤降气平喘、温肾纳气，主上实下虚；C项小青龙汤解表化饮，主外寒内饮清稀痰，均不兼食积"},{"q":"患者胸中痞硬，烦懊不安，欲吐不出，气上冲咽喉不得息，寸脉微浮。治疗应首选的方剂是","o":["瓜蒂散","半夏泻心汤","枳实薤白桂枝汤","半夏厚朴汤","乌梅丸"],"a":0,"e":"瓜蒂散涌吐痰食，主治痰涎宿食壅塞胸膈，胸中痞硬、烦懊不安、欲吐不出、气上冲咽喉不得息、寸脉微浮，因其势而吐之。B项半夏泻心汤和胃消痞，主寒热互结之心下痞满、呕利；C项枳实薤白桂枝汤通阳散结，主胸痹心中痞气、胸满胁逆；D项半夏厚朴汤行气散结、降逆化痰，主梅核气咽中如有炙脔"},{"q":"患者头痛，身热不甚，口渴，咽干鼻燥，干咳无痰，舌红，苔薄白而干，脉浮数而右脉大者，治宜","o":["杏苏散","清燥救肺汤","养阴清肺汤","桑杏汤","琼玉膏"],"a":3,"e":"桑杏汤清宣温燥、润肺止咳，主治外感温燥轻证，头痛、身热不甚、口渴、咽干鼻燥、干咳无痰、舌红苔薄白而干、脉浮数右脉大。B项清燥救肺汤清燥润肺力峻，主温燥重证身热较高、气逆而喘；C项养阴清肺汤养阴清肺解毒，主白喉咽痛；A项杏苏散轻宣凉燥，主凉燥痰稀、恶寒无汗"},{"q":"症见小便频数，尿中带血，赤涩热痛，舌红脉数，治疗宜选","o":["五苓散","槐花散","黄土汤","龙胆泻肝汤","小蓟饮子"],"a":4,"e":"小蓟饮子凉血止血、利水通淋，主治下焦热结之血淋，小便频数、尿中带血、赤涩热痛、舌红脉数，血热妄行兼淋涩。B项槐花散清肠止血、疏风行气，主肠风脏毒便血、血色鲜红；C项黄土汤温阳健脾、养血止血，主脾阳不足之远血、血色暗淡；A项五苓散化气利水，主膀胱气化不利之小便不利，无尿血"},{"q":"患者身不甚热，干咳无痰，咽干口燥，右脉数大。治疗宜","o":["桑菊饮","桑杏汤","柴葛解肌汤","杏苏散","麻杏石甘汤"],"a":1,"e":"桑杏汤清宣温燥，主治温燥伤肺轻证，身不甚热、干咳无痰、咽干口燥、右脉数大，燥邪轻浅故清宣即可。A项桑菊饮疏风清热，主风热咳嗽、身热不甚；C项柴葛解肌汤解肌清热，主三阳合病发热重、眼眶痛鼻干；D项杏苏散轻宣凉燥，主凉燥之恶寒无汗、痰稀；E项麻杏石甘汤清肺平喘，主邪热壅肺喘咳"},{"q":"以“恶寒发热，热轻寒重，无汗，肢冷倦怠，舌淡苔白，脉沉无力”为辨证要点的方剂是","o":["九味羌活汤","麻黄附子细辛汤","败毒散","再造散","参苏饮"],"a":3,"e":"再造散助阳益气、解表散寒，主治阳气虚弱外感风寒，热轻寒重、无汗肢冷、倦怠嗜卧、面色苍白、语声低微、舌淡苔白、脉沉无力。B项麻黄附子细辛汤助阳解表，主少阴伤寒始得之反发热脉沉，无益气健脾之功；C项败毒散益气解表，主气虚外感而无肢冷面白；E项参苏饮理气化痰，主气虚痰湿咳嗽"},{"q":"患者痈疽发背，溃后虚羸少气，溃疡作痛，倦怠懒言，少食乏味，自汗口干，夜寐不安，间有发热，经久不退，舌淡苔白，脉细弱。首选治疗方剂是","o":["八珍汤","普济消毒饮","內补黄芪汤","阳和汤","黄连解毒汤"],"a":2,"e":"内补黄芪汤补益气血、养阴生肌，主治痈疽溃后气血两虚，溃后虚羸少气、溃疡作痛、倦怠懒言、少食自汗、夜寐不安、经久不退、脉细弱。A项八珍汤平补气血，无托毒生肌之能；D项阳和汤温阳补血、散寒通滞，主阴疽初起漫肿无头、皮色不变；B项普济消毒饮清热解毒，主大头瘟；E项黄连解毒汤泻火解毒，均非溃后虚证"},{"q":"以身热微寒，咽干口燥，舌红，苔薄白，脉数为辨证要点的方剂是","o":["葱白七味饮","加减葳蕤汤","葱豉汤","银翘散","桑菊饮"],"a":1,"e":"加减葳蕤汤滋阴解表，主治阴虚之体外感风热，身热微寒、咽干口燥、舌红、苔薄白、脉数，葳蕤滋阴、葱豉解表，汗源充足而不伤阴。A项葱白七味饮养血解表，主血虚外感头痛身热；D项银翘散辛凉透表，主普通风热无阴虚咽干舌红；E项桑菊饮疏风清热，主风热轻证咳嗽，均无滋阴之功"},{"q":"患者皮肤疹出色红，或遍身云片斑点，瘙痒，抓破后渗出津水，苔白或黄，脉浮数。治疗首选的方剂是","o":["仙方活命饮","普济消毒饮","五味消毒饮","消风散","玉真散"],"a":3,"e":"消风散疏风养血、清热除湿，主治风湿浸淫血脉之瘾疹湿疹，皮肤疹出色红、云片斑点、瘙痒、抓破渗水、脉浮数，以疏风除湿止痒。A项仙方活命饮清热解毒、消肿溃坚，主阳证疮疡局部红肿热痛；B项普济消毒饮疏风清热解毒，主大头瘟；C项五味消毒饮清热解毒，主疔疮；E项玉真散祛风定惊，主破伤风"},{"q":"患者小腹急结，小便不利，谵语狂躁，至夜发热，脉沉实而涩。治疗应首选的方剂是","o":["失笑散","温经汤","桃核承气汤","复元活血汤","生化汤"],"a":2,"e":"桃核承气汤破血下瘀，主治下焦蓄血、瘀热互结，小腹急结、小便不利、谵语狂躁、至夜发热、脉沉实而涩，瘀热上扰心神故狂躁。A项失笑散活血止痛，主瘀血停滞之心腹剧痛、恶露不行；B项温经汤温经散寒养血，主冲任虚寒漏下、小腹冷痛；E项生化汤养血祛瘀，主产后瘀阻；D项复元活血汤主跌打瘀血胁下痛"},{"q":"患者腹痛时作，常自吐蛔，甚或手足厥冷烦闷呕吐，时发时止。治疗应首选的方剂是","o":["四逆散","理中丸","当归四逆汤","乌梅丸","肥儿丸"],"a":3,"e":"乌梅丸温脏安蛔，主治蛔厥，腹痛时作、常自吐蛔、手足厥冷、烦闷呕吐、时发时止，酸收辛伏、寒热并调，蛔得酸则静。A项四逆散透邪解郁、疏肝理脾，主阳郁厥逆之手足不温、脉弦；B项理中丸温中祛寒，主脾胃虚寒吐利；C项当归四逆汤温经养血，主血虚寒厥；E项肥儿丸杀虫消积，主小儿疳积"},{"q":"患者下利清水，色纯青，其气臭秽，脐腹疼痛，按之坚硬有块，口舌干燥，脉滑实。医生选用大承气汤治疗，体现的中医治法是","o":["塞因塞用","通因通用","缓则治其本","标本兼治","实则泻其子"],"a":1,"e":"下利清水、色纯青、臭秽，脐腹硬满疼痛、口舌干燥、脉滑实，为热结旁流，虽利而用大承气汤峻下热结，属通因通用，以通治通。A项塞因塞用指以补开塞，主虚胀虚秘；C项缓则治其本为慢性病治则；D项标本兼治主虚实夹杂；E项实则泻其子为五行治则，均非热结旁流之治"},{"q":"患者温疟而见有身无寒但热，骨节疼烦，时呕，脉如平。治疗应首选的方剂是","o":["凉膈散","白虎汤","柴葛解肌汤","白虎加苍术汤","白虎加桂枝汤"],"a":4,"e":"白虎加桂枝汤清热生津、通络止痛，主治温疟，身无寒但热、骨节疼烦、时呕、脉如平，白虎清气分热、桂枝通经止痛。B项白虎汤清热生津，主气分热盛之大热大汗大渴、脉洪大，无骨节疼烦；D项白虎加苍术汤清热祛湿，主湿温热重于湿；A项凉膈散清上泄下，主上中二焦火热；C项柴葛解肌汤解肌清热，主三阳合病"},{"q":"桂枝汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":1,"e":"桂枝汤解肌发表、调和营卫，主治外感风寒表虚证，恶风、发热、汗出、脉浮缓为辨证要点，汗出脉缓示营卫不和。A项所述为大青龙汤之恶寒发热、不汗出而烦躁、脉浮紧；C项为麻黄汤之恶寒发热、无汗而喘、脉浮紧；D项为九味羌活汤之头痛无汗、肢体酸楚、口苦微渴，均无汗出脉缓"},{"q":"患者咳唾涎沫，短气喘促，咽喉干燥，舌红少苔，脉虚数。治疗宜","o":["养阴清肺汤","清燥救肺汤","桑杏汤","琼玉膏","麦门冬汤"],"a":4,"e":"麦门冬汤清养肺胃、降逆下气，主治虚热肺痿，咳唾涎沫、短气喘促、咽喉干燥、舌红少苔、脉虚数，重在滋养肺胃之阴。A项养阴清肺汤养阴清肺解毒，主白喉咽痛、咳如犬吠；B项清燥救肺汤清燥润肺，主温燥重证身热气喘；D项琼玉膏滋阴润肺，主肺痨干咳咯血；C项桑杏汤清宣温燥，主外感温燥轻证"},{"q":"患者腹痛便脓血，赤白相兼，里急后重，肛门灼热，小便短赤，舌红苔黄，脉弦数。治疗应首选的方剂是","o":["香连丸","凉膈散","黄龙汤","芍药汤","黄芩汤"],"a":3,"e":"芍药汤清热燥湿、调气和血，主治湿热痢，腹痛便脓血、赤白相兼、里急后重、肛门灼热、小便短赤、舌红苔黄脉弦数，行血则便脓自愈、调气则后重自除。A项香连丸清热燥湿、行气止痢，主湿热痢轻证；E项黄芩汤清热止利，主热泻热痢；C项黄龙汤攻下养正，主热结旁流兼气血虚；B项凉膈散主上中二焦火热"},{"q":"患者怔忡不宁，或夜寐不安，口舌生疮。治疗应首选的方剂是","o":["黄连阿胶汤","磁朱丸","天王补心丹","交泰丸","酸枣仁汤"],"a":3,"e":"交泰丸交通心肾，以黄连清心火、肉桂引火归元，主治心肾不交，怔忡不宁、夜寐不安、口舌生疮，心火亢于上、肾水亏于下。A项黄连阿胶汤滋阴降火，主少阴热化之心中烦、不得卧、舌红苔少脉细数；C项天王补心丹滋阴养血，主阴虚血少之神志不安；B项磁朱丸重镇安神，主心肾不交兼耳鸣目眩；E项酸枣仁汤主肝血不足虚烦"},{"q":"患者烦躁口渴，面赤唇焦，胸膈烦热，口舌生疮，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["清胃散","导赤散","左金丸","凉膈散","泻心汤"],"a":3,"e":"凉膈散泻火通便、清上泄下，主治上中二焦火热，烦躁口渴、面赤唇焦、胸膈烦热、口舌生疮、舌红苔黄脉滑数，清胸膈之热并通腑泄浊。A项清胃散清胃凉血，主胃火牙痛；B项导赤散清心利水，主心火下移小肠之口舌生疮、小便赤涩；C项左金丸清肝泻火，主肝火犯胃吞酸；E项泻心汤苦寒泻火，主火盛吐衄"},{"q":"患者恶寒发热，热轻寒重，无汗肢冷，倦怠嗜卧，面色苍白，语声低微，舌淡苔白，脉沉无力。治疗应首选的方剂是","o":["九味羌活汤","再造散","麻黄附子细辛汤","败毒散","参苏饮"],"a":1,"e":"再造散助阳益气、解表散寒，主治阳虚外感风寒，热轻寒重、无汗肢冷、倦怠嗜卧、面色苍白、语声低微、脉沉无力，扶正与祛邪并行。C项麻黄附子细辛汤助阳解表，主少阴伤寒脉沉反发热，无益气固表之力；D项败毒散益气解表，主气虚外感而无明显肢冷面白；E项参苏饮化痰理气，主气虚痰湿；A项九味羌活汤兼清里热"},{"q":"患者心烦不寐，口渴欲饮，小便不利，溺时涩痛，点滴难出，舌红苔微黄，脉细数。本证的病机是","o":["湿热互结，气化不利","水热互结，气化不利","痰热互结，气化不利","痰瘀互结，气化不利","瘀热互结，气化不利"],"a":1,"e":"该证为水热互结、气化不利兼伤阴，猪苓汤利水渗湿、清热养阴，心烦不寐、口渴欲饮、小便不利、溺时涩痛、舌红苔微黄脉细数即其主证。A项湿热互结气化不利者见尿频涩痛、苔黄腻，属八正散热淋；C项痰热、D项痰瘀、E项瘀热互结均非水热伤阴之机，无口渴舌红少苔之阴虚象"},{"q":"患者见瘰疬痰核，咽干，舌红，脉弦滑略数。首选治疗方剂是","o":["托里消毒散","消瘰丸","四妙勇安汤","苇茎汤","西黄丸"],"a":1,"e":"消瘰丸清热化痰、软坚散结，主治痰火凝结之瘰疬痰核，咽干、舌红、脉弦滑略数，痰火互结于颈项故见结核。A项托里消毒散补益气血、托毒排脓，主痈疽气血不足、脓成难溃；C项四妙勇安汤清热解毒活血，主脱疽热毒炽盛；D项苇茎汤清肺化痰逐瘀，主肺痈；E项西黄丸清热解毒、消肿散结，主热毒痈疽，均非瘰疬专方"},{"q":"患者胸膈满闷，上气喘急，心下痞满，不思饮食，苔白，脉弦，治宜选用","o":["越鞠丸","柴胡疏肝散","四磨汤","枳实消痞丸","厚朴温中汤"],"a":2,"e":"四磨汤行气降逆、宽胸散结，主治七情气逆，胸膈满闷、上气喘急、心下痞满、不思饮食、苔白脉弦，四药磨服取气行则逆降。A项越鞠丸行气解郁，主六郁之胸膈痞闷、嗳酸；B项柴胡疏肝散疏肝理气，主肝气郁结之胁痛；D项枳实消痞丸健脾消痞，主脾虚寒热互结之痞满乏力；E项厚朴温中汤温中行气，主脾胃寒湿胀满"},{"q":"患者壮热面赤，烦渴引饮，汗出恶热，背微恶寒，脉浮大而芤。治疗应首选的方剂是","o":["凉膈散","白虎汤","银翘散","白虎加人参汤","白虎加桂枝汤"],"a":3,"e":"白虎加人参汤清热生津、益气，主治气分热盛而津气两伤，壮热面赤、烦渴引饮、汗出恶热、背微恶寒、脉浮大而芤，背微恶寒与脉芤为津伤气耗之据。B项白虎汤主气分热盛之大热大汗大渴、脉洪大有力，无背寒脉芤；E项白虎加桂枝汤主温疟；A项凉膈散主上中二焦火热；C项银翘散主风热表证"},{"q":"妇人漏下不止，入暮发热，手心烦热，唇干舌燥，小腹冷痛，舌黯红，脉细涩。治疗应首选的方剂是","o":["失笑散","温经汤","桃核承气汤","复元活血汤","生化汤"],"a":1,"e":"温经汤温经散寒、养血祛瘀，主治冲任虚寒、瘀血阻滞，妇人漏下不止、入暮发热、手心烦热、唇干舌燥、小腹冷痛、舌黯红脉细涩。A项失笑散活血止痛，主瘀血心腹剧痛；C项桃核承气汤破血下瘀，主下焦蓄血少腹急结、其人如狂；D项复元活血汤主跌打瘀血留于胁下；E项生化汤养血祛瘀，专主产后恶露不行"},{"q":"患者牙痛，烦热干渴，舌红苔黄而干。治疗应首选的方剂是","o":["白虎汤","玉女煎","玉液汤","麦门冬汤","百合固金汤"],"a":1,"e":"玉女煎清胃热、滋肾阴，主治胃热阴虚，牙痛、烦热干渴、舌红苔黄而干，胃火盛而肾水亏，故清胃与滋阴并行。A项白虎汤清气分大热，主大热大汗大渴、脉洪大；清胃散清胃凉血，主胃火牙痛但无阴虚苔干；D项麦门冬汤养阴降逆，主肺胃阴虚之咳唾涎沫；E项百合固金汤滋养肺肾，主咳嗽痰血咽燥"},{"q":"患者钮某，食欲不振，脘腹冷痛，口水较多，时欲呕吐，大便稀溏，口不渴，舌苔白，脉沉迟。治宜选用","o":["桂枝人参汤","温脾汤","理中丸","吴茱萸汤","大建中汤"],"a":2,"e":"理中丸温中祛寒、补气健脾，主治脾胃虚寒，食欲不振、脘腹冷痛、口水较多、呕吐、大便稀溏、口不渴、苔白、脉沉迟，中阳不足故自利不渴。D项吴茱萸汤温肝暖胃、降逆止呕，主肝胃虚寒之巅顶头痛、吐涎沫；E项大建中汤温中补虚、降逆止痛，主阴寒内盛之心胸大寒痛；A项桂枝人参汤解表温中，主外证未解而下利痞硬"},{"q":"患者常悲伤欲哭，不能自主，心中烦乱，睡眠不安，甚则言行失常，呵欠频作，舌淡红苔少，脉细略数。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","甘麦大枣汤","养心汤"],"a":3,"e":"甘麦大枣汤养心安神、和中缓急，主治脏躁，悲伤欲哭、不能自主、心中烦乱、睡眠不安、甚则言行失常、呵欠频作，以甘草小麦大枣甘润缓急。E项养心汤益气养血安神，主心血不足之惊悸恍惚；B项天王补心丹滋阴养血，主阴虚血少舌红少苔；C项酸枣仁汤养血除烦，主肝血不足虚烦失眠；A项朱砂安神丸镇心安神，主心火亢盛"},{"q":"患者上腹部疼痛2天，查体见心下至少腹硬满疼痛而痛不可近，大便秘结，日晡潮热，舌燥而渴，脉沉紧，按之有力。宜选用的方剂是","o":["大承气汤","大陷胸汤","大柴胡汤","大秦艽汤","大建中汤"],"a":1,"e":"大陷胸汤泻热逐水，主治水热互结之结胸证，心下至少腹硬满疼痛而痛不可近、大便秘结、日晡潮热、舌燥而渴、脉沉紧有力，水热结实故痛拒按。A项大承气汤峻下热结，主阳明腑实之腹满硬痛、潮热谵语，无明显的痛不可近及自心下硬满特点；C项大柴胡汤和解少阳、通下里实，主寒热往来、胸胁苦满；小陷胸汤清热化痰、宽胸散结，主痰热互结之小结胸、按之则痛，病位与热结程度均不同"},{"q":"以发热重，恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪为辨证要点的方剂是","o":["麻黄杏仁甘草石膏汤","银翘散","升麻葛根汤","桑菊饮","柴葛解肌汤"],"a":4,"e":"柴葛解肌汤解肌清热，主治风寒郁而化热、三阳合病，发热重恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪为辨证要点。B项银翘散辛凉透表，主风热初起之发热微恶寒、咽痛口渴、脉浮数；C项升麻葛根汤解肌透疹，主疹发不出；D项桑菊饮疏风清热，主风热轻证但咳；A项麻杏石甘汤清肺平喘，主发热喘咳苔黄脉数，均无阳明经眼眶鼻干之热"},{"q":"患者，男，25岁，正值盛暑前来就诊，症见身热烦渴，小便不利。临床辨证为","o":["暑湿证","气分热盛证","暑热气津两伤证","外感风热，邪热壅肺证","风温初起，邪客肺络证"],"a":0,"e":"六一散清暑利湿，主治暑湿证，盛暑身热烦渴、小便不利，滑石清暑利水、甘草和中，暑湿并行从小便而解。B项气分热盛证见大热大汗大渴、脉洪大，无小便不利；C项暑热气津两伤证见身热汗多、体倦少气、脉虚数，属清暑益气汤；D项邪热壅肺见发热喘咳；E项风温初起见咳嗽咽痛，均与暑湿不符"},{"q":"患者，男，55岁。大便不通8天，脘腹胀满疼痛，舌黄厚而干，脉沉数有力。医生用大承气汤治疗，方中厚朴的作用是","o":["行气消胀除满","泻热通便","下气开痞散结","行气通便","软坚散结"],"a":0,"e":"厚朴在大承气汤中行气消胀除满，主治脘腹胀满，与枳实相配以气行助腑通。B项泻热通便为大黄之功，为方中君药；E项软坚散结近于芒硝，主燥屎坚结；C项下气开痞散结侧重枳实，非厚朴专责；D项行气通便表述笼统，未突出其消胀除满之能，故厚朴之用在行气消胀除满"},{"q":"患者肠痈初起。右下腹疼痛拒按，局部肿痞，善屈右足，牵则剧痛，时时发热，自汗恶寒，舌苔薄黄而腻，脉滑数。首选治疗方剂是","o":["大黄牡丹汤","苇茎汤","透脓散","小金丹","牛蒡解肌汤"],"a":0,"e":"大黄牡丹汤泻热破瘀、散结消肿，主治肠痈初起湿热瘀滞，右下腹疼痛拒按、局部肿痞、善屈右足、牵则剧痛、发热自汗恶寒、苔薄黄腻、脉滑数，瘀热结于肠腑。B项苇茎汤清肺化痰逐瘀，主肺痈咳嗽胸痛、吐腥臭脓痰；C项透脓散补气托毒排脓，主痈疡脓成；D项小金丹化痰祛瘀，主阴疽疮疡；E项牛蒡解肌汤疏风清热，主头面颈项风热"},{"q":"患者目赤肿痛，烦躁易怒，不能安卧，尿赤便秘，脉洪实。治疗应首选的方剂是","o":["凉膈散","左金丸","逍遥散","泻青丸","泻黄散"],"a":3,"e":"泻青丸清肝泻火，主治肝经火郁，目赤肿痛、烦躁易怒、不能安卧、尿赤便秘、脉洪实，肝火上炎并郁于内，泻肝火兼疏达。龙胆泻肝汤清肝胆实火、利肝经湿热，主口苦胁痛、阴肿阴痒、小便淋浊；B项左金丸清肝泻火、降逆止呕，主肝火犯胃之呕吐吞酸；C项逍遥散疏肝健脾，主肝郁血虚；E项泻黄散泻脾胃伏火，主脾热弄舌"},{"q":"患者心腹剧痛，或产后恶露不行，或月经不调，小腹急痛。治疗应首选的方剂是","o":["复元活血汤","桂枝茯苓丸","失笑散","生化汤","温经汤"],"a":2,"e":"失笑散活血祛瘀、散结止痛，主治瘀血停滞，心腹剧痛、产后恶露不行、月经不调、小腹急痛，五灵脂蒲黄相须，通利血脉止痛。D项生化汤养血祛瘀，主产后瘀阻小腹冷痛、恶露不行，重在产后；B项桂枝茯苓丸活血消癥，主瘀阻胞宫之漏下、癥块；E项温经汤温经散寒，主冲任虚寒漏下暮热；A项复元活血汤主跌打瘀血胁痛"},{"q":"患者身热心烦，口渴欲饮，恶心呕吐，小便不利，点滴难出，小腹满痛，舌红苔微黄，脉细数。治疗应首选的治法是","o":["利水渗湿，清热生津","利水渗湿，清热泻火","利水渗湿，温阳化气","利水渗湿，清热除烦","利水渗湿，养阴清热"],"a":4,"e":"该证为水热互结伤阴，猪苓汤利水渗湿、养阴清热，身热心烦、口渴欲饮、恶心呕吐、小便不利点滴难出、小腹满痛、舌红苔微黄脉细数即其主证。B项利水渗湿、清热泻火为八正散，主湿热淋证；C项温阳化气为五苓散，主膀胱气化不利；D项清热除烦重在清心，均未及养阴；E项养阴清热与利水并行，恰合阴虚水热互结"},{"q":"患者，男，58岁。有慢性肾炎病史。因气温突降，受凉感冒2天，现恶寒发热，无汗，头身疼痛，头面四肢浮肿，舌苔白滑，脉浮。可用下列何方加味治疗","o":["香苏散","葱豉桔梗汤","九味羌活汤","小青龙汤","败毒散"],"a":3,"e":"小青龙汤解表散寒、温肺化饮，主治外寒内饮，慢性肾炎受凉后恶寒发热无汗、头身疼痛、头面四肢浮肿、苔白滑脉浮，水饮溢于肌肤则浮肿。E项败毒散益气祛湿解表，主气虚外感；C项九味羌活汤祛湿清热，主湿邪困表口苦微渴；A项香苏散疏风理气，主外感兼气滞；麻黄汤发汗平喘，无温化水饮之功"},{"q":"患者，心腹作痛，连及腰胁，上下攻刺，经侯不调，宜用","o":["延胡索汤","天台乌药散","橘核丸","暖肝煎","加味乌药汤"],"a":0,"e":"延胡索汤活血行气止痛，主治气血瘀滞之痛证，心腹作痛、连及腰胁、上下攻刺、经候不调，以延胡索行血中气滞、气中血滞。B项天台乌药散行气疏肝、散寒止痛，主寒凝气滞之小肠疝气、痛引睾丸；C项橘核丸行气活血、软坚散结，主颓疝睾丸肿痛；D项暖肝煎温补肝肾、行气止痛，主肝肾不足寒凝之小腹冷痛；E项加味乌药汤疏肝理气，主妇女经前胀痛"},{"q":"患者发热无汗，口渴欲饮，一身面目俱黄，黄色鲜明如橘子色，小便黄赤，舌红苔黄腻，脉沉数。治疗应首选的治法是","o":["健脾利湿退黄","解表清热退黄","清热解毒退黄","清热利湿退黄","温阳利湿退黄"],"a":3,"e":"该证为湿热阳黄，黄色鲜明如橘子色、发热无汗、口渴、小便黄赤、舌红苔黄腻、脉沉数，湿热蕴结肝胆、胆汁外溢，治宜清热利湿退黄，茵陈蒿汤主之。A项健脾利湿退黄力缓，主脾虚湿困；B项解表清热退黄主兼表证者，如麻黄连翘赤小豆汤；E项温阳利湿退黄主阴黄寒湿，黄色晦暗；C项清热解毒退黄非利湿专法"},{"q":"症见癫狂惊悸，或怔忡昏迷，或咳喘痰稠，或胸脘痞闷，或眩晕耳鸣，或绕项结核，或口眼蠕动，或不寐，或梦寐奇怪之状，或骨节卒痛难以名状，或噎息烦闷。大便秘结，舌苔黄腻，脉滑数有力。治宜选用","o":["温胆汤","二陈汤","小陷胸汤","苓甘五味姜辛汤","滚痰丸"],"a":4,"e":"滚痰丸泻火逐痰，主治实热老痰，癫狂惊悸、怔忡昏迷、咳喘痰稠、胸脘痞闷、眩晕耳鸣、大便秘结、苔黄腻、脉滑数有力，顽痰胶结非攻不去。A项温胆汤理气化痰、和胃利胆，主胆郁痰扰之心烦不眠、苔腻脉弦滑；B项二陈汤燥湿化痰，主湿痰咳嗽痰多；C项小陷胸汤清热化痰、宽胸散结，主痰热互结心下痞满；D项苓甘五味姜辛汤温肺化饮，主寒饮"},{"q":"患者下肢疼痛剧烈，步态不稳，舌质黯红，舌下络脉黑紫迂曲。治疗应首选的方剂是","o":["膈下逐瘀汤","血府逐瘀汤","身痛逐瘀汤","复元活血汤","生化汤"],"a":2,"e":"身痛逐瘀汤活血行气、祛瘀通络、通痹止痛，主治瘀血阻络之痹痛，下肢疼痛剧烈、舌质黯红、舌下络脉黑紫迂曲，瘀血阻滞经络故痛剧。B项血府逐瘀汤活血化瘀、行气止痛，主胸中血瘀之胸痛；A项膈下逐瘀汤活血祛瘀、行气止痛，主膈下瘀血之腹中积块；D项复元活血汤主跌打损伤瘀留胁下；E项生化汤养血祛瘀，主产后瘀阻"},{"q":"患者，女，65岁。咳嗽，咯痰伴气促，痰多白稀，痰易咯出，受凉后明显，饮温水后稍缓，纳可，二便正常，舌质淡红胖嫩，苔白滑，脉沉缓。治疗宜选的方剂是","o":["苓甘五味姜辛汤","苏子降气汤","小青龙汤","三子养亲汤","定喘汤"],"a":0,"e":"苓甘五味姜辛汤温肺化饮，主治寒饮咳嗽，痰多白稀易咯、受凉加重、饮温水稍缓、舌淡胖嫩苔白滑、脉沉缓，无表证故不用麻桂。C项小青龙汤解表散寒、温肺化饮，主外寒内饮兼表证；B项苏子降气汤降气平喘、温肾纳气，主上实下虚之咳喘；D项三子养亲汤降气消食化痰，主痰壅气逆食滞；E项定喘汤清热化痰，主痰热哮喘"},{"q":"患者身热不解，无汗，咳逆气急，甚则鼻煽，口渴，舌苔薄黄，脉浮而数。治疗宜首选的方剂是","o":["麻黄杏仁甘草石膏汤","桑菊饮","柴葛解肌汤","升麻葛根汤","银翘散"],"a":0,"e":"麻黄杏仁甘草石膏汤清肺平喘，主治外感风邪、邪热壅肺，身热不解、无汗、咳逆气急甚则鼻煽、口渴、苔薄黄、脉浮数，麻黄宣肺、石膏清热，宣清并用。E项银翘散辛凉透表，主风热表证发热咽痛；B项桑菊饮疏风清热，主风热轻证但咳；C项柴葛解肌汤解肌清热，主三阳合病眼眶痛鼻干；D项升麻葛根汤解肌透疹，主疹出不畅"},{"q":"患者一身面目俱黄，黄色鲜明，小便短赤，舌红苔黄腻，脉沉数有力。主治病证是","o":["黄疸阳黄","湿热互结证","黄疸，热重于湿证","黄疸，湿重于热证","黄疸阴黄"],"a":0,"e":"该证为湿热黄疸之阳黄，一身面目俱黄、黄色鲜明、小便短赤、舌红苔黄腻、脉沉数有力，湿热蕴结肝胆、胆汁外溢肌肤。E项阴黄黄色晦暗如烟熏、舌淡苔白腻，由寒湿阻遏；D项湿重于热证身热不扬、头身困重、苔腻微黄、脉濡缓；C项热重于湿证虽黄鲜明但多伴高热烦渴、大便秘结，本例以苔黄腻脉数为湿热之象，归阳黄。B项湿热互结证范围笼统，未指出黄疸"},{"q":"患者，女，39岁。长期居住寒湿之地。症见腰、股、腿、足疼痛，手足不温，口不渴，舌淡苔白、脉细欲绝者。治宜选用","o":["当归四逆汤","四逆汤","白通汤","通脉四逆汤","四逆散"],"a":0,"e":"当归四逆汤温经散寒、养血通脉，主治血虚寒厥，腰腿足疼痛、手足不温、口不渴、舌淡苔白、脉细欲绝，血虚寒凝、脉络不通，久居寒湿之地易致。B项四逆汤回阳救逆，主阳虚寒厥之下利清谷、脉微欲绝；D项通脉四逆汤主阴盛格阳之身反不恶寒；C项白通汤主少阴下利脉微；E项四逆散透邪解郁，主阳郁厥逆之脉弦有力"},{"q":"患者咳血1周后，现血已止，但突感风寒，头痛身热，微寒无汗。治疗首选的方剂是","o":["咳血方","桑菊饮","加减葳蕤汤","葱白七味饮","归脾汤"],"a":3,"e":"葱白七味饮养血解表，主治血虚外感，咳血后血已止、复感风寒、头痛身热、微寒无汗，养血以资汗源、解表而不伤血。C项加减葳蕤汤滋阴解表，主阴虚外感咽干舌红脉数；B项桑菊饮疏风清热，主风热轻证咳嗽；E项归脾汤补益心脾，主气血两虚无表证；A项咳血方清肝宁肺、凉血止血，主肝火犯肺咳血，均非血虚外感"},{"q":"患者心下痞满，不欲饮食，倦怠乏力，大便不畅，苔腻而微黄，脉弦，宜用","o":["柴胡疏肝散","四磨汤","厚朴温中汤","枳实消痞丸","木香顺气散"],"a":3,"e":"枳实消痞丸消痞化积、健脾和胃，主治脾虚气滞、寒热互结，心下痞满、不欲饮食、倦怠乏力、大便不畅、苔腻微黄、脉弦，消补兼施、寒热并调。A项柴胡疏肝散疏肝理气，主肝气郁结之胁痛；B项四磨汤行气降逆，主七情气逆之上气喘急；C项厚朴温中汤温中行气燥湿，主脾胃寒湿之胀满苔白；E项木香顺气散行气化湿，主湿郁气滞"},{"q":"患者小便不利，烦渴欲饮，甚则水入即吐，舌苔白，脉浮或缓。治疗应首选的方剂是","o":["真武汤","五苓散","六一散","猪苓汤","萆薢分清饮"],"a":1,"e":"五苓散利水渗湿、温阳化气，主治膀胱气化不利之水湿内停，小便不利、烦渴欲饮、甚则水入即吐、苔白、脉浮或缓，外有表邪、内停水湿。D项猪苓汤利水清热养阴，主水热互结伤阴之小便不利、舌红脉细数；A项真武汤温阳利水，主阳虚水泛之小便不利、四肢沉重；C项六一散清暑利湿，主暑湿身热烦渴；E项萆薢分清饮温肾利湿，主膏淋白浊"},{"q":"王冰提出的“寒之不寒，是无水也”，宜用哪一治法治疗","o":["汗法","清法","补法","消法","温法"],"a":2,"e":"王冰注《素问》提出寒之不寒是无水也，指用寒凉药治热而热不退，根源在阴精亏虚、无水制火，当用补法滋阴壮水，即壮水之主以制阳光。A项汗法发散、D项消法攻削均伤津液；B项清法直折火热，虚火愈清愈炽；E项温法助阳，更耗阴精，皆非无水之治"},{"q":"脉结代，心动悸，虚羸少气，舌光少苔，治宜选用","o":["大补阴丸","知柏地黄丸","天王补心丹","炙甘草汤","酸枣仁汤"],"a":3,"e":"炙甘草汤益气滋阴、通阳复脉，主治气血阴阳俱虚之脉结代、心动悸，虚羸少气、舌光少苔，重用炙甘草益气温中、生地阿胶滋阴养血。C项天王补心丹滋阴养血安神，主阴虚血少之虚烦失眠；E项酸枣仁汤养血除烦，主肝血不足之虚烦不得眠；A项大补阴丸滋阴降火，主阴虚火旺之骨蒸潮热；B项知柏地黄丸滋阴清热，主阴虚火旺诸证"},{"q":"患者颈项、头面红肿热痛，牙龈肿痛，寒轻热重，汗少口渴，小便黄赤，苔黄，脉浮数。首选治疗方剂是","o":["黄连解毒汤","四妙勇安汤","牛蒡解肌汤","仙方活命饮","海藻玉壶汤"],"a":2,"e":"牛蒡解肌汤疏风清热、化痰消肿，主治头面风热、颈项痰毒，颈项头面红肿热痛、牙龈肿痛、寒轻热重、汗少口渴、小便黄赤、苔黄脉浮数。D项仙方活命饮清热解毒、消肿溃坚，主阳证疮疡红肿热痛；A项黄连解毒汤泻火解毒，主三焦火毒；B项四妙勇安汤清热解毒活血，主脱疽；E项海藻玉壶汤化痰软坚，主瘿瘤，均非头面风热"},{"q":"脾肾虚寒，久泻久痢者，治宜选用","o":["四神丸","真人养脏汤","芍药汤","葛根芩连汤","补中益气汤"],"a":1,"e":"真人养脏汤涩肠固脱、温补脾肾，主治脾肾虚寒、久泻久痢，泻痢日久、滑脱不禁、腹痛喜温、倦怠食少，罂粟壳诃子涩肠、肉桂温肾。A项四神丸温肾暖脾，专主五更泄泻；C项芍药汤清热燥湿、调气和血，主湿热痢之赤白脓血、里急后重；D项葛根芩连汤解表清里，主协热下利；E项补中益气汤补气升阳，主气虚下陷之脱肛久泻"},{"q":"患者脘腹疼痛，恶心呕吐，肠鸣泄泻，舌苔白腻，脉濡。治疗应首选的方剂是","o":["参苓白术散","痛泻要方","半夏泻心汤","理中丸","藿香正气散"],"a":4,"e":"藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞，脘腹疼痛、恶心呕吐、肠鸣泄泻、舌苔白腻、脉濡，表里同治、升降并调。C项半夏泻心汤寒热平调，主寒热互结之心下痞满、呕利；D项理中丸温中祛寒，主脾胃虚寒吐利、苔白润；A项参苓白术散健脾渗湿，主脾虚湿盛之泄泻，无表证；B项痛泻要方补脾柔肝，主痛泻"},{"q":"患者，男，50岁。便秘腹痛，脐周绞痛，畏寒肢冷，手足不温。医生选用“辛热甘温咸寒合法，寓补于攻”的方剂进行治疗，该方是","o":["大黄附子汤","温脾汤","大承气汤","小承气汤","调胃承气汤"],"a":1,"e":"温脾汤温阳健脾、泻下通便，以附子干姜辛热温阳、人参甘草甘温益气、大黄芒硝咸寒泻下，辛热甘温咸寒合法，寓补于攻，主阳虚寒积之便秘腹痛、脐周绞痛、手足不温。A项大黄附子汤温里散寒、通便止痛，无益气补虚之功；C项大承气汤、D项小承气汤、E项调胃承气汤均为寒下，主治热结，无温阳之品"},{"q":"患者，女，38岁。每到冬季，两手青紫及腕际，指尖更甚，有麻冷感，遇暖则转红。西医诊断为雷诺病。曾多方医治，疗效甚微。就诊时舌淡苔白，脉沉细微。宜选择下列哪方治疗","o":["当归四逆汤","四逆汤","通脉四逆汤","白通汤","四逆散"],"a":0,"e":"当归四逆汤温经散寒、养血通脉，主治血虚寒厥，冬季两手青紫及腕、指尖尤甚、麻冷遇暖转红、舌淡苔白、脉沉细微，血虚寒凝、四末失养，雷诺病属此。B项四逆汤回阳救逆，主阳虚寒厥脉微欲绝、下利清谷；C项通脉四逆汤主阴盛格阳；D项白通汤主少阴下利；E项四逆散疏肝理脾，主阳郁厥逆脉弦，均无血虚寒凝之象"},{"q":"患者患肢黯红微肿灼热，疼痛剧烈，久则溃烂腐臭，脚趾节脱落，延及足背，烦热口渴，舌红，脉数。首选治疗方剂是","o":["西黄丸","四妙勇安汤","五味消毒饮","阳和汤","小金丹"],"a":1,"e":"四妙勇安汤清热解毒、活血止痛，主治脱疽热毒炽盛，患肢黯红微肿灼热、疼痛剧烈、溃烂腐臭、趾节脱落、烦热口渴、舌红脉数，毒热壅滞血脉。D项阳和汤温阳补血、散寒通滞，主阴疽漫肿无头、皮色不变；C项五味消毒饮清热解毒，主疔疮痈肿；A项西黄丸清热解毒、消肿散结，主热毒痈疽；E项小金丹化痰祛瘀，主阴疽痰核"},{"q":"患者症见身热汗多，口渴心烦，小便短赤，体倦少气，精神不振，脉虚数。临床辨证为","o":["暑湿证","气分热盛证","温病后期，邪伏阴分证","暑热气津两伤证","暑温证"],"a":3,"e":"身热汗多、口渴心烦、小便短赤、体倦少气、精神不振、脉虚数，为暑热气津两伤证，暑热耗气伤津，故清热兼益气养阴，清暑益气汤主之。A项暑湿证以身热烦渴、小便不利为主；B项气分热盛证大热大汗大渴、脉洪大有力；C项温病后期邪伏阴分见夜热早凉、热退无汗；E项暑温证范围宽泛，均不若气津两伤之的切"},{"q":"患者虚烦失眠，心悸不安，头目眩晕，咽干口燥，舌红，脉弦细。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","甘麦大枣汤","养心汤"],"a":2,"e":"酸枣仁汤养血安神、清热除烦，主治肝血不足、虚热内扰，虚烦失眠、心悸不安、头目眩晕、咽干口燥、舌红脉弦细，肝藏血舍魂，血虚则魂不安。A项朱砂安神丸镇心安神、清热养血，主心火亢盛、舌红苔黄；B项天王补心丹滋阴养血，主阴虚血少舌红少苔脉细数；D项甘麦大枣汤缓急安神，主脏躁悲伤欲哭；E项养心汤益气养血，主心虚惊悸恍惚"},{"q":"葱豉桔梗汤的辨证要点是","o":["头痛身热、咳嗽、咽痛、口渴、脉浮数","发热、喘咳、苔黄、脉数","发热重、恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪","发热、微恶寒、咽痛、口渴、脉浮数","疹发不出或出而不畅、舌红、脉数"],"a":0,"e":"葱豉桔梗汤疏风清热、宣肺利咽，主治风温初起，头痛身热、咳嗽、咽痛、口渴、脉浮数为辨证要点，葱豉解表、桔梗宣肺利咽。D项所述为银翘散之发热微恶寒、咽痛口渴、脉浮数，解毒力较强；B项为麻黄杏仁甘草石膏汤之发热喘咳、苔黄脉数；C项为柴葛解肌汤之发热重恶寒轻、眼眶痛鼻干；E项为升麻葛根汤之疹发不出"},{"q":"患者，热入营分而见身热夜甚，时有谵语，口渴或不渴，目常喜开或喜闭，舌绛而干，脉细数。治疗应首选的方剂是","o":["清骨散","清营汤","青蒿鳖甲汤","秦艽鳖甲散","清瘟败毒饮"],"a":1,"e":"清营汤清营解毒、透热养阴，主治热入营分，身热夜甚、时有谵语、口渴或不渴、目喜开或喜闭、舌绛而干、脉细数，热入营阴故身热夜甚、舌绛。C项青蒿鳖甲汤养阴透热，主温病后期邪伏阴分之夜热早凉、热退无汗；A项清骨散清虚热，主阴虚潮热骨蒸；D项秦艽鳖甲散滋阴养血退蒸，主风劳病；E项清瘟败毒饮气血两燔"},{"q":"患者气喘咳嗽，皮肤蒸热，日晡尤甚，舌红苔黄，脉细数。治疗应首选的方剂是","o":["定喘汤","泻白散","导赤散","止嗽散","麻黄杏仁甘草石膏汤"],"a":1,"e":"泻白散清泻肺热、止咳平喘，主治肺热喘咳，气喘咳嗽、皮肤蒸热、日晡尤甚、舌红苔黄、脉细数，肺有伏火、气机不利，泻肺清热而不伤正。A项定喘汤宣肺降气、清热化痰，主风寒外束痰热内蕴之哮喘；C项导赤散清心利水，主心火下移小肠；D项止嗽散疏风止咳，主风邪犯肺咳嗽；E项麻杏石甘汤清肺平喘，主邪热壅肺身热喘咳脉浮数"},{"q":"患者脘腹胀满，不思饮食，舌苔白腻，脉沉弦，宜选用","o":["理中丸","藿香正气散","枳实消痞丸","半夏泻心汤","厚朴温中汤"],"a":4,"e":"厚朴温中汤行气除满、温中燥湿，主治脾胃寒湿气滞，脘腹胀满、不思饮食、舌苔白腻、脉沉弦，寒湿中阻、气机不畅，故温中行气。C项枳实消痞丸消痞化积、健脾和胃，主脾虚寒热互结之痞满、倦怠乏力、苔腻微黄；A项理中丸温中祛寒，主脾胃虚寒之腹痛泄泻；D项半夏泻心汤寒热平调，主心下痞满、呕吐泻利；B项藿香正气散解表化湿，主外感湿滞"},{"q":"患者症见身热汗多，口渴心烦，小便短赤，体倦少气，精神不振，脉虚数。此病证的治法是","o":["清泻肺热，止咳平喘","清暑利湿","清暑益气，养阴生津","祛暑解表，化湿和中","益气生津，敛阴止汗"],"a":2,"e":"该证为暑热气津两伤，身热汗多、口渴心烦、小便短赤、体倦少气、脉虚数，治宜清暑益气、养阴生津，清暑益气汤主之。A项清泻肺热止咳平喘为泻白散；B项清暑利湿为六一散，主暑湿；D项祛暑解表化湿和中为香薷散或藿香正气散；E项益气生津、敛阴止汗为生脉散，均无清暑之力，不若清暑益气汤的切"},{"q":"患者三焦火毒热盛证而见有湿热黄疸，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["茵陈蒿汤","栀子柏皮汤","黄连解毒汤","普济消毒饮","甘露消毒丹"],"a":2,"e":"黄连解毒汤泻火解毒，主治三焦火毒热盛，大热烦躁、湿热黄疸、舌红苔黄、脉数有力，三黄苦寒直折三焦之火，火去则湿无所附。A项茵陈蒿汤清热利湿退黄，主阳黄黄色鲜明；B项栀子柏皮汤清热利湿，主湿热黄疸身热发黄；D项普济消毒饮疏风清热解毒，主大头瘟；E项甘露消毒丹利湿化浊、清热解毒，主湿温时疫湿热并重"},{"q":"患者见寒热如疟，寒轻热重，口苦膈闷，吐酸苦水，胸胁胀痛，小便黄少，舌红苔黄腻，脉数而右滑左弦。首选方剂是","o":["逍遥散","小柴胡汤","茵陈蒿汤","龙胆泻肝汤","蒿芩清胆汤"],"a":4,"e":"蒿芩清胆汤清胆利湿、和胃化痰，主治少阳湿热证，寒热如疟、寒轻热重、口苦膈闷、吐酸苦水、胸胁胀痛、小便黄少、舌红苔黄腻、脉数右滑左弦，胆火犯胃、湿热内蕴。B项小柴胡汤和解少阳，主寒热往来、胸胁苦满、苔薄白脉弦，无湿热之象；A项逍遥散疏肝健脾，主肝郁血虚；C项茵陈蒿汤清热利湿退黄；D项龙胆泻肝汤清肝胆实火湿热下注"},{"q":"患者恶寒身热，头痛无汗，胸脘痞闷，不思饮食，舌苔薄白，脉浮。治疗应自选的方剂是","o":["桂枝汤","香苏散","大青龙汤","败毒散","九味羌活汤"],"a":1,"e":"香苏散疏风散寒、理气和中，主治外感风寒、内有气滞，恶寒身热、头痛无汗、胸脘痞闷、不思饮食、苔薄白脉浮，理气以助解表。A项桂枝汤解肌发表，主表虚汗出脉浮缓；C项大青龙汤发汗清热，主不汗出而烦躁；D项败毒散益气解表，主气虚外感头身重痛；E项九味羌活汤祛湿清热，主肢体酸楚、口苦微渴，均无胸脘痞闷之气滞"},{"q":"患者咳嗽气喘，咽喉干燥，喉中有声，痰中带血，舌红少苔，脉细数。治宜","o":["百合固金汤","桑杏汤","清燥救肺汤","补肺阿胶汤","玉液汤"],"a":3,"e":"补肺阿胶汤养阴补肺、清热止血，主治肺虚热盛，咳嗽气喘、咽喉干燥、喉中有声、痰中带血、舌红少苔、脉细数，阿胶滋阴止血、马兜铃清肺降气。A项百合固金汤滋养肺肾，主肺肾阴虚之咳嗽痰血、咽喉燥痛、午后潮热；C项清燥救肺汤清燥润肺，主温燥重证；B项桑杏汤清宣温燥轻证；E项玉液汤益气滋阴，主消渴"},{"q":"症见久泻不愈，不思饮食，食不消化，腹痛喜温，腰酸肢冷，神疲乏力，舌淡，苔薄白，脉沉迟无力者。治宜首选","o":["真人养脏汤","肾气丸","桃花汤","四神丸","芍药汤"],"a":0,"e":"真人养脏汤涩肠固脱、温补脾肾，主治脾肾虚寒、久泻不愈，食不消化、腹痛喜温、腰酸肢冷、神疲乏力、舌淡苔薄白、脉沉迟无力，久泻滑脱故需固涩。D项四神丸温肾暖脾，主五更泄泻定时；C项桃花汤温中涩肠，主虚寒痢便脓血；B项肾气丸补肾助阳，主肾阳不足腰痛脚软、小便不利；E项芍药汤清热燥湿，主湿热痢"},{"q":"症见痔疮出血，血色鲜红，舌红苔黄，脉数，治宜选用","o":["胶艾汤","归脾汤","黄土汤","槐花散","葛根芩连汤"],"a":3,"e":"槐花散清肠止血、疏风行气，主治肠风脏毒下血，痔疮出血、血色鲜红、舌红苔黄脉数，大肠湿热、血热妄行，便前出血为其特点。A项胶艾汤养血止血、调经安胎，主冲任虚损之崩漏、胎漏；C项黄土汤温阳健脾、养血止血，主脾阳不足之远血、血色暗淡；B项归脾汤益气摄血，主心脾两虚之便血崩漏；E项葛根芩连汤解表清里，主协热下利"},{"q":"患者小便频数，淋沥不畅，溺时涩痛，小腹急满，舌苔黄腻，脉滑数。本证的病机是","o":["瘀热下注，蕴于膀胱","寒湿下注，蕴于膀胱","热毒下注，蕴于膀胱","暑湿下注，蕴于膀胱","湿热下注，蕴于膀胱"],"a":4,"e":"该证为湿热下注、蕴于膀胱之热淋，小便频数、淋沥不畅、溺时涩痛、小腹急满、苔黄腻脉滑数，湿热蕴结膀胱、气化不利。A项瘀热下注则兼尿血刺痛；B项寒湿下注苔白腻、无明显热象；C项热毒下注全身毒热症状显著；D项暑湿下注有明显暑季时令，均不若湿热下注之切合苔黄腻、脉滑数"},{"q":"妇人素有癥块，妊娠漏下不止，血色紫黑晦黯，舌质紫黯或有瘀点，脉沉涩者。治宜首选","o":["血府逐瘀汤","复元活血汤","生化汤","温经汤","桂枝茯苓丸"],"a":4,"e":"桂枝茯苓丸活血化瘀、缓消癥块，主治瘀阻胞宫，妇人素有癥块、妊娠漏下不止、血色紫黑晦黯、舌紫黯有瘀点、脉沉涩，祛瘀而不伤正、消癥而不动胎。A项血府逐瘀汤活血化瘀、行气止痛，主胸中血瘀胸痛；B项复元活血汤主跌打瘀血胁下；C项生化汤养血祛瘀，主产后恶露不行；D项温经汤温经散寒养血，主冲任虚寒漏下、小腹冷痛"},{"q":"以恶寒发热，无汗，烦躁，脉浮紧为辨证要点的方剂是","o":["麻黄汤","大青龙汤","桂枝汤","败毒散","小青龙汤"],"a":1,"e":"大青龙汤发汗解表、清热除烦，主治外寒里热，恶寒发热、无汗、烦躁、脉浮紧，麻黄倍量配石膏，发越阳气、外散风寒内清郁热。A项麻黄汤发汗平喘，主风寒束表无汗而喘、无烦躁；C项桂枝汤解肌发表，主表虚汗出脉浮缓；D项败毒散益气解表，主气虚外感；E项小青龙汤解表化饮，主外寒内饮之咳痰清稀，均无里热烦躁"},{"q":"患者心中烦热，失眠不得卧，口燥咽干，舌红苔少，脉细数。治疗应首选的方剂是","o":["朱砂安神丸","黄连阿胶汤","酸枣仁汤","桂枝甘草龙骨牡蛎汤","交泰丸"],"a":1,"e":"黄连阿胶汤滋阴降火，主治少阴热化、阴虚火旺，心中烦热、失眠不得卧、口燥咽干、舌红苔少、脉细数，黄连黄芩清心火、阿胶芍药滋阴血。A项朱砂安神丸镇心安神、清热养血，主心火亢盛舌红苔黄；C项酸枣仁汤养血除烦，主肝血不足之虚烦失眠、头目眩晕；D项桂枝甘草龙骨牡蛎汤温通心阳、镇慑安神，主心阳虚烦躁；E项交泰丸交通心肾，主心肾不交口舌生疮"},{"q":"患者，男，50岁。便秘腹痛，脐周绞痛，畏寒肢冷，手足不温。医生选用温脾汤治疗，该方的君药是","o":["干姜、大黄","附子、干姜","大黄、芒硝","干姜、人参","附子、大黄"],"a":4,"e":"温脾汤以附子大辛大热温壮脾阳、散寒凝，大黄泻下攻积，二者相合温下寒积，共为君药，针对阳虚寒积便秘。B项干姜虽助附子温中，为臣药，温力次于附子；D项人参、甘草益气补中，当归养血润肠，均为佐使；C项大黄、芒硝虽能泻下软坚，但芒硝在方中仅佐大黄软坚润燥，非君药，故君药为附子与大黄"},{"q":"患者，男，35岁。发狂2月，语无伦次，近10天病情加重，性情急躁，两目怒视，狂乱无知，不避亲疏，弃衣欲走，叫喊不已，大便秘结，脉象浮滑洪紧，舌苔黄燥。治宜选用的方剂是","o":["朱砂安神丸","镇肝熄风汤","大承气汤","桃核承气汤","酸枣仁汤"],"a":2,"e":"大承气汤峻下热结，主治阳明腑实、热结旁流，发狂、语无伦次、性情急躁、弃衣欲走、叫喊不已、大便秘结、脉浮滑洪紧、苔黄燥，釜底抽薪以泻阳明实热。D项桃核承气汤破血下瘀，主下焦蓄血少腹急结、其人如狂；B项镇肝熄风汤镇肝熄风，主肝阳上亢气血逆乱；A项朱砂安神丸镇心安神，主心火亢盛；E项酸枣仁汤养血安神，主肝血不足虚烦"},{"q":"患者猝然心腹疼痛，牙关紧闭，昏仆不醒，急救应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","苏合香丸","紫金锭"],"a":3,"e":"苏合香丸芳香开窍、行气温中，主治寒闭证，猝然心腹疼痛、牙关紧闭、昏仆不醒、身凉无热，寒邪秽浊闭阻窍道，温开为宜。A项安宫牛黄丸、B项紫雪、C项至宝丹均为凉开三宝，主热闭神昏，症见高热烦躁、神昏谵语，与本例无热象之寒闭相反；E项紫金锭化痰开窍、辟秽解毒，主秽恶痰浊之中暑吐泻，非寒闭急救首选"},{"q":"患者，男，30岁。平素喜食火锅，现感冒1天，症见恶寒发热，无汗，头痛项强，肢体酸楚疼痛，口苦口渴，舌苔黄，脉浮紧。可用下列何方加味治疗","o":["大青龙汤","九味羌活汤","麻黄杏仁甘草石膏汤","白虎汤","败毒散"],"a":1,"e":"九味羌活汤发汗祛湿、兼清里热，主治外感风寒湿邪、内有蕴热，恶寒发热、无汗、头痛项强、肢体酸楚疼痛、口苦口渴、苔黄、脉浮紧，分经论治。A项大青龙汤发汗清热，主不汗出而烦躁；C项麻杏石甘汤清肺平喘，主邪热壅肺喘咳；D项白虎汤清气分大热，主大热大汗大渴；E项败毒散益气解表，主气虚外感，均无肢体酸楚与口苦苔黄"},{"q":"以头痛身热，恶寒无汗兼见血虚或有失血病史为辨证要点的方剂是","o":["当归补血汤","桑菊饮","加减葳蕤汤","葱白七味饮","归脾汤"],"a":3,"e":"葱白七味饮养血解表，主治血虚外感，头痛身热、恶寒无汗兼血虚或失血病史，养血滋汗源、解表不伤正。C项加减葳蕤汤滋阴解表，主阴虚外感咽干舌红脉数；A项当归补血汤补气生血，主血虚发热、脉洪大而虚，无头痛恶寒表证；B项桑菊饮疏风清热，主风热轻证；E项归脾汤补益心脾，主气血两虚之心悸失眠，均非血虚外感"},{"q":"患者，男，43岁。证见脘腹痞满胀痛，嗳腐吞酸，恶食呕逆，伴大便泄泻，舌苔厚腻，脉滑。治宜","o":["木香槟榔丸","葛花解酲汤","保和丸","枳实导滞丸","健脾丸"],"a":2,"e":"保和丸消食和胃，主治食积停滞，脘腹痞满胀痛、嗳腐吞酸、恶食呕逆、大便泄泻、苔厚腻、脉滑，消食导滞兼清泄郁热。A项木香槟榔丸行气攻积力猛，主积滞内停之痞满胀痛、大便秘结；B项葛花解酲汤分消酒湿，主饮酒太过之呕吐泄泻；D项枳实导滞丸消积导滞、清利湿热，主湿热食积之小便短赤、苔黄腻；E项健脾丸健脾消食，主脾虚食积乏力"},{"q":"症见尿频、遗尿，心神恍惚，健忘，舌淡苔白，脉细弱，治宜选","o":["桑螵蛸散","归脾汤","萆薢分清饮","缩泉丸","天王补心丹"],"a":0,"e":"桑螵蛸散调补心肾、涩精止遗，主治心肾两虚、水火不交，尿频遗尿、心神恍惚、健忘、舌淡苔白、脉细弱，尿频与神志失常并见。D项缩泉丸温肾缩尿，主膀胱虚寒之尿频遗尿、小腹冷，无健忘恍惚；C项萆薢分清饮温肾利湿、分清去浊，主膏淋白浊；B项归脾汤补益心脾，主心脾两虚之惊悸健忘，无尿频遗尿；E项天王补心丹滋阴安神，主阴虚火旺"},{"q":"患者突然耳聋，伴有口苦，目赤，耳肿，舌红苔黄，脉弦数有力。治疗应首选的方剂是","o":["清胃散","凉膈散","六味地黄丸","龙胆泻肝汤","黄连解毒汤"],"a":3,"e":"龙胆泻肝汤清肝胆实火、利肝经湿热，主治肝胆实火上炎，突然耳聋、口苦、目赤、耳肿、舌红苔黄、脉弦数有力，肝胆火盛循经上扰清窍。A项清胃散清胃凉血，主胃火牙痛；B项凉膈散清上泄下，主上中二焦火热；C项六味地黄丸滋补肾阴，主肾阴虚之耳鸣耳聋、腰膝酸软、脉细数，属虚证而非实火；E项黄连解毒汤泻三焦火，无清肝利湿之专"},{"q":"患者，男，23岁。大便不通7天，兼见频转矢气，脘腹痞满，腹痛拒按，手足濈然汗出，舌苔黄燥，脉沉实。医生主张用“苦辛通降与咸寒合法，泻下与行气并重”的方剂治疗，此方是","o":["小承气汤","大承气汤","温脾汤","黄龙汤","调胃承气汤"],"a":1,"e":"大承气汤峻下热结，以大黄苦寒泻热、芒硝咸寒软坚，合厚朴枳实行气除满，苦辛通降与咸寒合法，泻下与行气并重，主大便不通、频转矢气、腹满痛拒按、手足濈然汗出、脉沉实。A项小承气汤无芒硝，无咸寒软坚；C项温脾汤温阳泻下，主寒积；D项黄龙汤攻下养正，主热结气血虚；E项调胃承气汤无枳朴，行气之力不足"},{"q":"患者恶寒发热，头项强痛，肢体酸痛，无汗，鼻塞声重，咳嗽有痰，胸膈痞满，舌淡苔白，脉浮而按之无力。治疗应首选的方剂是","o":["九味羌活汤","葱白七味饮","再造散","败毒散","参苏饮"],"a":3,"e":"败毒散益气解表、散风祛湿，主治气虚外感风寒湿，恶寒发热、头项强痛、肢体酸痛、无汗、鼻塞声重、咳嗽有痰、胸膈痞满、脉浮按之无力，人参扶正驱邪。A项九味羌活汤燥湿清热，主肢体酸楚、口苦微渴；B项葱白七味饮养血解表，主血虚外感；C项再造散助阳益气，主阳虚肢冷脉沉；E项参苏饮理气化痰，主气虚痰湿咳嗽，均无肢体酸痛之风湿重象"},{"q":"患者，大头瘟。治疗应首选的方剂是","o":["五味消毒饮","仙方活命饮","普济消毒饮","黄连解毒汤","清瘟败毒饮"],"a":2,"e":"普济消毒饮清热解毒、疏风散邪，主治大头瘟，头面红肿焮痛、恶寒发热、咽喉不利，风热疫毒上攻头面，黄芩黄连清热解毒、升降散疏散风热。B项仙方活命饮清热解毒、消肿溃坚，主阳证疮疡肿毒初起；A项五味消毒饮清热解毒，主疔疮痈肿；D项黄连解毒汤泻火解毒，主三焦火毒；E项清瘟败毒饮清热解毒、凉血泻火，主气血两燔"},{"q":"患者，女，32岁。发病3年，手足厥冷，但不过膝、不过肘，面色㿠白，口不渴，舌淡苔白，脉沉细。宜选择下列哪方治疗","o":["吴茱萸汤","小建中汤","当归四逆汤","四逆汤","大建中汤"],"a":2,"e":"当归四逆汤温经散寒、养血通脉，主治血虚寒厥，手足厥冷不过膝肘、面色㿠白、口不渴、舌淡苔白、脉沉细，血虚寒凝、四末失温，病程较缓。D项四逆汤回阳救逆，主阳虚寒厥之厥逆过膝肘、下利清谷、脉微欲绝；A项吴茱萸汤温肝暖胃，主巅顶头痛、吐涎沫；B项小建中汤温中补虚，主中焦虚寒腹痛；E项大建中汤主心胸中大寒痛，均非血虚四末厥冷"},{"q":"患者，男。运动后吹风，感冒1天。现体温39.5℃，怕风，无汗，口渴头痛，咽痛咳嗽，舌尖红，苔薄黄，脉浮数。可用下列何方加减治疗","o":["桑菊饮","银翘散","柴葛解肌汤","升麻葛根汤","麻黄杏仁甘草石膏汤"],"a":1,"e":"银翘散辛凉透表、清热解毒，主治风热犯表，发热、怕风、无汗、口渴头痛、咽痛咳嗽、舌尖红、苔薄黄、脉浮数，发热咽痛较著。A项桑菊饮疏风清热，主风热轻证但咳、身热不甚；C项柴葛解肌汤解肌清热，主三阳合病之眼眶痛鼻干；D项升麻葛根汤解肌透疹，主疹出不畅；E项麻杏石甘汤清肺平喘，主邪热壅肺之喘咳鼻煽，均非单纯风热表证"},{"q":"患者身重疼痛，肢体倦怠，胸闷不饥，午后身热，苔白不渴，脉弦细而濡。本证的病机是","o":["热重于湿，脾胃失和","湿重于热，脾胃失和","湿热并重，脾胃失和","湿热困脾，升降失常","寒湿困脾，升降失常"],"a":1,"e":"该证为湿重于热、脾胃失和，湿阻气机则身重疼痛、肢体倦怠、胸闷不饥，湿郁渐化热则午后身热，苔白不渴、脉弦细而濡，三仁汤宣畅气机、清利湿热主之。A项热重于湿者身热显著、口渴苔黄；C项湿热并重者咽痛颐肿、苔黄腻；D项湿热困脾升降失常以脘痞呕恶为主；E项寒湿困脾则无午后身热、苔白腻，均不若湿重于热之切"},{"q":"患者，男，67岁。咽痒咳嗽，甚则伴喘，痰多色白清稀，纳可，时有心悸，苔白，脉紧而弦。治疗应首选的方剂是","o":["苓甘五味姜辛汤","止嗽散","小青龙汤","苏子降气汤","二陈汤"],"a":0,"e":"苓甘五味姜辛汤温肺化饮，主治寒饮咳嗽，咽痒咳嗽、甚则伴喘、痰多色白清稀、苔白、脉紧而弦，饮为阴邪，遇寒则甚，得温则减。C项小青龙汤解表化饮，主外寒内饮兼恶寒发热无汗；D项苏子降气汤降气平喘、温肾纳气，主上实下虚之咳喘；E项二陈汤燥湿化痰，主湿痰咳嗽痰多易咯；B项止嗽散疏风止咳，主风邪犯肺咽痒咳嗽，均无温化寒饮之专"},{"q":"患者男，吹风后感冒1天。现头痛身热，微恶风寒，咳嗽，咽痛，口渴，舌尖红，苔薄白，脉浮数。治疗可用下列何方加减治疗","o":["银翘散","葱豉桔梗汤","麻黄杏仁甘草石膏汤","柴葛解肌汤","升麻葛根汤"],"a":1,"e":"葱豉桔梗汤疏风清热、宣肺利咽，主治风温初起，头痛身热、微恶风寒、咳嗽咽痛、口渴、舌尖红、苔薄白、脉浮数，葱豉解表、桔梗宣肺，力轻清宣散。A项银翘散清热解毒力较强，主风热较重、发热咽痛显著；C项麻杏石甘汤清肺平喘，主邪热壅肺喘咳；D项柴葛解肌汤解肌清热，主三阳合病眼眶痛鼻干；E项升麻葛根汤解肌透疹，主疹出不畅"},{"q":"患者少腹瘀血积块，疼痛，经期腰酸，久不受孕。治疗应首选的方剂是","o":["失笑散","少腹逐瘀汤","桃核承气汤","复元活血汤","生化汤"],"a":1,"e":"少腹逐瘀汤活血祛瘀、温经止痛，主治少腹瘀血积块，少腹瘀血积块疼痛、经期腰酸、久不受孕，小茴香肉桂温经散寒、当归川芎活血，瘀去则胞宫得养。A项失笑散活血止痛，主瘀血停滞之心腹剧痛；C项桃核承气汤破血下瘀，主下焦蓄血少腹急结、其人如狂；D项复元活血汤主跌打瘀血留于胁下；E项生化汤养血祛瘀，主产后恶露不行腹痛"},{"q":"患者汗多神疲，体倦乏力，气短懒言，咽干口渴，干咳少痰，短气自汗，治疗宜用的方剂是","o":["生脉散","肾气丸","补中益气汤","归脾汤","四物汤"],"a":0,"e":"生脉散益气生津、敛阴止汗，主治气阴两虚，汗多神疲、体倦乏力、气短懒言、咽干口渴、干咳少痰、短气自汗，补气以生阴、敛阴以固脱。C项补中益气汤补中益气、升阳举陷，主气虚发热、久泻脱肛，无咽干口渴干咳；B项肾气丸补肾助阳，主肾阳不足；D项归脾汤补益心脾，主心悸失眠；E项四物汤补血调血，主营血虚滞，均无益气养阴之功"},{"q":"患者，女，35岁。证见食少难消，脘腹痞满，大便溏薄，倦怠乏力，苔腻微黄，脉虚弱。宜选","o":["保和丸","枳术丸","温脾汤","归脾丸","健脾丸"],"a":4,"e":"健脾丸健脾和胃、消食止泻，主治脾虚食积，食少难消、脘腹痞满、大便溏薄、倦怠乏力、苔腻微黄、脉虚弱，消补兼施，健脾为主。A项保和丸消食和胃，主单纯食积之嗳腐吞酸、苔厚腻，无脾虚乏力；B项枳术丸健脾消食，主脾虚气滞之痞满、食后尤甚；C项温脾汤温阳泻下，主寒积便秘；D项归脾丸补益心脾，主心脾两虚之惊悸健忘，无食积"},{"q":"患者胸胁满闷，目眩心悸，舌苔白滑，脉弦滑。治疗应首选的方剂是","o":["十枣汤","苓桂术甘汤","龙胆泻肝汤","柴胡疏肝散","苏子降气汤"],"a":1,"e":"苓桂术甘汤温阳化饮、健脾利湿，主治中阳不足之痰饮，胸胁满闷、目眩心悸、舌苔白滑、脉弦滑，脾阳虚则水饮内停、上犯清阳则目眩。A项十枣汤攻逐水饮，主悬饮之胸胁引痛、咳唾；C项龙胆泻肝汤清肝胆实火湿热，主口苦胁痛、小便淋浊；D项柴胡疏肝散疏肝理气，主肝气郁结之胁痛；E项苏子降气汤降气平喘，主上实下虚之咳喘"},{"q":"患者，女，66岁。眼睑痉挛不适1年余。现症见眼睑痉挛，面肌搐抖，下颌抽动，似嚼食物，口干口苦，纳少寐差，大便不畅，舌质红，苔黄腻，脉弦滑。治疗应首选的方剂是","o":["定痫丸","半夏白术天麻汤","龙胆泻肝汤","天麻钩藤饮","镇肝熄风汤"],"a":0,"e":"定痫丸涤痰熄风、开窍安神，主治风痰蕴热之痫证，眼睑痉挛、面肌搐抖、下颌抽动、口干口苦、大便不畅、舌红苔黄腻、脉弦滑，风痰上扰清窍。B项半夏白术天麻汤化痰熄风，主风痰上扰之眩晕头痛、苔白腻，无黄腻苔；C项龙胆泻肝汤清肝胆实火，主口苦胁痛；D项天麻钩藤饮平肝熄风，主肝阳上亢之眩晕；E项镇肝熄风汤镇肝熄风，主气血上逆之中风"},{"q":"患者，男，28岁。左小腿有一处局部漫肿无头，酸痛无热，皮色不变，口不渴，舌苔淡白，脉沉细。治疗宜选用","o":["阳和汤","西黄丸","透脓散","小金丹","仙方活命饮"],"a":0,"e":"阳和汤温阳补血、散寒通滞，主治阴疽，局部漫肿无头、酸痛无热、皮色不变、口不渴、舌苔淡白、脉沉细，阳虚血弱、寒凝痰滞，熟地鹿角胶补血、麻黄姜炭散寒。B项西黄丸清热解毒、消肿散结，主热毒痈疽；C项透脓散补气托毒排脓，主痈疡脓成难溃；D项小金丹化痰祛瘀，主痰瘀凝滞之阴疽疮疡；E项仙方活命饮清热解毒，主阳证疮疡红肿热痛"},{"q":"患者但咳，身热不甚，口微渴，脉浮数。治疗宜首选的方剂是","o":["升麻葛根汤","麻黄杏仁甘草石膏汤","桑菊饮","银翘散","柴葛解肌汤"],"a":2,"e":"桑菊饮疏风清热、宣肺止咳，主治风热轻证，但咳、身热不甚、口微渴、脉浮数，重在宣肺止咳，辛凉轻剂。D项银翘散辛凉透表、清热解毒，主风热较重之发热咽痛口渴；B项麻黄杏仁甘草石膏汤清肺平喘，主邪热壅肺之发热喘咳；A项升麻葛根汤解肌透疹，主麻疹初起疹出不畅；E项柴葛解肌汤解肌清热，主三阳合病发热重、眼眶痛鼻干"},{"q":"患者素体肺肾阴虚，现咳嗽气喘，痰中带血，咽喉燥痛，头晕目眩，午后潮热，舌红少苔，脉细数。治疗宜首选的方剂是","o":["沙参麦冬汤","百合固金汤","麦门冬汤","琼玉膏","清燥救肺汤"],"a":1,"e":"百合固金汤滋养肺肾、止咳化痰，主治肺肾阴虚、虚火上炎，咳嗽气喘、痰中带血、咽喉燥痛、头晕目眩、午后潮热、舌红少苔、脉细数，肺肾同病故滋阴兼顾。A项沙参麦冬汤养阴清肺、益胃生津，主肺胃阴伤之干咳少痰；C项麦门冬汤清养肺胃、降逆下气，主虚热肺痿或胃阴不足呕吐；D项琼玉膏滋阴润肺，主肺痨虚劳咳嗽；E项清燥救肺汤清燥润肺，主温燥重证"},{"q":"患者，女，30岁。大便不通5天，脘腹胀满疼痛，舌黄厚而干，脉沉数有力。下列最为适宜的方剂是","o":["大陷胸汤","温脾汤","大黄附子汤","大承气汤","麻子仁丸"],"a":3,"e":"大承气汤峻下热结，主治阳明腑实，大便不通、脘腹胀满疼痛、舌黄厚而干、脉沉数有力，大黄芒硝泻下软坚、厚朴枳实行气除满，痞满燥实坚兼备。A项大陷胸汤泻热逐水，主结胸之心下至少腹硬满痛不可近；B项温脾汤温阳泻下，主寒积便秘；C项大黄附子汤温里散寒通便，主寒积胁下偏痛；E项麻子仁丸润肠泄热，主脾约之大便干结、小便频数"},{"q":"气虚血瘀之中风证，治宜选方","o":["桃核承气汤","血府逐瘀汤","小蓟饮子","槐花散","补阳还五汤"],"a":4,"e":"补阳还五汤补气活血通络，主治气虚血瘀之中风，重用黄芪大补元气，当归尾赤芍川芎等活血化瘀，气旺则血行、瘀去则络通，适用于半身不遂、口眼歪斜、语言謇涩。A项桃核承气汤破血下瘀，主下焦蓄血；B项血府逐瘀汤活血化瘀、行气止痛，主胸中血瘀胸痛；C项小蓟饮子凉血止血，主血淋；D项槐花散清肠止血，主肠风便血"},{"q":"患者发热，微恶风寒，无汗，口渴头痛，咽痛咳嗽，舌尖红，苔薄黄，脉浮数。治疗应首选的方剂是","o":["银翘散","桑菊饮","麻黄杏仁甘草石膏汤","柴葛解肌汤","升麻葛根汤"],"a":0,"e":"银翘散辛凉透表、清热解毒，主治风热犯表，发热、微恶风寒、无汗、口渴头痛、咽痛咳嗽、舌尖红、苔薄黄、脉浮数。B项桑菊饮疏风清热，主风热轻证但咳、身热不甚、口微渴；C项麻黄杏仁甘草石膏汤清肺平喘，主邪热壅肺喘咳；D项柴葛解肌汤解肌清热，主三阳合病眼眶痛鼻干；E项升麻葛根汤解肌透疹，主疹出不畅"},{"q":"患者胸痛，日久不愈，痛如针刺而有定处，舌质黯红，脉紧。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":3,"e":"血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀，胸痛日久不愈、痛如针刺而有定处、舌质黯红、脉紧涩，瘀血内停胸中、气机阻滞，活血兼行气则瘀去痛止。B项补阳还五汤补气活血，主气虚血瘀之中风半身不遂；C项桃核承气汤破血下瘀，主下焦蓄血少腹急结；A项清营汤清营解毒，主热入营分身热夜甚舌绛；E项清骨散清虚热，主阴虚骨蒸"},{"q":"患者，热入血分而见尿血、便血，舌深绛起刺，脉数。治疗应首选的方剂是","o":["小蓟饮子","槐花散","犀角地黄汤","羚角钩藤汤","大定风珠"],"a":2,"e":"犀角地黄汤清热解毒、凉血散瘀，主治热入血分，尿血便血、舌深绛起刺、脉数，热毒炽盛、迫血妄行，凉血兼散瘀使血止而不留瘀。A项小蓟饮子凉血止血、利水通淋，主下焦热结之血淋、尿中带血赤涩热痛；B项槐花散清肠止血，主肠风脏毒便血；D项羚角钩藤汤凉肝熄风，主热盛动风抽搐；E项大定风珠滋阴熄风，主温病后期虚风内动"},{"q":"患者小便不利，脐下动悸，吐涎沫而头眩，舌苔白，脉缓。本证的病机是","o":["水热结于下焦，痰饮内停","湿热下注膀胱，痰饮内停","膀胱气化不利，痰饮内停","暑湿下注膀胱，痰饮内停","瘀热下注膀胱，痰饮内停"],"a":2,"e":"该证为膀胱气化不利、痰饮内停，五苓散利水渗湿、温阳化气，小便不利、脐下动悸、吐涎沫而头眩、舌苔白、脉缓，水停下焦、上犯清阳则头眩。A项水热结于下焦为猪苓汤，兼舌红脉细数伤阴；B项湿热下注膀胱见尿频涩痛、苔黄腻；D项暑湿下注有暑季特征；E项瘀热下注兼尿血刺痛，均不若气化不利、痰饮内停之切"},{"q":"患者反复咳喘10余年，咳甚则气喘自汗，痰少而粘，脉虚数。治宜首选","o":["生脉散","定喘汤","泻白散","九仙散","麻黄汤"],"a":3,"e":"九仙散敛肺止咳、益气养阴，主治久咳肺虚，反复咳喘、咳甚气喘自汗、痰少而黏、脉虚数，久咳耗伤肺气阴，故敛肺固表兼养阴。A项生脉散益气生津、敛阴止汗，主气阴两虚之汗多体倦，无久咳；B项定喘汤宣肺降气、清热化痰，主痰热哮喘；C项泻白散清泻肺热，主肺热喘咳皮肤蒸热；E项麻黄汤发汗平喘，主风寒表实，均非久咳虚喘"},{"q":"症见痰稠色黄，咯之不爽，胸膈痞闷，甚则气急呕恶，舌质红，苔黄腻，脉滑数者，治宜选用","o":["贝母瓜萎散","温胆汤","半夏白术天麻汤","苓甘五味姜辛汤","清气化痰丸"],"a":4,"e":"清气化痰丸清热化痰、理气止咳，主治痰热咳嗽，痰稠色黄、咯之不爽、胸膈痞闷、甚则气急呕恶、舌红苔黄腻、脉滑数，痰热互结、气机不畅。A项贝母瓜蒌散润肺清热、理气化痰，主燥痰之咯痰不爽、咽喉干燥、苔白而干；B项温胆汤理气化痰、和胃利胆，主胆郁痰扰之心烦不眠；D项苓甘五味姜辛汤温肺化饮，主寒饮痰稀；C项半夏白术天麻汤化痰熄风，主风痰眩晕"},{"q":"患者见恶寒发热，头疼身痛，无汗，腹痛吐泻，胸脘痞闷，舌苔白腻，脉浮，治宜首选","o":["清暑益气汤","竹叶石膏汤","香薷散","桂苓甘露散","六一散"],"a":2,"e":"香薷散祛暑解表、化湿和中，主治阴暑，恶寒发热、头疼身痛、无汗、腹痛吐泻、胸脘痞闷、苔白腻脉浮，暑天贪凉饮冷、外感寒邪内伤湿滞。A项清暑益气汤清暑益气养阴，主暑热气津两伤之体倦少气脉虚数；B项竹叶石膏汤清热生津、益气和胃，主伤寒解后虚羸少气；D项桂苓甘露散清暑化气利水，主暑湿之发热烦渴小便不利；E项六一散清暑利湿，主暑湿轻证"},{"q":"治疗脏躁首选的方剂是","o":["养心汤","天王补心丹","酸枣仁汤","甘麦大枣汤","磁朱丸"],"a":3,"e":"甘麦大枣汤养心安神、和中缓急，主治脏躁，为治疗脏躁之首选方，精神恍惚、悲伤欲哭、不能自主、心中烦乱、睡眠不安、呵欠频作，以甘草小麦大枣甘润缓急安神。A项养心汤益气养血安神，主心血不足之惊悸恍惚；B项天王补心丹滋阴养血，主阴虚血少虚烦失眠；C项酸枣仁汤养血除烦，主肝血不足虚烦；E项磁朱丸重镇安神，主心肾不交心悸失眠"},{"q":"患者头痛恶寒，肢体倦怠，身重疼痛，胸闷不饥，午后身热，面色淡黄，苔白不渴，脉濡。主治病证是","o":["湿温初起之湿热并重证","暑温夹湿之热重于湿证","暑温初起之热重于湿证","湿温初起之湿重于热证","湿温初起之热重于湿证"],"a":3,"e":"该证为湿温初起、湿重于热，头痛恶寒、身重疼痛、肢体倦怠、胸闷不饥、午后身热、面色淡黄、苔白不渴、脉濡，湿邪重着、阻遏气机，三仁汤宣畅气机、清利湿热主之。A项湿热并重者咽痛颐肿、苔黄腻；B、C两项属暑温，起病急、热象著；E项湿温热重于湿者热势较盛、口渴苔黄，均不若湿重于热之苔白不渴、身重困倦"},{"q":"跌打损伤，筋断骨折之瘀血肿痛，刀伤出血，一切无名肿毒，烧伤烫伤者，治疗应选用的方剂是","o":["复元活血汤","黄土汤","槐花散","七厘散","归脾汤"],"a":3,"e":"七厘散活血散瘀、止血定痛，主治跌打损伤、筋断骨折之瘀血肿痛，刀伤出血、无名肿毒、烧伤烫伤，既可内服又可外用，散瘀止血并重。A项复元活血汤活血祛瘀、疏肝通络，主跌打损伤瘀血留于胁下；B项黄土汤温阳健脾、养血止血，主脾阳不足之远血；C项槐花散清肠止血，主肠风便血；E项归脾汤益气补血、健脾养心，主心脾两虚，均无散瘀止痛之效"},{"q":"患者四肢沉重疼痛，下肢浮肿，畏寒肢冷，小便不利，舌淡胖苔白滑，脉沉细。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":3,"e":"真武汤君附子温肾助阳化水，臣茯苓、白术健脾渗湿，佐生姜温散、白芍敛阴利水，主治脾肾阳虚水泛之四肢沉重、下肢浮肿、小便不利、畏寒肢冷、脉沉细。实脾散亦治阳虚水肿，但偏温脾行气，兼胸腹胀满便溏；五苓散为膀胱蓄水，口渴脉浮而无寒象；猪苓汤属水热互结伤阴，舌红脉细数"},{"q":"以发热、喘咳、苔黄、脉数为辨证要点的方剂是","o":["银翘散","麻黄杏仁甘草石膏汤","升麻葛根汤","柴葛解肌汤","桑菊饮"],"a":1,"e":"麻黄杏仁甘草石膏汤以麻黄宣肺平喘，石膏倍量清热，一宣一清，主治外感风邪、邪热壅肺之发热、喘咳、苔黄、脉数。银翘散主治风温初起、发热重恶寒轻、咽痛口渴，咳喘不显；桑菊饮重在疏风止咳，身热不甚；升麻葛根汤、柴葛解肌汤均为解肌透疹或和解之剂，无清热平喘之功"},{"q":"将药物加水反复煎煮，去渣浓缩后，加蜜或糖炼制而成的半液体剂型属","o":["酒剂","膏剂","茶剂","露剂","丹剂"],"a":1,"e":"膏剂系药物加水反复煎煮、去渣浓缩后加蜜或糖炼制成的半流体剂型，又称煎膏、膏方，滋补调制多用之。酒剂以酒浸药而成，可内服外用；茶剂为粗末或方块沸水冲泡；露剂为药材蒸馏所得芳香水溶液；丹剂多为汞硫等矿物药升炼而成，与此制法有别"},{"q":"治疗太阳风寒未解，入里化热，初犯阳明或三阳合病之常用方是","o":["升麻葛根汤","柴葛解肌汤","桑菊饮","银翘散","麻黄杏仁甘草石膏汤"],"a":1,"e":"柴葛解肌汤以柴胡、葛根解肌清热，配羌活、白芷、桔梗等，主治外感风寒、郁而化热、初犯阳明或三阳合病，症见恶寒渐轻、身热增盛、头痛肢楚、目疼鼻干。升麻葛根汤专于解肌透疹，主治麻疹初起；银翘散、桑菊饮为辛凉解表，无化热入里之机；麻杏甘石汤则清热平喘，主治邪热壅肺"},{"q":"患者类风湿性关节炎病史多年，现多关节疼痛，运动不利，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"独活寄生汤以独活祛下焦风寒湿邪，配细辛、秦艽、防风等，并伍四物、四君补气血、益肝肾，主治痹证日久、肝肾两虚、气血不足之关节疼痛、畏寒喜暖、舌淡苔白、脉细弱。羌活胜湿汤祛上部风湿，主治肩背痛；大秦艽汤养血祛风，主治风邪中络；九味羌活汤解表兼清里热，均无补益肝肾之功"},{"q":"患者肠痈日久，身无热，肌肤甲错，腹皮急，按之濡如肿状，脉数。首选治疗方剂是","o":["大黄牡丹汤","西黄丸","苇茎汤","阳和汤","薏苡附子败酱散"],"a":4,"e":"薏苡附子败酱散以薏苡仁排脓利湿，附子温阳散寒，败酱草清热解毒、消痈排脓，主治肠痈脓已成、身无热、肌肤甲错、腹皮急、按之濡、脉数。大黄牡丹汤主治肠痈初起、湿热瘀滞、腹痛拒按、脉滑数；阳和汤治阴疽漫肿无头、皮色不变；苇茎汤主治肺痈；西黄丸清热解毒、消肿散结，非肠痈专方"},{"q":"患者肢体筋脉疼痛，麻木拘挛，关节屈伸不利，疼痛游走不定。亦治中风，手足不仁，日久不愈，经络湿痰瘀血，而见腰腿沉重，或腿臂间作痛。治疗首选的方剂是","o":["羌活胜湿汤","小活络丹","独活寄生汤","大秦艽汤","九味羌活汤"],"a":1,"e":"小活络丹以川乌、草乌温经散寒止痛，胆南星燥湿化痰，乳香、没药活血化瘀，地龙通经活络，主治风寒湿痹与中风后手足不仁、经络湿痰瘀血之肢体疼痛麻木、关节屈伸不利、腰腿沉重。羌活胜湿汤治风湿在表之肩背腰脊痛；独活寄生汤补肝肾益气血；大秦艽汤养血祛风通络，均无化痰逐瘀通络之猛力"},{"q":"患者恶寒发热，头身疼痛，无汗，喘咳，痰涎清稀而量多，舌苔白滑，脉浮。治疗应自选的方剂是","o":["小青龙汤","香苏散","葱豉桔梗汤","败毒散","九味羌活汤"],"a":0,"e":"小青龙汤以麻黄、桂枝解表散寒，干姜、细辛温肺化饮，半夏燥湿化痰，五味子、白芍敛肺和营，主治外寒内饮之恶寒发热、无汗、喘咳、痰清稀量多、苔白滑、脉浮。九味羌活汤解表兼清里热，无化饮之功；香苏散疏肝理气；败毒散益气解表；葱豉桔梗汤辛凉解表，均不治寒饮咳喘"},{"q":"治疗中气虚弱，寒热互结，升降失常的基础方是","o":["生姜泻心汤","半夏泻心汤","甘草泻心汤","黄连汤","大黄附子汤"],"a":1,"e":"半夏泻心汤以半夏、干姜辛开散寒，黄连、黄芩苦降清热，人参、甘草、大枣补中，主治中气虚弱、寒热互结、升降失常之心下痞满、呕吐、肠鸣下利，为辛开苦降甘调之法。生姜泻心汤偏于和胃消痞、宣散水气，主治水热互结、干噫食臭；甘草泻心汤重在益胃，主治痞利俱甚；黄连汤主治胸中热、胃中有寒；大黄附子汤温下寒积"},{"q":"患者汗出恶风，小便不利，舌淡苔白，脉浮。治疗应首选的方剂是","o":["导赤散","防己黄芪汤","猪苓汤","五苓散","真武汤"],"a":1,"e":"防己黄芪汤以防己祛风利水，黄芪益气固表，白术健脾，甘草调和，主治表虚不固、风湿外袭之汗出恶风、小便不利、舌淡苔白、脉浮。五苓散化气利水，主治膀胱蓄水、口渴脉浮，无汗出恶风之表虚；真武汤温阳利水，主治阳虚水泛、畏寒肢冷、脉沉细；导赤散清心利水，治心火下移小肠；猪苓汤养阴利水，治水热伤阴"},{"q":"患者筋痿，阴汗，舌红苔黄腻，脉细数有力。治疗应首选的方剂是","o":["龙胆泻肝汤","知柏地黄丸","甘露消毒丹","六味地黄丸","当归六黄汤"],"a":0,"e":"龙胆泻肝汤以龙胆草清肝胆实火、利肝胆湿热，黄芩、栀子助清热，泽泻、木通、车前子利湿，当归、生地养血滋阴，主治肝胆湿热下注之筋痿、阴汗、舌红苔黄腻、脉细数有力。知柏地黄丸滋阴降火，主治阴虚火旺、潮热盗汗；六味地黄丸滋补肾阴；甘露消毒丹利湿化浊、清热解毒，治湿温时疫；当归六黄汤滋阴泻火、固表止汗，治盗汗"},{"q":"患者，女，25岁。因外出游玩，吹风后感冒1天。现怕风，发热，咳嗽咽痒，咯痰不爽，舌苔薄白，脉浮缓。可用下列何方加味治疗","o":["香苏散","九味羌活汤","败毒散","止嗽散","葱豉桔梗汤"],"a":3,"e":"止嗽散以荆芥疏风解表，桔梗、白前、紫菀、百部止咳化痰，陈皮理气，甘草调和，主治风邪犯肺之咳嗽咽痒、咯痰不爽、微恶风发热、苔薄白、脉浮缓，重在疏风宣肺止咳。香苏散理气解表；九味羌活汤解表胜湿兼清里热；败毒散益气解表；葱豉桔梗汤辛凉解表，均不专于止咳"},{"q":"患者反复泻利，甚至脱门坠下，伴有脐腹冷痛，喜温喜按，倦怠食少，舌淡苔白，脉迟细。治疗首选的方剂是","o":["四神丸","理中丸","真人养脏汤","桃花汤","补中益气汤"],"a":2,"e":"真人养脏汤以罂粟壳涩肠止泻，肉豆蔻、诃子助涩肠，人参、白术、甘草补气健脾，当归、白芍养血和血，肉桂温中，木香行气，主治久泻久痢、脾肾虚寒、肠失固摄之泻利、脱肛坠下、脐腹冷痛喜温喜按、脉迟细。四神丸温肾暖脾、涩肠止泻，主治五更泄泻；理中丸温中健脾；桃花汤温中涩肠，治虚寒痢便脓血；补中益气汤补气升提，治气虚下陷"},{"q":"患者，男，55岁。平素嗜酒。刻下眩晕呕吐，胸膈痞闷，食少体倦，小便不利，大便泄泻，舌苔腻，脉滑。治宜","o":["健脾丸","葛花解酲汤","木香槟榔丸","木香导滞丸","枳实消痞丸"],"a":1,"e":"葛花解酲汤以葛花解酒醒脾，配砂仁、蔻仁、木香等理气化湿，茯苓、泽泻、猪苓利湿，人参、白术、干姜温中健脾，主治酒积伤脾之眩晕呕吐、胸膈痞闷、食少体倦、小便不利、大便泄泻、苔腻脉滑。健脾丸健脾消食；枳实消痞丸消痞除满、健脾和胃；木香槟榔丸、木香导滞丸行气导滞、攻积泄热，均无解酒之功"},{"q":"患者虚劳干咳，咽燥咯血，肌肉消瘦，气短乏力，舌红少苔，脉细数。治疗宜首选的方剂是","o":["麦门冬汤","百合固金汤","养阴清肺汤","琼玉膏","清燥救肺汤"],"a":3,"e":"琼玉膏以生地黄滋阴养血，人参、茯苓益气健脾，蜂蜜润燥，共奏滋阴润肺、益气补中之功，主治虚劳干咳、咽燥咯血、肌肉消瘦、气短乏力、舌红少苔、脉细数。百合固金汤养阴润肺、化痰止咳，主治肺肾阴虚、咳嗽带血；麦门冬汤清养肺胃、降逆下气；养阴清肺汤养阴清肺解毒，治白喉；清燥救肺汤清燥润肺，治温燥伤肺"},{"q":"桑菊饮的辨证要点是","o":["咳嗽、发热不甚、微渴、脉浮数","发热、喘咳、苔黄、脉数","发热重、 恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪","发热、微恶寒、咽痛、口渴、脉浮数","疹发不出或出而不畅、舌红、脉数"],"a":0,"e":"桑菊饮疏风清热、宣肺止咳，主治风温初起、邪轻浅在肺卫，以咳嗽、身热不甚、微渴、脉浮数为辨证要点。发热、喘咳、苔黄、脉数为麻杏甘石汤之邪热壅肺；发热重恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪为柴葛解肌汤；发热、微恶寒、咽痛、口渴、脉浮数为银翘散；疹发不出、舌红脉数为升麻葛根汤"},{"q":"患者，女，53岁。患者痰多色白易咳，胸膈痞闷，恶心呕吐，肢体倦怠，舌苔白润，脉滑。选用何方为佳","o":["清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤","茯苓丸"],"a":3,"e":"二陈汤以半夏燥湿化痰、和胃降逆，陈皮理气行滞，茯苓健脾渗湿，甘草调和，主治湿痰证之痰多色白易咳、胸膈痞闷、恶心呕吐、肢体倦怠、苔白润、脉滑。清气化痰丸清热化痰，治痰热咳嗽、痰黄稠；贝母瓜蒌散润肺化痰，治燥痰；温胆汤理气化痰、清胆和胃，治胆郁痰扰之虚烦不眠；茯苓丸治痰停中脘之臂痛"},{"q":"患者，男，30岁。头晕伴耳鸣3周。头晕如坐舟车，口苦，耳鸣，小便可，大便干，舌红苔白腻，脉弦滑。治疗应首选的方剂是","o":["温胆汤加黄芩","定痫丸加白术","天麻钩藤饮加白术","镇肝熄风汤加黄芩","半夏白术天麻汤加黄芩"],"a":4,"e":"本证头晕如坐舟车、耳鸣、苔白腻、脉弦滑为风痰上扰清空，兼口苦、便干、舌红，故以半夏白术天麻汤化痰熄风、健脾祛湿，加黄芩清热。温胆汤理气化痰、清胆和胃，主治胆郁痰扰之心烦不眠、惊悸；定痫丸涤痰熄风、开窍定痫，主治癫痫发作；天麻钩藤饮平肝熄风、清热活血，主治肝阳上亢之头痛眩晕；镇肝熄风汤镇肝熄风，主治类中风"},{"q":"患者风湿热痹，身大热，关节肿痛等。治疗应首选的方剂是","o":["小活络丹","大活络丹","当归拈痛汤","白虎加桂枝汤","白虎加苍术汤"],"a":4,"e":"白虎加苍术汤以白虎汤清热生津，加苍术燥湿，主治风湿热痹、身大热、关节肿痛而湿邪偏重者。白虎加桂枝汤虽也治风湿热痹，但偏于通络止痛、主治温疟；小活络丹温经散寒、化痰逐瘀，主治风寒湿痹；大活络丹祛风止痛、舒筋活络，主治中风痹痛；当归拈痛汤利湿清热、疏风止痛，主治湿热痹阻、肢节烦痛"},{"q":"患者下痢脓血，赤多白少，腹痛里急后重，肛门灼热，渴欲饮水，舌红苔黄，脉弦数。治疗应首选的方剂是","o":["芍药汤","桃花汤","白头翁汤","黄连解毒汤","葛根黄芩黄连汤"],"a":2,"e":"白头翁汤以白头翁清热解毒、凉血止痢，黄连、黄柏清热燥湿、泻火解毒，秦皮收涩止痢，主治热毒壅滞大肠之痢下脓血、赤多白少、腹痛里急后重、肛门灼热、脉弦数。芍药汤清热燥湿、调气和血，主治湿热痢、赤白相兼；桃花汤温中涩肠，治虚寒痢；葛根芩连汤解表清热，治协热下利；黄连解毒汤泻火解毒，主治三焦火毒，无凉血止痢之功"},{"q":"有关服药时间，如病在上焦者宜","o":["食后服","临睡服","食前服","早上空腹服","不拘时服"],"a":0,"e":"服药时间依病位而定，病在上焦者宜食后服，使药力滞留上焦、缓缓吸收；病在下焦者宜食前服，使药力直达下焦。临睡服多治失眠、遗精等；早上空腹服常用于驱虫、泻下；不拘时服多为急症或呕吐者，均非上焦病所宜"},{"q":"患者胸中满痛彻背，背痛彻胸，不能安卧者，宜用","o":["丹参饮","瓜蒌薤白白酒汤","瓜蒌薤白半夏汤","枳实薤白桂枝汤","血府逐瘀汤"],"a":2,"e":"瓜蒌薤白半夏汤以瓜蒌、薤白通阳散结、行气祛痰，加半夏增强祛痰散结之力，主治胸痹痰饮壅盛、胸中满痛彻背、背痛彻胸、不能安卧。瓜蒌薤白白酒汤主治胸痹轻证、喘息咳唾、胸背痛；枳实薤白桂枝汤主治胸痹气结、胸满而痛、心中痞气；丹参饮活血行气止痛，治心胃诸痛；血府逐瘀汤活血化瘀，治胸中血瘀"},{"q":"患者遍身水肿，喘呼气急，烦躁口渴，二便不利，脉沉实。治疗应首选的方剂是","o":["小青龙汤","麻黄杏仁甘草石膏汤","疏凿饮子","防风通圣散","五积散"],"a":2,"e":"疏凿饮子以商陆、泽泻、赤小豆等泻水逐饮，配羌活、秦艽、腹皮等疏风除湿、行气利水，主治水气内停、表里俱实之遍身水肿、喘呼气急、烦躁口渴、二便不利、脉沉实，有上下分消、表里同治之效。五积散温中散寒、祛湿化痰；防风通圣散解表攻里；小青龙汤解表化饮；麻杏甘石汤清热平喘，均无逐水消肿之力"},{"q":"患者少腹拘急，小便自利，谵语烦渴，至夜发热，舌面瘀点，脉涩。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":2,"e":"桃核承气汤以桃仁破血行瘀，大黄泻热逐瘀，桂枝通行血脉，甘草调和，芒硝软坚，主治下焦蓄血、瘀热互结之少腹拘急、小便自利、谵语烦渴、至夜发热、舌有瘀点、脉涩。血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀；补阳还五汤补气活血，治中风气虚血瘀；清营汤清营解毒；清骨散清虚热，均无逐瘀泻热之功"},{"q":"患者胁肋疼痛，嘈杂吞酸，呕吐口苦，舌红苔黄，脉弦数。治疗应首选的方剂是","o":["左金丸","凉膈散","逍遥散","龙胆泻肝汤","黄连解毒汤"],"a":0,"e":"左金丸以黄连清泻肝火，少量吴茱萸疏肝和胃、引经并制黄连之寒，主治肝火犯胃之胁肋疼痛、嘈杂吞酸、呕吐口苦、舌红苔黄、脉弦数。龙胆泻肝汤清肝胆实火、利湿热，主治肝胆湿热；凉膈散泻火通便、清上泄下；逍遥散疏肝解郁、养血健脾；黄连解毒汤泻三焦火毒，均无和胃降逆制酸之用"},{"q":"患者神昏谵语，身热烦躁，喉中痰鸣，气息粗大，舌绛苔黄垢腻，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":2,"e":"至宝丹以麝香、冰片、安息香等芳香开窍，配犀角（水牛角）、牛黄、玳瑁清热解毒，主治痰热内闭心包之神昏谵语、身热烦躁、喉中痰鸣、气息粗大、舌绛苔黄垢腻，长于化浊开窍。安宫牛黄丸清热解毒之力最强，主治热闭心包、高热烦躁；紫雪长于熄风止痉；抱龙丸、紫金锭化痰开窍，力较逊"},{"q":"患者，女。平素月经滞后，行经时小腹疼痛，喜温喜按，入冬后手足生冻疮，肢冷畏寒，舌淡苔薄白，脉细迟。治宜选用","o":["四物汤","当归四逆汤","黄土汤","理中丸","小建中汤"],"a":1,"e":"当归四逆汤以当归养血和血，桂枝、芍药温经通脉，细辛助桂枝温经散寒，通草通经脉，大枣、甘草益气健脾，主治血虚寒厥之月经滞后、小腹冷痛喜温喜按、手足冻疮、肢冷畏寒、舌淡苔白、脉细迟。四物汤补血调血；黄土汤温阳健脾、养血止血，治便血崩漏；理中丸温中健脾；小建中汤温中补虚、缓急止痛，均无温经通脉之功"},{"q":"胁肋疼痛，吞酸吐苦，舌红少津，脉虚弦，治宜选用","o":["逍遥丸","四逆散","龙胆泻肝汤","小柴胡汤","一贯煎"],"a":4,"e":"一贯煎以生地黄滋阴养肝，枸杞子、沙参、麦冬、当归滋阴养血柔肝，川楝子疏肝泄热、行气止痛，主治肝肾阴虚、肝气不舒之胁肋疼痛、吞酸吐苦、舌红少津、脉虚弦。逍遥散疏肝解郁、养血健脾，主治肝郁血虚；四逆散透邪解郁、疏肝理脾；小柴胡汤和解少阳；龙胆泻肝汤清肝胆实火湿热，均非滋阴柔肝之剂"},{"q":"患者，男，47岁。头晕眼花，站立不稳，重者如乘船晕车，颈项僵硬不适。时伴恶心，呕吐，自觉胸闷，乏力，二便尚可，舌淡、体微胖边有齿痕、苔白，脉弦滑。治疗宜选的方剂是","o":["半夏白术天麻汤","镇肝熄风汤加钩藤、石决明、葛根","天麻钩藤饮加白术、葛根","天麻钩藤饮","半夏白术天麻汤加钩藤、石决明、葛根"],"a":4,"e":"本证头晕眼花、站立不稳、胸闷乏力、舌淡体胖边有齿痕、苔白、脉弦滑为风痰上扰，颈项僵硬故加葛根舒筋，加钩藤、石决明平肝熄风。天麻钩藤饮平肝熄风、清热活血，主治肝阳上亢之头痛眩晕；镇肝熄风汤镇肝熄风，主治气血上逆之中风；单纯半夏白术天麻汤无平肝舒筋之力"},{"q":"患者咳嗽，痰稠，痰中带血，咯吐不爽，心烦易怒，胸胁作痛，舌红苔黄，脉弦数，治宜选用","o":["咳血方","清气化痰丸","清燥救肺汤","泻白散","百合固金汤"],"a":0,"e":"咳血方以青黛、栀子清肝泻火，瓜蒌、海粉清化痰热，诃子敛肺止咳，主治肝火犯肺之咳嗽、痰稠带血、咯吐不爽、心烦易怒、胸胁作痛、舌红苔黄、脉弦数，重在清肝宁肺。清气化痰丸清热化痰，治痰热咳嗽；百合固金汤养阴润肺，治肺肾阴虚咳血；清燥救肺汤清燥润肺；泻白散清泻肺热，均无清肝宁血之功"},{"q":"患者小肠疝气，少腹痛引睾丸，舌淡，苔白，脉沉弦，宜用","o":["橘核丸","天台乌药散","吴茱萸汤","暖肝煎","枳实薤白桂枝汤"],"a":1,"e":"天台乌药散以乌药行气疏肝、散寒止痛，木香、小茴香、青皮等助行气散结，高良姜散寒，槟榔行气，川楝子、巴豆同炒去巴豆以减其寒而增行气，主治寒凝气滞之小肠疝气、少腹痛引睾丸、舌淡苔白、脉沉弦。橘核丸行气止痛、软坚散结，主治颓疝；暖肝煎温补肝肾、行气止痛，主治肝肾不足之疝气；吴茱萸汤温中补虚、降逆止呕；枳实薤白桂枝汤通阳散结，治胸痹"},{"q":"症见胆怯易惊，头眩心悸，心烦不眠，呕吐呃逆，癫痫，舌苔白腻，脉弦滑者。治宜选用","o":["温胆汤","清气化痰丸","定痫丸","酸枣仁汤","滚痰丸"],"a":0,"e":"温胆汤以半夏、陈皮、茯苓、甘草（二陈）理气化痰，枳实行气消痰，竹茹清热化痰、和胃止呕，主治胆郁痰扰之胆怯易惊、头眩心悸、心烦不眠、呕吐呃逆、癫痫、苔白腻、脉弦滑。清气化痰丸清热化痰，治痰热咳嗽；定痫丸涤痰熄风定痫，主治癫痫发作；酸枣仁汤养血安神、清热除烦，治虚烦不眠；滚痰丸攻逐顽痰，力峻"},{"q":"患者，三焦火毒热盛而见发斑，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["清营汤","黄芩汤","犀角地黄汤","清瘟败毒饮","黄连解毒汤"],"a":4,"e":"黄连解毒汤以黄连、黄芩、黄柏、栀子苦寒直折，泻三焦火毒，主治三焦火毒热盛之发斑、吐血衄血、身热、舌红苔黄、脉数有力。清瘟败毒饮气血两燔，主治大热渴饮、头痛如劈、发斑；犀角地黄汤清热解毒、凉血散瘀，主治热入血分、斑色紫黑；黄芩汤清热止利、和中止痛，治热痢；清营汤清营解毒，治热入营分、斑疹隐隐"},{"q":"患者心悸怔忡，失眠多梦，急躁易怒，入暮潮热，唇黯，舌黯红，脉紧涩。治疗应首选的方剂是","o":["失笑散","血府逐瘀汤","桃核承气汤","复元活血汤","生化汤"],"a":1,"e":"血府逐瘀汤以桃仁、红花、当归、川芎、赤芍活血化瘀，柴胡、枳壳、桔梗升降气机，牛膝引血下行，生地、甘草养血和中，主治胸中血瘀之心悸怔忡、失眠多梦、急躁易怒、入暮潮热、唇黯舌黯红、脉紧涩。失笑散活血祛瘀、散结止痛，治心腹刺痛；桃核承气汤逐瘀泻热，治下焦蓄血；复元活血汤治跌打瘀血胁痛；生化汤养血祛瘀，治产后瘀阻"},{"q":"患者呃逆不已，胸脘痞闷，舌淡苔白，脉沉迟，宜用","o":["橘皮竹茹汤","丁香柿蒂汤","旋覆代赭汤","藿香正气散","六君子汤"],"a":1,"e":"丁香柿蒂汤以丁香温胃散寒、降逆止呕，柿蒂降逆止呃，人参、生姜温中益气，主治胃寒气逆之呃逆不已、胸脘痞闷、舌淡苔白、脉沉迟。橘皮竹茹汤清热益气、降逆止呃，主治胃虚有热之呃逆；旋覆代赭汤降逆化痰、益气和胃，主治胃虚痰阻之心下痞硬、噫气不除；藿香正气散解表化湿、理气和中；六君子汤健脾益气、燥湿化痰"},{"q":"患者胁腹痞满，大便秘结，纳食减少，舌苔薄腻，脉弦，宜用","o":["五磨饮子","六磨饮子","枳实消痞丸","四磨汤","香砂六君子汤"],"a":1,"e":"六磨饮子以木香、乌药、沉香、槟榔、枳实、大黄（磨汁）行气导滞、通腑排便，主治气滞腑闭之胁腹痞满、大便秘结、纳食减少、苔薄腻、脉弦。五磨饮子行气降逆，主治气郁胸闷、暴怒气厥，无通便之力；四磨汤行气降逆、宽胸散结；枳实消痞丸消痞除满、健脾和胃；香砂六君子汤健脾益气、理气和胃，均非气秘之剂"},{"q":"患者男，50岁，恶寒发热伴水肿1周，西医诊断急性肾小球肾炎，现身体疼痛，无汗，舌苔薄白，脉浮紧。可用下列何方加味治疗","o":["桂枝汤","麻黄汤","败毒散","大青龙汤","小青龙汤"],"a":1,"e":"麻黄汤以麻黄发汗解表、宣肺平喘，桂枝助其解肌，杏仁降肺气，甘草调和，主治风寒表实之恶寒发热、无汗、身体疼痛、脉浮紧；风水相搏、肺气闭郁之水肿无汗亦可用之，取其宣肺发汗、通调水道。桂枝汤解肌发表、调和营卫，主治汗出脉浮缓；大青龙汤发汗力峻，兼清里热，治不汗出而烦躁；败毒散益气解表；小青龙汤解表化饮，治寒饮咳喘"},{"q":"患者痛经，月经前少腹胀痛，胀甚于痛，连及胸胁、乳房胀痛，舌淡，苔薄白，脉弦紧，宜用","o":["橘核丸","天台乌药散","加味乌药汤","暖肝煎","枳实薤白桂枝汤"],"a":2,"e":"加味乌药汤以乌药、砂仁、木香、延胡索等行气活血、调经止痛，香附疏肝理气，甘草调和，主治气滞血瘀之经前少腹胀痛、胀甚于痛、连及胸胁乳房胀痛、脉弦紧。橘核丸、天台乌药散、暖肝煎均治寒疝；枳实薤白桂枝汤通阳散结，治胸痹，皆非痛经所宜"},{"q":"以恶寒发热，无汗，喘咳，痰多而稀，舌苔白滑，脉浮为辨证要点的方剂是","o":["葱豉桔梗汤","香苏散","败毒散","九味羌活汤","小青龙汤"],"a":4,"e":"本方为解表化饮之剂，以恶寒发热、无汗、喘咳、痰多而稀、舌苔白滑、脉浮为辨证要点，属外寒内饮。不汗出而烦躁、脉浮紧为大青龙汤；恶风发热汗出脉浮缓为桂枝汤；无汗而喘、脉浮紧为麻黄汤；肢体酸楚疼痛、口苦微渴为九味羌活汤"},{"q":"患者胃火牙痛。治疗应首选的方剂是","o":["玉女煎","左金丸","清胃散","白虎汤","凉膈散"],"a":2,"e":"清胃散以黄连清胃府之火，升麻升散解毒、引经，生地、丹皮凉血，当归养血和血，主治胃火上炎之牙痛、面颊发热、齿喜冷恶热、舌红苔黄、脉滑数。玉女煎清胃滋阴，主治胃热阴虚之牙痛、烦热干渴；左金丸清肝和胃，治肝火犯胃；白虎汤清气分大热；凉膈散泻火通便，治上中二焦邪热"},{"q":"患者暴饮暴食之后，又复受凉，淬然心腹胀痛，痛如锥刺，气急口噤，大便不通。宜选用的方剂是","o":["大陷胸汤","大承气汤","温脾汤","大黄附子汤","三物备急丸"],"a":4,"e":"三物备急丸以大黄、干姜、巴豆（巴豆霜）相伍，巴豆辛热峻下、攻逐寒积，干姜温中散寒，大黄泻下通便，主治寒食冷积、卒然心腹胀痛、痛如锥刺、气急口噤、大便不通之急症。大承气汤峻下热结，治热积便秘；温脾汤温补脾阳、攻下冷积，偏于虚寒；大黄附子汤温下寒积，治胁腹疼痛便秘；大陷胸汤泻热逐水，治结胸"},{"q":"患者，女，60岁。腹痛便秘，畏寒肢冷，手足不温，苔白腻，脉弦紧。医生用大黄附子汤治疗，方中的君药是","o":["干姜","大黄","附子","细辛","人参"],"a":2,"e":"大黄附子汤主治寒积里实之腹痛便秘、畏寒肢冷、脉弦紧，方中附子大辛大热，温经散寒、助阳通便，为君药；大黄苦寒泻下通便，借附子之热以去其寒性而存其泻下之用，为臣；细辛助附子温经散寒，为佐。干姜、人参非本方所有；大黄虽泻下，但非温散寒凝之主药，故不为君"},{"q":"患者发热，恶寒甚剧，其寒不解，神疲欲寐，脉沉微。治疗应首选的方剂是","o":["四逆汤","回阳救急汤","再造散","参附汤","麻黄附子细辛汤"],"a":4,"e":"麻黄附子细辛汤以麻黄解表散寒，附子温经助阳，细辛助麻黄解表、助附子温里，主治素体阳虚、外感风寒之发热、恶寒甚剧、其寒不解、神疲欲寐、脉沉微，为温和之剂。四逆汤、回阳救急汤、参附汤均回阳救逆，主治阳虚欲脱、脉微欲绝，无解表之功；再造散助阳益气解表，主治阳气虚弱、外感风寒，但力量较峻且配伍复杂"},{"q":"配伍特点为重用甘寒，补中寓清；心肾并治，重在养心的方剂是","o":["朱砂安神丸","桂枝甘草龙骨牡蛎汤","天王补心丹","酸枣仁汤","甘麦大枣汤"],"a":2,"e":"天王补心丹以生地黄为君，重用甘寒滋阴养血，配麦冬、天冬、玄参等滋阴清热，人参、茯苓、当归等益气养血安神，柏子仁、酸枣仁、远志养心安神，桔梗载药上行，主治阴虚血少、心肾不交之虚烦心悸、失眠多梦，故曰补中寓清、心肾并治而重在养心。朱砂安神丸镇心安神、清热养血，重在镇坠；酸枣仁汤养血安神、清热除烦；甘麦大枣汤养心安神、和中缓急"},{"q":"患者咳嗽气喘，呼多吸少，声音低怯，痰稠色黄，或咳吐脓血，胸中烦热，身体羸瘦，或遍身浮肿，脉浮虚，治疗宜用的方剂是","o":["异功散","胶艾汤","玉屏风散","生脉散","人参蛤蚧散"],"a":4,"e":"人参蛤蚧散以蛤蚧补肺益肾、纳气定喘，人参、茯苓、甘草、杏仁、贝母等补气健脾、化痰止咳，知母、桑白皮清泻肺热，主治肺肾气虚、痰热内蕴之咳嗽气喘、呼多吸少、声音低怯、痰稠色黄或咳吐脓血、身体羸瘦、脉浮虚。异功散健脾益气、理气和胃；玉屏风散益气固表止汗；生脉散益气养阴、敛汗生脉；胶艾汤养血止血，均无固定喘之功"},{"q":"患者，女，31岁。因洗澡后受凉3天，现咳嗽，口渴，脉浮数。可用以下何方加减治疗","o":["银翘散","升麻葛根汤","麻黄杏仁甘草石膏汤","柴葛解肌汤","桑菊饮"],"a":4,"e":"桑菊饮以桑叶、菊花轻清宣透、疏风清热，杏仁、桔梗宣肺止咳，连翘清热，薄荷疏风，芦根清热生津，主治风温初起、风邪犯肺之咳嗽、口渴、脉浮数，且咳嗽较著而身热不甚。银翘散辛凉透表、清热解毒，主治发热重、咽痛明显；麻杏甘石汤清热平喘，治邪热壅肺；柴葛解肌汤解肌清热；升麻葛根汤解肌透疹"},{"q":"患者大便不通6天，兼见频转矢气，脘腹痞满，腹痛拒按，手足濈然汗出，舌苔黄燥，脉沉实。医生主张用“釜底抽薪，急下存阴”治法，方剂是","o":["大陷胸汤","大承气汤","十枣汤","麻子仁丸","三物备急丸"],"a":1,"e":"大承气汤以大黄泻热通便、芒硝软坚润燥、厚朴行气除满、枳实消痞，峻下热结，主治阳明腑实之大便不通、频转矢气、脘腹痞满、腹痛拒按、手足濈然汗出、苔黄燥、脉沉实，体现釜底抽薪、急下存阴。大陷胸汤泻热逐水，治结胸；十枣汤攻逐水饮；麻子仁丸润肠泄热，治脾约便秘；三物备急丸攻逐寒积"},{"q":"患者半身不遂，口眼歪斜，口角流涎，遗尿失禁，舌黯淡，苔白，脉缓无力。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":1,"e":"补阳还五汤重用黄芪大补元气，配当归尾、赤芍、川芎、桃仁、红花、地龙活血化瘀通络，主治中风后气虚血瘀之半身不遂、口眼歪斜、口角流涎、遗尿失禁、舌黯淡苔白、脉缓无力。血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀；桃核承气汤逐瘀泻热，治下焦蓄血；清营汤清营解毒；清骨散清虚热，均非补气通络之剂"},{"q":"患者，三焦火毒热盛而见吐血、衄血，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["黄连解毒汤","犀角地黄汤","清瘟败毒饮","普济消毒饮","仙方活命饮"],"a":0,"e":"黄连解毒汤以黄连、黄芩、黄柏、栀子合用，苦寒直折三焦火毒，主治三焦火毒热盛之吐血、衄血、身热、舌红苔黄、脉数有力。犀角地黄汤清热解毒、凉血散瘀，主治热入血分、斑疹、吐衄；清瘟败毒饮气血两燔；普济消毒饮清热解毒、疏风散邪，主治大头瘟；仙方活命饮清热解毒、消肿溃坚，主治疮疡初起"},{"q":"患者胃脘灼热隐痛，饥不欲食，口干咽燥，大便干结，舌红少津，脉细数。治疗宜首选的方剂是","o":["麦门冬汤","益胃汤","养阴清肺汤","清燥救肺汤","玉液汤"],"a":1,"e":"益胃汤以沙参、麦冬、生地、玉竹滋阴养胃，冰糖润燥，主治胃阴不足之胃脘灼热隐痛、饥不欲食、口干咽燥、大便干结、舌红少津、脉细数。麦门冬汤清养肺胃、降逆下气，主治肺胃阴虚、气逆呕吐；养阴清肺汤养阴清肺解毒，治白喉；清燥救肺汤清燥润肺；玉液汤益气滋阴、固肾止渴，治消渴"},{"q":"患者痰涎壅盛，喉中痰声辘辘，气闭不通，心神瞀闷，四肢不收，或倒仆不省，或口角似㖞，脉滑实有力。治疗应首选的方剂是","o":["二陈汤","救急稀涎散","镇肝熄风汤","羚角钩藤汤","大承气汤"],"a":1,"e":"救急稀涎散以皂角、白矾涌吐痰涎，主治痰涎壅盛、喉中痰声辘辘、气闭不通、心神瞀闷、四肢不收、倒仆不省、脉滑实有力之闭证急救，取其高者因而越之之意。二陈汤燥湿化痰、理气和中，治湿痰咳嗽；镇肝熄风汤镇肝熄风，治类中风；羚角钩藤汤凉肝熄风，治热极生风；大承气汤峻下热结，均无涌吐开闭之功"},{"q":"患者高热不退，烦闷躁扰，手足抽搐，发为痉厥，甚则神昏，舌质绛而干，或舌焦起刺，脉弦数。治疗首选的方剂是","o":["天麻钩藤饮","镇肝熄风汤","羚角钩藤汤","大定风珠","大秦艽汤"],"a":2,"e":"羚角钩藤汤以羚羊角、钩藤凉肝熄风、清热解痉，桑叶、菊花清热，生地、白芍、甘草养阴柔肝，贝母、竹茹清热化痰，茯苓安神，主治热盛生风之高热不退、烦闷躁扰、手足抽搐、痉厥神昏、舌绛而干、脉弦数。天麻钩藤饮平肝熄风、清热活血，治肝阳上亢；镇肝熄风汤镇肝熄风，治类中风；大定风珠滋阴熄风，治阴虚风动；大秦艽汤养血祛风，治中风手足不仁"},{"q":"患者浮肿身半以下为甚，胸腹胀满，平素带下量多色白、稍稠，舌淡苔白腻，脉沉迟。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":4,"e":"实脾散以附子、干姜温养脾肾、助阳化水，白术、茯苓健脾渗湿，厚朴、木香、槟榔、草果行气导滞，木瓜化湿，甘草调和，主治脾肾阳虚、水气内停之阴水，症见身半以下肿甚、胸腹胀满、带下量多色白、舌淡苔白腻、脉沉迟。真武汤温阳利水，主治阳虚水泛、四肢沉重疼痛、小便不利；苓桂术甘汤温阳化饮、健脾利湿，治中阳不足之痰饮；五苓散、猪苓汤均无温阳行气之功"},{"q":"患者牙痛牵引头痛，面颊发热，其齿喜冷恶热，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["左金丸","清胃散","玉女煎","普济消毒饮","清瘟败毒饮"],"a":1,"e":"清胃散以黄连清胃火，升麻升散解毒引经，生地、丹皮凉血，当归和血，主治胃火牙痛、牵引头痛、面颊发热、齿喜冷恶热、苔黄脉滑数。玉女煎清胃滋阴，治胃热阴虚牙痛；左金丸清肝和胃；普济消毒饮清热解毒、疏风散邪，治大头瘟；清瘟败毒饮气血两燔，均非胃火牙痛专剂"},{"q":"患者，女，67岁。右上肺癌术后1年余。现咳嗽痰多，呈白色泡沫状，胸闷气短，双侧胸背持续性隐痛，以右侧为甚，舌淡苔白滑，脉弦滑。治疗应首选的方剂是","o":["苏子降气汤","小青龙汤","贝母瓜蒌散","苓甘五味姜辛汤","百合固金汤"],"a":3,"e":"苓甘五味姜辛汤以干姜、细辛温肺散寒化饮，茯苓健脾渗湿，五味子敛肺止咳，甘草调和，主治寒饮内停肺胃之咳嗽、痰多清稀呈泡沫状、胸闷气短、舌淡苔白滑、脉弦滑。苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳；小青龙汤解表化饮，治外寒内饮；贝母瓜蒌散润肺化痰，治燥痰；百合固金汤养阴润肺，治肺肾阴虚"},{"q":"患者大便秘结，脘腹胀满，腹痛拒按，身热口渴，神倦少气，谵语，神昏肢厥，舌苔焦黑，脉虚。治疗应首选方剂是","o":["大承气汤","小承气汤","黄龙汤","安宫牛黄丸","至宝丹"],"a":2,"e":"黄龙汤即大承气汤加人参、当归、甘草、桔梗，泻热通便兼益气养血，主治阳明腑实、气血不足之大便秘结、腹痛拒按、身热口渴、神昏谵语、神倦少气、肢厥、苔焦黑、脉虚，体现攻补兼施。大承气汤、小承气汤单纯攻下，无补益之力；安宫牛黄丸、至宝丹清热开窍，治热闭神昏，均无通腑之功"},{"q":"患者婚后久不孕育，全身痩削，阳痿遗精，两目昏花，腰膝酸软，治疗宜用的方剂是","o":["左归丸","肾气丸","右归丸","龟鹿二仙胶","六味地黄丸"],"a":3,"e":"龟鹿二仙胶以龟板滋阴潜阳、益肾健骨，鹿角胶温肾壮阳、益精血，人参补气，枸杞子滋阴益精，共奏滋阴填精、益气壮阳之功，主治真元虚损、精血不足之久不孕育、形体消瘦、阳痿遗精、两目昏花、腰膝酸软。左归丸、右归丸、肾气丸、六味地黄丸或滋阴、或温阳，均不能阴阳精血并补而兼益气"},{"q":"患者突然鼻衄，血色鲜红，舌红，脉数，治宜选用","o":["咳血方","十灰散","槐花散","小蓟饮子","导赤散"],"a":1,"e":"十灰散以大蓟、小蓟、荷叶、侧柏叶、白茅根等凉血止血，棕榈炭、栀子、大黄、丹皮等清热凉血、化瘀止血，诸药烧灰存性，主治血热妄行之突然鼻衄、血色鲜红、舌红脉数。咳血方清肝宁肺，治肝火犯肺咳血；槐花散清肠止血，治肠风脏毒下血；小蓟饮子凉血止血、利尿通淋，治血淋；导赤散清心利水，治心火下移"},{"q":"患者恶寒发热，无汗，头痛项强，肢体酸楚疼痛，口苦微渴，舌苔微黄，脉浮紧。治疗应首选的方剂是","o":["桂枝汤","小青龙汤","大青龙汤","败毒散","九味羌活汤"],"a":4,"e":"九味羌活汤以羌活解表胜湿，防风、苍术助祛风胜湿，细辛、白芷、川芎祛风散寒止痛，黄芩、生地清里热，甘草调和，主治外感风寒湿邪、内有蕴热之恶寒发热、无汗、头痛项强、肢体酸楚疼痛、口苦微渴、苔微黄、脉浮紧。麻黄汤辛温发汗，无胜湿清里之功；大青龙汤发汗清热，治不汗出而烦躁；桂枝汤治汗出脉缓；败毒散益气解表"},{"q":"患者小便不利，身热心烦，口渴欲饮，舌红苔微黄，脉细数。治疗应首选的方剂是","o":["蒿芩清胆汤","真武汤","五苓散","六一散","猪苓汤"],"a":4,"e":"猪苓汤以猪苓、茯苓、泽泻利水渗湿，滑石清热利水，阿胶滋阴润燥，主治水热互结、邪热伤阴之小便不利、身热心烦、口渴欲饮、舌红苔微黄、脉细数，利水而不伤阴。五苓散温阳化气利水，主治膀胱蓄水、苔白脉浮；真武汤温阳利水，治阳虚水泛；六一散清暑利湿，治暑湿；蒿芩清胆汤清胆利湿、和胃化痰，治少阳湿热"},{"q":"以心悸失眠，体倦食少，便血或崩漏，舌淡，脉细弱为证治要点的方剂是","o":["补中益气汤","归脾汤","四物汤","胶艾汤","当归补血汤"],"a":1,"e":"归脾汤以人参、黄芪、白术、甘草益气健脾，当归、龙眼肉养血安神，酸枣仁、远志、茯苓宁心安神，木香理气醒脾，主治心脾两虚、气血不足之心悸怔忡、失眠多梦、体倦食少、便血或崩漏、舌淡脉细弱。补中益气汤补中益气、升阳举陷，治气虚下陷；四物汤补血调血；胶艾汤养血止血、调经安胎；当归补血汤补气生血，治血虚发热"},{"q":"患者头晕目眩，目胀耳鸣，脑部热痛，面色如醉，心中烦热，或时常噫气，或肢体渐觉不利，口眼渐形斜；甚或眩晕颠仆，昏不知人，移时始醒；或醒后不能复原，脉弦长有力。治疗首选的方剂是","o":["大秦艽汤","天麻钩藤饮","羚角钩藤汤","大定风珠","镇肝熄风汤"],"a":4,"e":"镇肝熄风汤以怀牛膝引血下行，代赭石、龙骨、牡蛎镇肝潜阳，龟板、白芍、玄参、天冬滋阴柔肝清热，川楝子、茵陈、麦芽疏肝泄热，甘草调和，主治肝阳上亢、气血上逆之类中风，症见头晕目眩、目胀耳鸣、脑部热痛、面色如醉、噫气、肢体不利、口眼㖞斜、脉弦长有力。天麻钩藤饮平肝熄风、清热活血，主治肝阳上亢轻证；羚角钩藤汤凉肝熄风，治热极生风；大定风珠滋阴熄风；大秦艽汤养血祛风通络"},{"q":"患者壮热面赤，烦渴引饮，汗出恶热，脉洪大有力。治疗应首选的方剂是","o":["败毒散","白虎汤","银翘散","黄连解毒汤","甘露消毒丹"],"a":1,"e":"白虎汤以石膏清气分大热，知母滋阴润燥，粳米、甘草益胃生津，主治气分热盛之壮热面赤、烦渴引饮、汗出恶热、脉洪大有力。败毒散益气解表；银翘散辛凉解表，治风温初起；黄连解毒汤泻三焦火毒；甘露消毒丹利湿化浊、清热解毒，治湿温，均无清气分大热之功"},{"q":"患者上吐下泻，胸脘痞闷，舌苔黄腻，脉濡数。治疗应首选的治法是","o":["利水渗湿，理气和中","清热解毒，理气和中","利湿化浊，理气和中","清热化湿，理气和中","清热泻火，理气和中"],"a":3,"e":"上吐下泻、胸脘痞闷、苔黄腻、脉濡数为湿热蕴结中焦、升降失常，治宜清热化湿、理气和中，方如葛根芩连汤合藿香正气之类。利水渗湿、理气和中偏治湿盛于热；清热解毒、理气和中偏重热毒；利湿化浊、理气和中偏治湿温初起湿重于热；清热泻火、理气和中偏重实火，均无化湿与清热并举之贴切"},{"q":"以发热，微恶寒，咽痛，口渴，脉浮数为辨证要点的方剂是","o":["银翘散","柴葛解肌汤","麻黄杏仁甘草石膏汤","桑菊饮","升麻葛根汤"],"a":0,"e":"银翘散辛凉透表、清热解毒，主治风温初起、邪在肺卫，以发热、微恶寒、咽痛、口渴、脉浮数为辨证要点。柴葛解肌汤解肌清热，治三阳合病；麻杏甘石汤清热平喘，治邪热壅肺；桑菊饮疏风止咳，以咳嗽为主、热象较轻；升麻葛根汤解肌透疹，治麻疹初起"},{"q":"患者疹发不出，身热头痛，咳嗽，目赤流泪，口渴，舌红，苔薄而干，脉浮数。治疗宜首选的方剂是","o":["柴葛解肌汤","银翘散","升麻葛根汤","桑菊饮","麻黄杏仁甘草石膏汤"],"a":2,"e":"升麻葛根汤以升麻、葛根解肌透疹，芍药养血和营，甘草调和，主治麻疹初起、疹发不出或出不畅、身热头痛、咳嗽、目赤流泪、口渴、舌红苔薄而干、脉浮数。银翘散辛凉解表，治风温初起；桑菊饮疏风止咳；柴葛解肌汤解肌清热，治三阳合病；麻杏甘石汤清热平喘，均无透疹之功"},{"q":"患者骨蒸潮热，肌肉消瘦，唇红颊赤，气粗困倦，舌红少苔，脉细数。治疗应首选的方剂是","o":["清骨散","凉膈散","六味地黄丸","知柏地黄丸","秦艽鳖甲散"],"a":4,"e":"秦艽鳖甲散以鳖甲、知母滋阴清热，秦艽、柴胡祛风退热，地骨皮、青蒿清虚热，当归养血，主治风劳、阴虚内热之骨蒸潮热、肌肉消瘦、唇红颊赤、气粗困倦、舌红少苔、脉细数。清骨散专清虚热、退骨蒸；知柏地黄丸滋阴降火；六味地黄丸滋补肾阴；凉膈散泻火通便，均无祛风退蒸、治肌肉消瘦之功"},{"q":"患者心下痞鞕，噫气不除，舌质淡，苔白滑，脉弦而虚，宜用","o":["六君子汤","半夏泻心汤","枳实消痞丸","旋覆代赭汤","丁香柿蒂汤"],"a":3,"e":"旋覆代赭汤以旋覆花消痰下气、降逆止噫，代赭石重镇降逆，人参、甘草、大枣、生姜益气和胃，半夏化痰散结，主治胃虚痰阻、气逆不降之心下痞鞕、噫气不除、苔白滑、脉弦而虚。半夏泻心汤寒热平调、消痞散结，治心下痞、呕吐下利；枳实消痞丸消痞除满、健脾和胃；丁香柿蒂汤温中降逆，治胃寒呃逆；六君子汤健脾化痰，均非噫气不除之主方"},{"q":"据“疗寒以热，而佐以寒”而用之寒药属于","o":["君药","佐药","引经药","臣药","调和药"],"a":1,"e":"方剂配伍中，佐药有三义：佐助药助君臣药加强疗效，佐制药制约君臣药之毒性烈性，反佐药即疗寒以热而佐以寒，或疗热以寒而佐以热，于大寒大热剂中少佐相反药性之品以防拒药，此寒药即属反佐药。君药针对主病主证；臣药助君药或治兼证；引经药引诸药直达病所；调和药调和诸药，皆非此义"},{"q":"患者小便频数，小腹急满，溺时涩痛，尿色浑赤，淋沥不畅，甚则癃闭不通，口燥咽干，舌苔黄腻，脉滑数。治疗应首选的治法是","o":["清热化瘀，利水通淋","清热解暑，利水通淋","清热排石，利水通淋","清热泻火，利水通淋","清热凉血，利水通淋"],"a":3,"e":"小便频数、小腹急满、溺时涩痛、尿色浑赤、淋沥不畅、口燥咽干、苔黄腻、脉滑数为湿热下注膀胱之热淋，治宜清热泻火、利水通淋，方如八正散。清热化瘀、利水通淋用于血淋瘀阻；清热解暑、利水通淋用于暑湿；清热排石、利水通淋用于石淋；清热凉血、利水通淋用于血淋，均非本证正治"},{"q":"患者热入血分证而见便血，喜忘如狂，漱水不欲咽，舌深绛起刺，脉数。治疗应首选的方剂是","o":["普济消毒饮","清瘟败毒饮","犀角地黄汤","青蒿鳖甲汤","黄连解毒汤"],"a":2,"e":"犀角地黄汤以水牛角清热解毒、凉血，生地凉血养阴，赤芍、丹皮凉血散瘀，主治热入血分、迫血妄行之便血、喜忘如狂、漱水不欲咽、舌深绛起刺、脉数，体现入血就恐耗血动血、直须凉血散血。清瘟败毒饮气血两燔；普济消毒饮治大头瘟；青蒿鳖甲汤养阴透热，治温病后期；黄连解毒汤泻三焦火毒，均无凉血散瘀之功"},{"q":"患者消化不良，面黄形瘦，肚腹胀大，口臭发热，舌苔黄腻。治疗应首选的方剂是","o":["保和丸","健脾丸","枳实导滞丸","乌梅丸","肥儿丸"],"a":4,"e":"肥儿丸以神曲、麦芽、山楂消食化积，使君子、槟榔杀虫消积，黄连、胡黄连清热，白术、茯苓健脾，木香理气，主治小儿疳积、消化不良、面黄形瘦、肚腹胀大、口臭发热、苔黄腻。保和丸消食和胃，治食积；健脾丸健脾消食，治脾虚食积；枳实导滞丸消积导滞、清热利湿，治湿热食积；乌梅丸温脏安蛔，治蛔厥"},{"q":"患者长期从事鱼丸制作工作，每年秋冬季节出现双手诸关节疼痛，屈伸不利，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"独活寄生汤以独活祛风湿、止痹痛，细辛、秦艽、防风、肉桂温经散寒，桑寄生、杜仲、牛膝补肝肾强筋骨，四物、四君益气养血，主治痹证日久、肝肾气血不足之关节疼痛、屈伸不利、畏寒喜暖、舌淡苔白、脉细弱。羌活胜湿汤祛上部风湿；肾著汤温中胜湿，治寒湿腰痛；大秦艽汤、九味羌活汤均无补益肝肾气血之功"},{"q":"患者咽中如有物阻，咯吐不出，吞咽不下，舌苔白腻，脉弦滑，宜选用","o":["二陈汤","平胃散","瓜蒌薤白白酒汤","半夏泻心汤","半夏厚朴汤"],"a":4,"e":"半夏厚朴汤以半夏化痰散结、降逆和胃，厚朴下气除满，茯苓渗湿健脾，生姜和胃，苏叶芳香行气、疏肝解郁，主治痰气郁结之梅核气，症见咽中如有物阻、咯吐不出、吞咽不下、苔白腻、脉弦滑。二陈汤燥湿化痰，治湿痰咳嗽；平胃散燥湿运脾、行气和胃，治湿滞脾胃；瓜蒌薤白白酒汤通阳散结，治胸痹；半夏泻心汤寒热平调，治心下痞"},{"q":"患者身热，下利臭秽，胸脘烦热，口干作渴，喘而汗出，舌红苔黄，脉数。治疗应首选的方剂是","o":["败毒散","大承气汤","芍药汤","香薷散","葛根黄芩黄连汤"],"a":4,"e":"葛根黄芩黄连汤以葛根解肌升阳、止泻，黄芩、黄连清热燥湿止痢，甘草调和，主治外感表证未解、热邪入里之身热、下利臭秽、胸脘烦热、口干作渴、喘而汗出、舌红苔黄、脉数。大承气汤峻下热结；芍药汤清热燥湿、调气和血，治湿热痢；败毒散益气解表；香薷散祛暑解表、化湿和中，治阴暑，均无解肌清热止利之功"},{"q":"患者瘿瘤肿硬，皮色不变。首选治疗方剂是","o":["仙方活命饮","阳和汤","大黄牡丹汤","海藻玉壶汤","苇茎汤"],"a":3,"e":"海藻玉壶汤以海藻、昆布、海带化痰软坚散结，贝母、半夏、连翘、青皮、陈皮等化痰理气散结，当归、川芎、甘草养血和中，主治气滞痰凝之瘿瘤、肿硬、皮色不变。仙方活命饮清热解毒、消肿溃坚，治疮疡阳证；阳和汤温阳补血、散寒通滞，治阴疽；大黄牡丹汤治肠痈；苇茎汤治肺痈，均非瘿瘤专方"},{"q":"跌打损伤，瘀留腋下，痛不可忍，治宜选方","o":["血府逐瘀汤","桃红四物汤","温经汤","复元活血汤","柴胡疏肝散"],"a":3,"e":"复元活血汤以柴胡疏肝引经，大黄、桃仁、红花、当归、川芎活血化瘀，天花粉、甘草清热养血，穿山甲通络散结，主治跌打损伤、瘀血留于胁下、痛不可忍。血府逐瘀汤治胸中血瘀；桃红四物汤活血调经；温经汤温经散寒、养血祛瘀，治冲任虚寒瘀阻；柴胡疏肝散疏肝理气止痛，均无活血疗伤、引经胁下之力"},{"q":"患者心下至少腹硬满疼痛而痛不可近，大便秘结，日晡潮热，舌燥而渴，脉沉紧，按之有力。医生开出的方剂是大陷胸汤，下列煎服法不正确的是","o":["芒硝溶服","冲服甘遂末","水煎服","先煮大黄","清晨空腹服"],"a":4,"e":"大陷胸汤煎服法为先煮大黄，后纳芒硝溶服，甘遂末冲服，水煎温服，取下燥屎为度；清晨空腹服为十枣汤等攻逐水饮剂的服法，借空腹使药力峻攻而不留滞，并非大陷胸汤所宜。芒硝溶服、冲服甘遂末、先煮大黄均为本方正确煎服法，水煎服亦无误"},{"q":"患者，男，21岁。脑外伤3个月后，突然摔倒伴四肢抽搐，口吐白沫，意识不清，醒后头晕，乏力。现症见急躁易怒，夜寐多梦，脘胀纳减，痰多色黄，舌质晦红，苔白厚腻，脉弦滑。治疗应首选","o":["血府逐瘀汤加减","半夏白术天麻汤加减","定痫丸加减","天麻钩藤饮加减","镇肝熄风汤加减"],"a":2,"e":"定痫丸以天麻、钩藤、全蝎、僵蚕等熄风止痉，胆南星、半夏、竹沥、贝母等化痰，朱砂、琥珀等镇心安神，主治痰热内闭、风痰上扰之癫痫突然昏倒、四肢抽搐、口吐白沫、急躁易怒、痰多色黄、苔腻脉弦滑。半夏白术天麻汤化痰熄风，治风痰眩晕；天麻钩藤饮平肝熄风；镇肝熄风汤镇肝熄风；血府逐瘀汤活血化瘀，均无定痫开窍之功"},{"q":"患者，男，44岁。脘腹拘急时痛，喜温喜按3年余，面色无华，神疲乏力，心悸气短，手足烦热，咽干口燥，舌淡苔白，脉弦细。宜选择下列哪方治疗","o":["吴茱萸汤","小建中汤","当归四逆汤","四逆汤","大建中汤"],"a":1,"e":"小建中汤以桂枝、白芍调和营卫、温中缓急，饴糖温中补虚、缓急止痛，生姜、大枣、甘草和中，主治中焦虚寒、肝脾不和之脘腹拘急时痛、喜温喜按、面色无华、神疲乏力、心悸气短、手足烦热、咽干口燥、脉弦细。吴茱萸汤温中补虚、降逆止呕；当归四逆汤温经通脉；四逆汤回阳救逆；大建中汤温中补虚、降逆止痛，主治中阳衰弱、阴寒内盛之心腹大痛，力更峻"},{"q":"患者疮疡初起，红肿焮痛，身热凛寒，苔薄白，脉数有力。首选治疗方剂是","o":["五味消毒饮","仙方活命饮","黄连解毒汤","四妙勇安汤","普济消毒饮"],"a":1,"e":"仙方活命饮以白芷、防风、贝母、花粉等疏风清热、化痰散结，当归尾、赤芍、乳香、没药、穿山甲活血消肿、通络溃坚，金银花、甘草清热解毒，皂角刺消肿排脓，主治疮疡阳证初起、红肿焮痛、身热凛寒、脉数有力，有疮疡之圣药之称。五味消毒饮清热解毒，治疔疮；黄连解毒汤泻火解毒；四妙勇安汤清热解毒、活血止痛，治脱疽；普济消毒饮治大头瘟"},{"q":"以恶寒发热，头痛无汗，胸脘痞闷，苔薄白，脉浮为辨证要点的方剂是","o":["葱豉桔梗汤","败毒散","九味羌活汤","小青龙汤","香苏散"],"a":4,"e":"香苏散以香附疏肝理气，紫苏叶解表散寒，陈皮理气和中，甘草调和，主治外感风寒、内有气滞之恶寒发热、头痛无汗、胸脘痞闷、苔薄白、脉浮。葱豉桔梗汤辛凉解表；败毒散益气解表；九味羌活汤解表胜湿兼清里热；小青龙汤解表化饮，均无理气宽中之功"},{"q":"患者有慢性前列腺炎病史，近期小便混浊，状如膏糊，排尿涩痛，舌淡苔白，脉沉。治疗应首选的方剂是","o":["导赤散","小蓟饮子","萆薢分清饮","八正散","猪苓汤"],"a":2,"e":"萆薢分清饮以萆薢利湿去浊、分辨清浊，石菖蒲化浊开窍，益智仁温肾缩尿，乌药温肾行气，茯苓、甘草利湿和中，主治肾虚湿浊下注之膏淋、白浊，症见小便混浊如膏糊、排尿涩痛、舌淡苔白、脉沉。导赤散清心利水，治心火下移；小蓟饮子凉血止血、利尿通淋，治血淋；八正散清热利水通淋，治热淋；猪苓汤养阴利水，治水热伤阴"},{"q":"患者尿频尿急，溺时涩痛，淋沥不畅，舌苔黄腻，脉滑数。治疗应首选的方剂是","o":["石韦散","导赤散","八正散","六一散","小蓟饮子"],"a":2,"e":"八正散以车前子、瞿麦、萹蓄、滑石、木通、栀子、大黄等清热利水通淋，甘草梢调和，灯心草引火下行，主治湿热下注膀胱之热淋，症见尿频尿急、溺时涩痛、淋沥不畅、苔黄腻、脉滑数。石韦散清热利湿、排石通淋，治石淋；导赤散清心利水；六一散清暑利湿；小蓟饮子凉血止血、利尿通淋，治血淋，均非热淋通利之主方"},{"q":"患者往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，口苦，咽干，目眩，舌苔薄白，脉弦。治疗宜首选的方剂是","o":["半夏泻心汤","龙胆泻肝汤","小柴胡汤","参苓白术散","逍遥散"],"a":2,"e":"小柴胡汤以柴胡透泄少阳之邪，黄芩清少阳之热，半夏、生姜和胃降逆，人参、甘草、大枣扶正祛邪，主治伤寒少阳证之往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕、口苦咽干目眩、苔薄白、脉弦。半夏泻心汤寒热平调，治心下痞；龙胆泻肝汤清肝胆实火湿热；参苓白术散健脾渗湿止泻；逍遥散疏肝解郁、养血健脾，均无和解少阳之功"},{"q":"孙某，女，50岁。便秘腹痛，绕脐绞痛不止，手足不温，苔白不渴，脉沉弦而迟。医生选用具有攻下冷积、温补脾阳功用的方剂治疗，该方是","o":["温脾汤","大黄附子汤","五仁丸","三物备急丸","麻子仁丸"],"a":0,"e":"温脾汤以附子、干姜温补脾阳、散寒，大黄攻下冷积，人参、甘草益气健脾，当归养血，主治阳虚寒积之便秘腹痛、绕脐绞痛、手足不温、苔白不渴、脉沉弦而迟，功效攻下冷积、温补脾阳。大黄附子汤温下寒积，无补脾之功；三物备急丸峻下寒积，主治急症；五仁丸、麻子仁丸润肠通便，治肠燥便秘，均无温阳攻下之力"},{"q":"患者身热多汗，心胸烦闷，气逆欲呕，口干喜饮，虚羸少气，舌红苔少，脉虚数等。治疗应首选的方剂是","o":["白虎汤","竹叶石膏汤","清暑益气汤","白虎加人参汤","白虎加桂枝汤"],"a":1,"e":"竹叶石膏汤以竹叶、石膏清热生津，人参、麦冬、半夏益气养阴、和胃降逆，粳米、甘草益胃和中，主治伤寒、温病后期、余热未清、气津两伤之身热多汗、心胸烦闷、气逆欲呕、口干喜饮、虚羸少气、舌红苔少、脉虚数。白虎汤清气分大热；白虎加人参汤清热益气生津，主治大热大汗、脉洪大而虚；清暑益气汤清暑益气、养阴生津，治暑热气津两伤；白虎加桂枝汤治温疟"},{"q":"患者患处漫肿无头，皮色不变，酸痛无热，口中不渴，舌淡苔白，脉沉细。首选治疗方剂是","o":["仙方活命饮","普济消毒饮","阳和汤","大黄牡丹汤","小金丹"],"a":2,"e":"阳和汤以熟地黄、鹿角胶温阳补血，肉桂、姜炭温经散寒，麻黄、白芥子通阳散结、祛痰通络，生甘草调和，主治阴疽、贴骨疽、流注等患处漫肿无头、皮色不变、酸痛无热、口中不渴、舌淡苔白、脉沉细。仙方活命饮治阳证疮疡；普济消毒饮治大头瘟；大黄牡丹汤治肠痈；小金丹化痰祛瘀、解毒消肿，治阴疽初起，但非本证首选"},{"q":"患者，女，56岁。平素怕风，现感冒1天，症见恶风，发热，体温38、5℃，出汗，头痛，食后欲呕，苔白，脉浮缓。可用下列何方加味治疗","o":["大青龙汤","败毒散","麻黄汤","桂枝汤","小青龙汤"],"a":3,"e":"桂枝汤以桂枝解肌发表、温通卫阳，白芍敛阴和营，生姜、大枣调和营卫，甘草调和，主治外感风寒、营卫不和之恶风发热、汗出、头痛、脉浮缓，服后啜热稀粥以助药力。麻黄汤发汗解表，治无汗脉浮紧；大青龙汤发汗清热；败毒散益气解表；小青龙汤解表化饮，均无调和营卫、治汗出恶风之功"},{"q":"患者，女。平素月经量少，周期延长，有时四五十天才月经来潮，入冬后，手、足及耳部多处发生冻疮，肢冷畏寒，舌淡苔薄白，脉细迟。治宜选用","o":["四逆汤","四逆散","小建中汤","当归四逆汤","桂枝人参汤"],"a":3,"e":"当归四逆汤以当归养血和血，桂枝、芍药调和营卫、温经通脉，细辛温经散寒，通草通经脉，大枣、甘草益气健脾，主治血虚寒厥之月经量少、周期延长、手足耳部冻疮、肢冷畏寒、舌淡苔薄白、脉细迟。四逆汤回阳救逆，治阳虚欲脱；四逆散透邪解郁、疏肝理脾；小建中汤温中补虚；桂枝人参汤温中解表，均无养血温经通脉之功"},{"q":"患者突然昏倒，牙关紧闭，不省人事，苔白脉迟，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","苏合香丸","抱龙丸","紫金锭"],"a":2,"e":"苏合香丸以苏合香、麝香、冰片、安息香等芳香开窍，配檀香、沉香、丁香、木香等行气温中，主治寒邪、痰浊内闭之突然昏倒、牙关紧闭、不省人事、苔白脉迟，为温开之剂。安宫牛黄丸、紫雪、至宝丹均为凉开三宝，主治热闭神昏、身热烦躁；抱龙丸、紫金锭化痰开窍，力弱，均非寒闭所宜"},{"q":"产后血虚，复感风寒，恶露不行，少腹冷痛，治宜选方","o":["温经汤","四物汤","归脾汤","生化汤","逍遥散"],"a":3,"e":"生化汤以当归养血活血，川芎行气活血，桃仁活血祛瘀，炮姜温经散寒，炙甘草调和，黄酒助药力，主治产后血虚受寒、恶露不行、少腹冷痛，有产后必用之称。温经汤温经散寒、养血祛瘀，治冲任虚寒、瘀血阻滞之月经不调；四物汤补血调血；归脾汤益气补血、健脾养心；逍遥散疏肝解郁，均无温经化瘀、专治产后恶露之功"},{"q":"患者，男，正值夏季高温时节，患暑热病而见身大热属于气津两伤者。治疗应首选的方剂是","o":["白虎加人参汤","竹叶石膏汤","当归六黄汤","清暑益气汤","桂苓甘露饮"],"a":0,"e":"白虎加人参汤以白虎汤清气分大热，加人参益气生津，主治暑热病、身大热、大汗出、大烦渴、脉洪大而气津两伤者。竹叶石膏汤清余热、益气血，主治病后余热未清；当归六黄汤滋阴泻火、固表止汗，治盗汗；清暑益气汤清暑益气、养阴生津，治暑热伤气津但热势较缓；桂苓甘露饮清暑化气、利水除湿，治暑湿"},{"q":"患者肢节烦痛，肩背沉得，或脚气肿痛，苔白腻微黄，脉濡数。主治病证是","o":["湿热相搏，外受暑邪证","湿热相搏，外受疫邪证","湿热相搏，外受风邪证","湿热相搏，外受寒邪证","湿热相搏，外受燥邪证"],"a":2,"e":"肢节烦痛、肩背沉重、脚气肿痛、苔白腻微黄、脉濡数为风湿热邪相搏、外受风邪，属当归拈痛汤主治病证。湿热相搏外受暑邪多见身热烦渴、胸闷；外受疫邪多见高热神昏、斑疹；外受寒邪多见肢节冷痛、脉紧；外受燥邪多见口鼻干燥、干咳，均无肢节沉重肿痛、苔腻脉濡之风湿相搏之象"},{"q":"患者素体肺肾阴虚，复感疫毒，出现白喉，宜首选的方剂是","o":["清燥救肺汤","百合固金汤","玉液汤","养阴清肺汤","麦门冬汤"],"a":3,"e":"养阴清肺汤以生地、麦冬、玄参、贝母、白芍、甘草、薄荷、丹皮滋阴清肺、解毒利咽，主治肺肾阴虚、复感疫毒之白喉，症见咽痛、喉间白膜、不易擦去、发热口干、脉细数。百合固金汤养阴润肺、化痰止咳，治肺肾阴虚咳嗽；清燥救肺汤清燥润肺；玉液汤益气滋阴、固肾止渴，治消渴；麦门冬汤清养肺胃、降逆下气"},{"q":"患者舌强不能言，足废不能用，口干不欲饮，足冷面赤，脉沉细弱，治疗宜用的方剂是","o":["左归丸","右归丸","大补阴丸","肾气丸","地黄饮子"],"a":4,"e":"地黄饮子以熟地、山萸肉、石斛、麦冬、五味子滋阴，附子、肉桂、巴戟天、肉苁蓉温阳，石菖蒲、远志、茯苓化痰开窍，薄荷引药上行，主治下元虚衰、虚阳上浮、痰浊上泛之瘖痱，症见舌强不能言、足废不能用、口干不欲饮、足冷面赤、脉沉细弱。左归丸、右归丸、肾气丸或滋阴、或温阳、或阴阳双补，均无化痰开窍治舌强不语之功；大补阴丸滋阴降火"},{"q":"下列何种病证可使用麻黄汤","o":["尿血而伴恶寒发热无汗，头身疼痛，脉浮紧者","鼻出血而伴恶寒发热无汗，头身疼痛，脉浮紧者","疮疡反复发作伴恶寒发热无汗，头身疼痛，脉浮紧者","咳血而伴恶寒发热无汗，头身疼痛，脉浮紧者","疮疡初起伴恶寒发热无汗，头身疼痛，脉浮紧者"],"a":4,"e":"麻黄汤发汗解表、宣肺平喘，主治风寒表实证；疮疡初起兼有恶寒发热、无汗、头身疼痛、脉浮紧之风寒表证者，可用麻黄汤疏表散寒，使邪从汗解，表解则疮疡易消。尿血、鼻出血、咳血皆属出血证，麻黄辛温升散，用之可助火动血；疮疡反复发作多属正虚邪恋，均非麻黄汤所宜"},{"q":"患者心悸不安，痛如针刺而有定处，舌质黯红，脉紧。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":3,"e":"血府逐瘀汤以桃仁、红花、当归、川芎、赤芍活血化瘀，柴胡、枳壳、桔梗调畅气机，牛膝引血下行，生地、甘草养血和中，主治胸中血瘀之心悸不安、痛如针刺而有定处、舌质黯红、脉紧涩。桃核承气汤逐瘀泻热，治下焦蓄血；补阳还五汤补气活血，治中风；清营汤清营解毒；清骨散清虚热，均无宽胸行气活血之功"},{"q":"患者三焦火毒热盛证而见有身热下利，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["黄芩汤","小承气汤","普济消毒饮","黄连解毒汤","清瘟败毒饮"],"a":3,"e":"黄连解毒汤以黄连、黄芩、黄柏、栀子苦寒直折，泻三焦火毒，主治三焦火毒热盛之身热下利、舌红苔黄、脉数有力。黄芩汤清热止利、和中止痛，治太阳少阳合病下利；小承气汤轻下热结，治阳明腑实轻证；普济消毒饮清热解毒、疏风散邪，治大头瘟；清瘟败毒饮气血两燔，均非三焦火毒直折之主方"},{"q":"患者身重肢肿，关节疼痛，汗出恶风，小便不利，苔白脉浮。主治病证是","o":["肺虚之风水","里虚之风水","肾虚之风水","脾虚之风水","表虚之风水"],"a":4,"e":"身重肢肿、关节疼痛、汗出恶风、小便不利、苔白脉浮为风水相搏、表虚不固，属防己黄芪汤主治之表虚风水。肺虚之风水多兼咳喘；里虚之风水病在里、脉沉；肾虚之风水兼腰膝酸冷；脾虚之风水兼纳呆便溏，均无汗出恶风、脉浮之表虚特征"},{"q":"患者头痛目赤，胁痛，口苦，舌红苔黄，脉弦数有力。治疗应首选的方剂是","o":["凉膈散","银翘散","左金丸","逍遥散","龙胆泻肝汤"],"a":4,"e":"龙胆泻肝汤以龙胆草清肝胆实火、利肝胆湿热，黄芩、栀子助清热，泽泻、木通、车前子利湿，当归、生地养血滋阴，柴胡引经，甘草调和，主治肝胆实火上炎之头痛目赤、胁痛口苦、舌红苔黄、脉弦数有力。左金丸清肝和胃，治肝火犯胃之呕酸；凉膈散泻火通便；银翘散辛凉解表；逍遥散疏肝解郁，均非清肝胆实火之主方"},{"q":"患者遍身肢节烦痛，肩背沉重，脚膝生疮，苔白腻微黄，脉数。治疗应首选的治法是","o":["利湿清热，疏风止痛","利湿清热，通络止痛","利湿清热，祛瘀止痛","利湿清热，散寒止痛","利湿清热，理气止痛"],"a":0,"e":"遍身肢节烦痛、肩背沉重、脚膝生疮、苔白腻微黄、脉数为风湿热邪相搏、外受风邪，治宜利湿清热、疏风止痛，方如当归拈痛汤。利湿清热、通络止痛偏于瘀阻经络；利湿清热、祛瘀止痛用于瘀血阻络；利湿清热、散寒止痛用于寒湿；利湿清热、理气止痛用于气滞，均无疏风祛邪之针对性"},{"q":"症见月经不调，小腹冷痛，经血夹有瘀块，时有烦热，舌质黯红，脉细涩。治应首选","o":["温经汤","四物汤","归脾汤","生化汤","逍遥散"],"a":0,"e":"温经汤以吴茱萸、桂枝温经散寒、通利血脉，当归、川芎、芍药、丹皮养血活血，人参、甘草、生姜益气和中，阿胶、麦冬养阴润燥，半夏通降，主治冲任虚寒、瘀血阻滞之月经不调、小腹冷痛、经血夹瘀块、时有烦热、舌黯红、脉细涩。四物汤补血调血；生化汤治产后瘀阻；归脾汤益气养血；逍遥散疏肝解郁，均无温经散寒祛瘀之功"},{"q":"小青龙汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":4,"e":"小青龙汤为解表化饮之主方，以恶寒发热、无汗、喘咳、痰多而稀、舌苔白滑、脉浮为辨证要点，属外寒内饮。不汗出而烦躁、脉浮紧为大青龙汤；恶风发热汗出脉浮缓为桂枝汤；恶寒发热无汗而喘脉浮紧为麻黄汤；肢体酸楚疼痛、口苦微渴为九味羌活汤"},{"q":"患儿，男，12岁。患癫痫6年。发则突然昏倒，不省人事，面色初潮红，继青紫，甚苍白，牙关紧闭，肢体抽搐，口吐涎沫，并作尖叫，数分钟后苏醒，舌苔白腻微黄，脉弦滑略数。治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","羚角钩藤汤","定痫丸","镇肝熄风汤"],"a":3,"e":"定痫丸以天麻、全蝎、僵蚕、蜈蚣等熄风止痉，胆南星、半夏、陈皮、茯苓、贝母、竹沥等化痰，辰砂、琥珀、远志、石菖蒲镇心安神开窍，麦冬、甘草调和，主治风痰上扰、痰热内闭之癫痫，症见突然昏倒、四肢抽搐、口吐白沫、尖叫、苔白腻微黄、脉弦滑略数。安宫牛黄丸、紫雪清热开窍，治热闭神昏；羚角钩藤汤凉肝熄风；镇肝熄风汤镇肝熄风，均无涤痰定痫之功"},{"q":"患者，男，51岁。证见脘腹痞满胀痛，赤白痢疾，里急后重，舌苔黄腻，脉沉实。治宜","o":["保和丸","葛花解酲汤","枳实导滞丸","木香槟榔丸","芍药汤"],"a":3,"e":"木香槟榔丸以木香、槟榔、青皮、陈皮、香附、莪术等行气导滞，大黄、牵牛子、芒硝攻积泄热，黄连、黄柏清热燥湿，主治积滞内停、湿热下痢之脘腹痞满胀痛、赤白痢疾、里急后重、苔黄腻、脉沉实。枳实导滞丸消积导滞、清热利湿，治湿热食积；保和丸消食和胃；葛花解酲汤解酒醒脾；芍药汤清热燥湿、调气和血，治湿热痢"},{"q":"患者胸痛，饮水即呛，干呕，易躁易怒，两目黯黑，舌质黯红，舌有瘀斑，脉紧。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":3,"e":"血府逐瘀汤以桃仁、红花、当归、川芎、赤芍活血化瘀，柴胡、枳壳、桔梗宽胸行气，牛膝引血下行，生地、甘草养血和中，主治胸中血瘀之胸痛、饮水即呛、干呕、易怒、两目黯黑、舌质黯红有瘀斑、脉紧。桃核承气汤逐瘀泻热，治下焦蓄血；补阳还五汤补气活血，治中风；清营汤清营解毒；清骨散清虚热，均无宽胸行气、治胸中瘀血之功"},{"q":"患者久泻不愈，腹痛喜温，腰痠肢冷，神疲乏力，舌淡，苔薄白，脉沉迟无力。治疗首先的方剂是","o":["四神丸","桃花汤","肾气丸","理中丸","真人养脏汤"],"a":0,"e":"四神丸以补骨脂温补肾阳、暖脾止泻，肉豆蔻温中涩肠，吴茱萸温中散寒，五味子敛肠止泻，生姜、大枣温中和胃，主治脾肾阳虚之五更泄泻、久泻不愈、腹痛喜温、腰痠肢冷、神疲乏力、舌淡苔薄白、脉沉迟无力。真人养脏汤涩肠固脱、温补脾肾，主治久泻久痢、脱肛；桃花汤温中涩肠，治虚寒痢；理中丸温中健脾；肾气丸温补肾阳，均无暖脾涩肠止五更泻之专功"},{"q":"以下哪一项不属“七方”的内容","o":["大方","小方","急方","复方","单方"],"a":4,"e":"七方出自《素问·至真要大论》，指大方、小方、缓方、急方、奇方、偶方、复方七种配伍组方之法，是早期方剂分类理论。复方属七方之一，指两方或数方合用；单方指单味药成方，不在七方之列；大方、小方以药味多少、剂量大小分；急方、缓方以药力峻缓、服用缓急分"},{"q":"患者龚某，腹中时痛，喜温喜按，面色无华，心悸不宁，手足烦热，咽干口燥，舌淡苔白，脉细弦而缓。治宜选用","o":["大建中汤","小建中汤","吴茱萸汤","理中汤","温脾汤"],"a":1,"e":"小建中汤以桂枝、白芍调和营卫、缓急止痛，饴糖温中补虚，生姜、大枣、甘草和中，主治中焦虚寒、肝脾不和之腹中时痛、喜温喜按、面色无华、心悸不宁、手足烦热、咽干口燥、舌淡苔白、脉细弦而缓。大建中汤温中补虚、降逆止痛，主治中阳衰弱、阴寒内盛之心腹大痛；吴茱萸汤温中降逆；理中汤温中健脾；温脾汤攻下冷积，均非缓急止痛之主方"},{"q":"患者大便秘结，口渴，舌干红，脉细数。治疗宜首选的方剂是","o":["增液承气汤","增液汤","调胃承气汤","麻子仁丸","玉液汤"],"a":1,"e":"增液汤以玄参、麦冬、生地滋阴润燥、增液润下，主治阳明温病、津亏便秘之大便秘结、口渴、舌干红、脉细数，体现增水行舟之法。增液承气汤增液泻下，主治热结阴亏、燥屎不行；调胃承气汤泻热和胃，治阳明腑实轻证；麻子仁丸润肠泄热，治脾约便秘；玉液汤益气滋阴止渴，治消渴"},{"q":"患者心胸烦热，口渴面赤，意欲冷饮，口舌生疮，舌红脉数。治疗应首选的方剂是","o":["清营汤","败毒散","白虎汤","导赤散","玉女煎"],"a":3,"e":"导赤散以生地凉血滋阴，木通清心利水，竹叶清心除烦，甘草梢调和，主治心经有热、心火上炎之心胸烦热、口渴面赤、意欲冷饮、口舌生疮、舌红脉数，或心火下移小肠之小便赤涩。清营汤清营解毒，治热入营分；白虎汤清气分大热；败毒散益气解表；玉女煎清胃滋阴，均无清心利水之功"},{"q":"以咳嗽咽痒，微恶风发热，苔薄白为辨证要点的方剂是","o":["九味羌活汤","败毒散","止嗽散","葱豉桔梗汤","香苏散"],"a":2,"e":"止嗽散疏风宣肺、止咳化痰，主治风邪犯肺之咳嗽咽痒、微恶风发热、苔薄白，重在疏风止咳，温而不燥。九味羌活汤解表胜湿兼清里热；败毒散益气解表；葱豉桔梗汤辛凉解表；香苏散理气解表，均不专于止咳"},{"q":"患者大便秘结，下后两三日，复见便秘，脉沉无力。主治方剂是","o":["小承气汤","调味承气汤","增液汤","增液承气汤","玉液汤"],"a":2,"e":"增液汤以玄参、麦冬、生地增液润燥，主治热病后津亏肠燥之大便秘结、下后两三日复见便秘、脉沉无力，取增水行舟之意。小承气汤、调胃承气汤均以大黄攻下，治热结便秘，无养阴增液之功；增液承气汤增液与攻下并用，主治热结阴亏较重者；玉液汤益气滋阴止渴，治消渴"},{"q":"患者恶风发热，汗出头痛，鼻鸣干呕，苔白不渴，脉浮缓。治疗应首选的方剂是","o":["大青龙汤","桂枝汤","麻黄汤","小青龙汤","败毒散"],"a":1,"e":"桂枝汤以桂枝解肌发表、温通卫阳，白芍敛阴和营，生姜、大枣调和营卫，甘草调和，主治外感风寒、营卫不和之恶风发热、汗出头痛、鼻鸣干呕、苔白不渴、脉浮缓。大青龙汤发汗清热，治不汗出而烦躁；麻黄汤发汗平喘，治无汗脉紧；小青龙汤解表化饮；败毒散益气解表，均无调和营卫、治汗出恶风之功"},{"q":"患者恶寒发热，脘腹疼痛，呕吐泄泻，舌苔白腻，脉濡。本证的病机是","o":["风寒在表，水饮内停","风寒在表，湿滞脾胃","风寒在表，内有蕴热","风热在表，湿滞脾胃","风湿在表，内有蕴热"],"a":1,"e":"恶寒发热为风寒在表，脘腹疼痛、呕吐泄泻、舌苔白腻、脉濡为湿滞脾胃、升降失常，本证属外感风寒、内伤湿滞，方如藿香正气散。风寒在表、水饮内停多见咳喘痰饮；风寒在表、内有蕴热多见口渴烦躁；风热在表、湿滞脾胃多见发热重、咽痛；风湿在表、内有蕴热多见肢节烦痛、苔黄，均与本证不符"},{"q":"患者发烧多日，大便不通，神昏谵语，手足冰凉并有汗出，舌苔黄燥起刺，脉沉实。宜选用的方剂是","o":["四逆散","四逆汤","当归四逆汤","大承气汤","温脾汤"],"a":3,"e":"大承气汤以大黄、芒硝、厚朴、枳实峻下热结，主治阳明腑实、热结旁流之发烧多日、大便不通、神昏谵语、手足厥冷而汗出、舌苔黄燥起刺、脉沉实，属热厥，治宜寒因寒用，釜底抽薪。四逆散透邪解郁，治阳郁厥逆；四逆汤回阳救逆，治阳虚厥逆；当归四逆汤温经通脉，治血虚寒厥；温脾汤攻下冷积，均无峻下热结之功"},{"q":"体虚卫外不固，又复心阳不潜之自汗盗汗，治宜首选","o":["玉屏风散","补中益气汤","四君子汤","牡蛎散","炙甘草汤"],"a":3,"e":"牡蛎散以煅牡蛎敛阴潜阳、固表止汗，黄芪益气固表，麻黄根专于止汗，小麦养心阴、益心气，主治体虚卫外不固、心阳不潜之自汗盗汗、心悸气短、舌淡脉虚。玉屏风散益气固表止汗，主治表虚自汗、易感风邪；补中益气汤补中升阳，治气虚发热自汗；四君子汤益气健脾；炙甘草汤益气养阴、通阳复脉，治心动悸脉结代，均无潜阳敛汗之功"},{"q":"患者心胸刺痛，脘腹疼痛，治宜选方","o":["桃核承气汤","血府逐瘀汤","失笑散","槐花散","导赤散"],"a":2,"e":"失笑散以五灵脂、蒲黄活血祛瘀、散结止痛，主治瘀血内停之心胸刺痛、脘腹疼痛、痛经、产后腹痛，痛如针刺而有定处。血府逐瘀汤活血化瘀、宽胸行气，治胸中血瘀；桃核承气汤逐瘀泻热，治下焦蓄血；槐花散清肠止血，治肠风下血；导赤散清心利水，均无专门的活血止痛之功"},{"q":"患者肢节沉重肿痛，苔白腻微黄，脉濡数。治疗应首选的方剂是","o":["羌活胜湿汤","独活寄生汤","当归拈痛汤","五皮散","甘露消毒丹"],"a":2,"e":"当归拈痛汤以羌活、防风、升麻、葛根疏风胜湿，茵陈、黄芩、苦参、知母清热燥湿，泽泻、猪苓、茯苓利水渗湿，当归、人参、白术、甘草养血益气健脾，主治湿热相搏、外受风邪之肢节沉重肿痛、肩背沉重、脚膝生疮、苔白腻微黄、脉濡数。羌活胜湿汤祛风湿止痛，治风湿在表；独活寄生汤补肝肾益气血；五皮散利水消肿；甘露消毒丹利湿化浊，均无疏风清热利湿并用之功"},{"q":"患者呕吐，口渴咽干，舌红少苔，脉虚数。治疗应首选的方剂是","o":["麦门冬汤","琼玉膏","益胃汤","增液汤","玉液汤"],"a":0,"e":"麦门冬汤以麦冬滋养肺胃之阴，半夏降逆下气、化痰散结，人参、甘草、粳米、大枣益气养胃生津，主治肺胃阴虚、气逆不降之呕吐、口渴咽干、舌红少苔、脉虚数，及虚热肺痿、咳嗽气逆。琼玉膏滋阴润肺，治虚劳干咳；益胃汤养胃阴，治胃脘隐痛饥不欲食；增液汤增液润下，治便秘；玉液汤益气滋阴止渴，治消渴"},{"q":"症见咳嗽痰多，色白易咳，胸膈痞闷，恶心呕吐，肢体困重，舌苔白滑，脉滑者。治宜选用","o":["茯苓丸","温胆汤","小陷胸汤","二陈汤","苓甘五味姜辛汤"],"a":3,"e":"二陈汤以半夏燥湿化痰、和胃降逆，陈皮理气化痰，茯苓健脾渗湿，甘草调和，主治湿痰证之咳嗽痰多、色白易咳、胸膈痞闷、恶心呕吐、肢体困重、苔白滑、脉滑。温胆汤理气化痰、清胆和胃，治胆郁痰扰；小陷胸汤清热化痰、宽胸散结，治痰热结胸；茯苓丸治痰停中脘；苓甘五味姜辛汤温肺化饮，治寒饮咳嗽"},{"q":"以恶寒重，发热轻，神疲欲寐，脉沉为辨证要点的方剂是","o":["大青龙汤","麻黄附子细辛汤","再造散","败毒散","参苏饮"],"a":1,"e":"本方以麻黄解表、附子温阳、细辛通窍，主治素体阳虚、外感风寒之少阴表证，以恶寒重、发热轻、神疲欲寐、脉沉为辨证要点。大青龙汤发汗清热，治不汗出而烦躁；再造散助阳益气解表，主治阳气虚弱、外感风寒较重；败毒散益气解表，治气虚外感；参苏饮益气解表、理气化痰，治气虚外感风寒、内有痰湿"},{"q":"患者头痛，眩晕，失眠，舌红苔黄，脉弦数。治疗首选的方剂是","o":["半夏白术天麻汤","大定风珠","羚角钩藤汤","天麻钩藤饮","镇肝熄风汤"],"a":3,"e":"天麻钩藤饮以天麻、钩藤平肝熄风，石决明平肝潜阳，栀子、黄芩清热，牛膝引血下行，杜仲、桑寄生补肝肾，茯神、夜交藤安神，益母草活血，主治肝阳上亢、肝风上扰之头痛、眩晕、失眠、舌红苔黄、脉弦数。半夏白术天麻汤化痰熄风，治风痰眩晕；大定风珠滋阴熄风；羚角钩藤汤凉肝熄风，治热极生风；镇肝熄风汤镇肝熄风，治气血上逆之中风"},{"q":"患者发热口渴，肢酸倦怠，胸闷腹胀，舌苔白腻，脉滑数。本证的病机是","o":["湿热疫毒，蕴于下焦","湿热疫毒，蕴于中焦","湿热疫毒，蕴于上焦","湿热疫毒，蕴于气分","湿热疫毒，蕴于血分"],"a":3,"e":"发热口渴、肢酸倦怠、胸闷腹胀、苔白腻、脉滑数为湿热疫毒蕴结气分、气机阻滞，属甘露消毒丹主治之湿温时疫。湿热疫毒蕴于下焦多见小便淋涩、痢疾；蕴于中焦多见脘痞呕恶、便溏；蕴于上焦多见胸闷咽痛、咳嗽；蕴于血分多见斑疹、出血、神昏，均非气分湿热之见症"},{"q":"患者胃气不和，心下痞满不痛，呕吐或肠鸣下利，舌苔腻而微黄。治疗应首选的方剂是","o":["小柴胡汤","痛泻要方","理中丸","半夏泻心汤","芍药汤"],"a":3,"e":"半夏泻心汤以半夏、干姜辛开散寒，黄连、黄芩苦降清热，人参、甘草、大枣补中益气，主治胃气不和、寒热互结、升降失常之心下痞满不痛、呕吐、肠鸣下利、苔腻微黄。小柴胡汤和解少阳，治往来寒热；痛泻要方补脾柔肝、祛湿止泻，治痛泻；理中丸温中健脾；芍药汤清热燥湿、调气和血，治湿热痢，均无辛开苦降消痞之功"}];
